INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('degrees-of-excellence', 'Islamic', 'Degrees of Excellence', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('degrees-of-excellence', 'كتاب إثبات الإمامة', 'ar', 'theology', '<p>In the Name of God, this book undertakes a single task, and its original title names that task exactly. <em>Kitab ithbat al-imama</em> means the demonstration of the imamate — <em>ithbat</em> being the establishing of a claim by proof, and the imamate the necessity of a divinely appointed guide standing at the center of religion in every age. What follows is a treatise, not a story: it reasons its case out step by step, moving from first principles toward one conclusion, without characters or dialogue.</p>', NULL, 'degrees-of-excellence/cover.png', 'degrees-of-excellence/book.pdf', '2026-08-29T20:17:47Z', '46129cd6f0dc8a11ac4bdab0739b9368abc93429');
