INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('degrees-of-excellence', 'from adam to ali', 'pp. 93-100', '["Section Seven", "DEGREES OF EXCELLENCE", "AFFIRMING THE IMAMATE", "Muhammad, even though the sunna has not been replaced or altered and people cannot do without an imam.", "DEGREES OF EXCELLENCE"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('degrees-of-excellence', 'god''s vicegerent in his time', 'pp. 100-112', '["AFFIRMING THE IMAMATE", "Indeed, Adam — like all other vicegerents — was called ''vicegerent''", "Those who came after him fulfilled some of its conditions and so", "Commander of the Faithful, peace be upon him — for a shadow", "Faithful, peace be upon him. The Prophet, may God bless him, also", "DEGREES OF EXCELLENCE", "Faithful, peace be upon him, is the one through whom God", "God''s own conduct toward humanity, in obedience to God''s"]');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'blurb', NULL, 'Degrees of Excellence', 0, NULL, 'In the Name of God, this book undertakes a single task, and its original title names that task exactly. Kitab ithbat al-imama means the demonstration of the imamate — ithbat being the establishing of a claim by proof, and the imamate the necessity of a divinely appointed guide standing at the center of religion in every age. What follows is a treatise, not a story: it reasons its case out step by step, moving from first principles toward one conclusion, without characters or dialogue.', '', NULL, NULL, NULL, NULL, 'degrees of excellence', 'in the name of god this book undertakes a single task and its original title names that task exactly kitab ithbat al imama means the demonstration of the imamate ithbat being the establishing of a claim by proof and the imamate the necessity of a divinely appointed guide standing at the center of religion in every age what follows is a treatise not a story it reasons its case out step by step moving from first principles toward one conclusion without characters or dialogue', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'In the Name of God, this book undertakes a single task, and its original title names that task exactly. Kitab ithbat al-imama means the demonstration of the imamate (الْإِمَامَة) — ithbat being the establishing of a claim by proof, and the imamate the necessity of a divinely appointed guide standing at the center of religion in every age. What follows is a treatise, not a story: it reasons its case out step by step, moving from first principles toward one conclusion, without characters or dialogue.', '', NULL, NULL, NULL, NULL, 'degrees of excellence introduction to the book', 'in the name of god this book undertakes a single task and its original title names that task exactly kitab ithbat al imama means the demonstration of the imamate الامامه ithbat being the establishing of a claim by proof and the imamate the necessity of a divinely appointed guide standing at the center of religion in every age what follows is a treatise not a story it reasons its case out step by step moving from first principles toward one conclusion without characters or dialogue', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'The work is ascribed to Ahmad b. Ibrahim al-Naysaburi (اَلنَّيْسَابُورِي), a scholar of the Ismaili tradition as it flourished under the Fatimids in the late tenth and early eleventh centuries — the same intellectual world that produced al-Kirmani (اَلْكِرْمَانِيّ) and his Rahat al-Aql, a name the reader will meet among these pages. When the text says "I," that voice is the author himself, building his argument; read it as the man making the case.', '', NULL, NULL, NULL, NULL, 'degrees of excellence introduction to the book', 'the work is ascribed to ahmad b ibrahim al naysaburi النيسابوري a scholar of the ismaili tradition as it flourished under the fatimids in the late tenth and early eleventh centuries the same intellectual world that produced al kirmani الكرماني and his rahat al aql a name the reader will meet among these pages when the text says i that voice is the author himself building his argument read it as the man making the case', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The argument climbs deliberately. It calls the imam the pole (قُطْب) and foundation of religion, grounds the need for him in both nature and reason, and arranges creation into ranks and degrees before naming the imam the physician of souls and the governing principle beneath the visible order. It then turns to the institutions of faith — the direction of prayer, the sermon, the alms, the fifth — showing the imam present within each, and finally traces a single line of guides from Adam to Ali, naming the imam God''s vicegerent for his own time.', '', NULL, NULL, NULL, NULL, 'degrees of excellence introduction to the book', 'the argument climbs deliberately it calls the imam the pole قطب and foundation of religion grounds the need for him in both nature and reason and arranges creation into ranks and degrees before naming the imam the physician of souls and the governing principle beneath the visible order it then turns to the institutions of faith the direction of prayer the sermon the alms the fifth showing the imam present within each and finally traces a single line of guides from adam to ali naming the imam gods vicegerent for his own time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 0, NULL, 'In the Name of God, the All-Compassionate, the All-Merciful, from Whom we seek help in all matters.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'in the name of god the all compassionate the all merciful from whom we seek help in all matters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 1, NULL, 'Praise belongs to God, who sent messengers and prophets and appointed imams and caliphs — a mercy to His friends (اَلْأَوْلِيَاء), a punishment to His enemies, a benefit to religion and to the world, and an edifice (عِمَارَة) upholding both this present world and the world to come. I praise Him as one who knows the immense worth of the bounty He conveys through them, who is grateful for it, and who travels for His sake and hastens toward it. I bear witness that there is no deity except God — the witness of a servant who understands what this profession requires and strives to meet its obligations. And I bear witness that Muhammad is His servant and Messenger, favored above all His messengers and kept free of every mistake and error; may God bless him with blessings beyond number and beyond end. May God likewise bless his loyal and truthful legatee [Ali], who is skilled in the clarification and in the inner realities of the Quran, and the imams descended from the martyr, to whom belong praise, glory, infallibility, and uprightness. May He likewise bless the master of the palace and the age [al-Hakim (اَلْحَكِيم)], upheld by conquest and victory. May God''s finest salutations, His most generous blessings, and His purest greetings rest upon him, upon the heir-apparent of the Muslims (وَلِيّ عَهْد الْمُسْلِمِين), and upon the vicegerent (خَلِيفَة) of the Commander of the Faithful, for as long as tongues speak and as long as darkness and light continue to follow one another.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'praise belongs to god who sent messengers and prophets and appointed imams and caliphs a mercy to his friends الاولياء a punishment to his enemies a benefit to religion and to the world and an edifice عماره upholding both this present world and the world to come i praise him as one who knows the immense worth of the bounty he conveys through them who is grateful for it and who travels for his sake and hastens toward it i bear witness that there is no deity except god the witness of a servant who understands what this profession requires and strives to meet its obligations and i bear witness that muhammad is his servant and messenger favored above all his messengers and kept free of every mistake and error may god bless him with blessings beyond number and beyond end may god likewise bless his loyal and truthful legatee ali who is skilled in the clarification and in the inner realities of the quran and the imams descended from the martyr to whom belong praise glory infallibility and uprightness may he likewise bless the master of the palace and the age al hakim الحكيم upheld by conquest and victory may gods finest salutations his most generous blessings and his purest greetings rest upon him upon the heir apparent of the muslims ولي عهد المسلمين and upon the vicegerent خليفه of the commander of the faithful for as long as tongues speak and as long as darkness and light continue to follow one another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 2, NULL, 'Now to the matter itself.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'now to the matter itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 3, NULL, 'The imamate is the pole and the foundation of religion (أَسَاسُه) around which every religious and worldly affair turns, and it is a benefit to this present life and to the life to come. Through it the affairs of God''s servants are governed, the land prospers, and reward is accepted in the abode of return. Through the imamate one attains, by proof, demonstration, and evidence, the knowledge of God''s absolute oneness (التَّوْحِيد) and of the revealed Message, together with knowledge of the religious law — its foundations, its interpretation (التَّأْوِيل), and its clarification.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'the imamate is the pole and the foundation of religion اساسه around which every religious and worldly affair turns and it is a benefit to this present life and to the life to come through it the affairs of gods servants are governed the land prospers and reward is accepted in the abode of return through the imamate one attains by proof demonstration and evidence the knowledge of gods absolute oneness التوحيد and of the revealed message together with knowledge of the religious law its foundations its interpretation التاويل and its clarification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 4, NULL, 'I have called the imamate the pole and foundation of religion, and I have not placed the messengership ahead of it, because to affirm (إِثْبَات) the imamate is already to affirm the messengership. Whoever acknowledges the imam acknowledges the messenger, yet not everyone who acknowledges the messenger acknowledges the true reality of the imam. Proof of the messengership is needed for those who stand outside the domain of Islam, while affirming the imamate is what Muslims require — and Muslims stand nearer to the true believers. To contend with them by debate and argument therefore takes priority over contending with those who deny the messenger and the messengership; for the call to Islam and to the messengership has already reached the polytheists and the proof has been established against them, so that meeting them with the sword is the more fitting course. Moreover, the world can never be without an imam at any moment, whereas the messenger is present at some times and absent at others. And so, to affirm the imamate is at the same time to affirm the messengership.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'i have called the imamate the pole and foundation of religion and i have not placed the messengership ahead of it because to affirm اثبات the imamate is already to affirm the messengership whoever acknowledges the imam acknowledges the messenger yet not everyone who acknowledges the messenger acknowledges the true reality of the imam proof of the messengership is needed for those who stand outside the domain of islam while affirming the imamate is what muslims require and muslims stand nearer to the true believers to contend with them by debate and argument therefore takes priority over contending with those who deny the messenger and the messengership for the call to islam and to the messengership has already reached the polytheists and the proof has been established against them so that meeting them with the sword is the more fitting course moreover the world can never be without an imam at any moment whereas the messenger is present at some times and absent at others and so to affirm the imamate is at the same time to affirm the messengership', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 5, NULL, 'Al-Baqarah: 124وَإِذِ ٱبْتَلَىٰٓ إِبْرَهِۦمَ رَبُّهُۥ بِكَلِمَتٍۢ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًۭا', '', 'وَإِذِ ٱبْتَلَىٰٓ إِبْرَهِۦمَ رَبُّهُۥ بِكَلِمَتٍۢ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًۭا', 'Al-Baqarah: 124', 2, 124, 'degrees of excellence 1 the pole and foundation of religion', 'al baqarah 124واذ ابتلي ابرهم ربه بكلمت فاتمهن قال اني جاعلك للناس اماما', 'واذ ابتلي ابرهم ربه بكلمت فاتمهن قال اني جاعلك للناس اماما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 6, NULL, 'God, the Exalted, called the imam a messenger when He said: "And remember in the Scripture, Ismail was indeed faithful in fulfilling his promise while he was a messenger, a prophet." He likewise called the messenger an imam when He addressed Abraham: "Indeed, I am appointing you an imam for all humanity." This came after Abraham had completed his messengership, for God, the Exalted, said: "And when His Lord tried Abraham with His commands and he fulfilled them, He said: I am appointing you an imam for all humanity."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'god the exalted called the imam a messenger when he said and remember in the scripture ismail was indeed faithful in fulfilling his promise while he was a messenger a prophet he likewise called the messenger an imam when he addressed abraham indeed i am appointing you an imam for all humanity this came after abraham had completed his messengership for god the exalted said and when his lord tried abraham with his commands and he fulfilled them he said i am appointing you an imam for all humanity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 7, NULL, 'It is related from Jafar al-Sadiq (عَلَيْهِ السَّلَامُ) that he said: "God chose Abraham first as a prophet (نبياً), then as a friend (خَلِيل), then as a messenger (رسولاً), and at last said: I am appointing you an imam for all humanity." God called Adam a vicegerent (خَلِيفَة), and "vicegerent" is among the names of the imams. He called David (ع) a vicegerent while David was one of the imams of the cycles that had passed, and He called the proofs (اَلْحُجَج) "prophets." He called Muhammad and the other messengers "prophets," addressing them as prophets just as He addressed them as messengers. This is because a messenger first reaches the rank of the imamate, and then, should the age call for a new religious law to be set in place, he becomes the seventh imam of that cycle and takes up the promulgation of that law. In this way the imam stands in the place of the messenger in his own age and time. Before he rises to promulgate the religious law, the messenger is himself one of the imams, having received command from an imam before him; and once he has completed the religious law, he hands command to the imam who follows. The imam is thus always present in the world, and the world is never left without him. The imam upholds and preserves the religious law together with its inner reality, as I said earlier. It is now plain that the turning of the religious cycle depends upon the imam, and that how he acts upon the prophet''s law in his own time is the imam''s own prerogative. No one can reach the prophet, attain his rank, or arrive at a sound understanding of the religious law — which only the imam changes or replaces — except through the imam. Through the imam alone can one reach the inner truth of the religious law, its interpretation, and its meaning.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'it is related from jafar al sadiq عليه السلام that he said god chose abraham first as a prophet نبيا then as a friend خليل then as a messenger رسولا and at last said i am appointing you an imam for all humanity god called adam a vicegerent خليفه and vicegerent is among the names of the imams he called david ع a vicegerent while david was one of the imams of the cycles that had passed and he called the proofs الحجج prophets he called muhammad and the other messengers prophets addressing them as prophets just as he addressed them as messengers this is because a messenger first reaches the rank of the imamate and then should the age call for a new religious law to be set in place he becomes the seventh imam of that cycle and takes up the promulgation of that law in this way the imam stands in the place of the messenger in his own age and time before he rises to promulgate the religious law the messenger is himself one of the imams having received command from an imam before him and once he has completed the religious law he hands command to the imam who follows the imam is thus always present in the world and the world is never left without him the imam upholds and preserves the religious law together with its inner reality as i said earlier it is now plain that the turning of the religious cycle depends upon the imam and that how he acts upon the prophets law in his own time is the imams own prerogative no one can reach the prophet attain his rank or arrive at a sound understanding of the religious law which only the imam changes or replaces except through the imam through the imam alone can one reach the inner truth of the religious law its interpretation and its meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 8, NULL, 'Many works composed by the elders of the dawa to affirm the imamate rely on deduction and on evidence drawn from the well-known Quranic verses revealed concerning the imamate and the imams (عَلَيْهِمُ السَّلَامُ), and on the traditions reported from the Prophet. Those who came before have left nothing in this matter for those who come after, and there is little use in restating the same ideas in other words. I wish, therefore, to write a treatise that affirms the imamate by way of evidence (اِسْتَشْهَد) and deduction (اَلْاِسْتِدْلَال) drawn from the outer horizons (اَلْآفَاق) and from our own selves (نَفْس), from politics and governance (اَلسِّيَاسَة) and from established norms (اَلرُّسُوم); by way of intellect (اَلْعَقْل), self-evidence (اَلضَّرُورَة), innate constitution (اَلْفِطْرَة), and natural disposition (الْجِبْلَة); and by the agreement (اَلْاِتِّفَاق) of every religious community (أَهْلُ كُلِّ مِلَّةٍ), as well as of the philosophers (اَلْفَلَاسِفَة) and those who reckon with numbers (أَهْلُ الْحِسَاب). In this I follow the way of God, the Exalted, who said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'many works composed by the elders of the dawa to affirm the imamate rely on deduction and on evidence drawn from the well known quranic verses revealed concerning the imamate and the imams عليهم السلام and on the traditions reported from the prophet those who came before have left nothing in this matter for those who come after and there is little use in restating the same ideas in other words i wish therefore to write a treatise that affirms the imamate by way of evidence استشهد and deduction الاستدلال drawn from the outer horizons الافاق and from our own selves نفس from politics and governance السياسه and from established norms الرسوم by way of intellect العقل self evidence الضروره innate constitution الفطره and natural disposition الجبله and by the agreement الاتفاق of every religious community اهل كل مله as well as of the philosophers الفلاسفه and those who reckon with numbers اهل الحساب in this i follow the way of god the exalted who said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 9, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ"We shall show them Our signs on the horizons and within themselves until it becomes manifest to them that it is the truth. Does it not suffice concerning your Lord that He is witness over all things?"', '', NULL, 'Fussilat: 53', NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شيء شهيد we shall show them our signs on the horizons and within themselves until it becomes manifest to them that it is the truth does it not suffice concerning your lord that he is witness over all things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 10, NULL, 'I shall draw further evidence from the very structure of the religious duties (اَلْفَرَائِض) and practices, in a manner the elders of the dawa never attempted. If what follows proves sound, that is owing to the excellent support of the master of the age and the time (وَلِيُّ الْعَصْرِ وَالزَّمَانِ); and if any error appears in it, that is from my own weakness and shortcoming — and that is the most fitting thing for one such as me.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'i shall draw further evidence from the very structure of the religious duties الفرايض and practices in a manner the elders of the dawa never attempted if what follows proves sound that is owing to the excellent support of the master of the age and the time ولي العصر والزمان and if any error appears in it that is from my own weakness and shortcoming and that is the most fitting thing for one such as me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the pole and foundation of religion', '1. The Pole and Foundation of Religion', 11, NULL, 'Editorial note (tradition-grounded). A related teaching preserved in this tradition holds that Adam was the first to draw the lines of religion in command and prohibition — a point that illuminates why this chapter can name Adam a vicegerent and count "vicegerent" among the names of the imams. That same tradition distinguishes the apparent laws the speaker-prophets set down from the inner meanings inferred beneath them, "the recommended meanings of the parables, called interpretation." This is the tawil the chapter says only the imam can open: the outer law is promulgated by the messenger in his cycle, while its interpretation and inner reality are preserved and unlocked through the imam who stands in the world at every moment. Read alongside that teaching, the chapter''s claim that religion turns upon the imam is less a single assertion than the near end of a longer thread reaching back to the first command and prohibition.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 1 the pole and foundation of religion', 'editorial note tradition grounded a related teaching preserved in this tradition holds that adam was the first to draw the lines of religion in command and prohibition a point that illuminates why this chapter can name adam a vicegerent and count vicegerent among the names of the imams that same tradition distinguishes the apparent laws the speaker prophets set down from the inner meanings inferred beneath them the recommended meanings of the parables called interpretation this is the tawil the chapter says only the imam can open the outer law is promulgated by the messenger in his cycle while its interpretation and inner reality are preserved and unlocked through the imam who stands in the world at every moment read alongside that teaching the chapters claim that religion turns upon the imam is less a single assertion than the near end of a longer thread reaching back to the first command and prohibition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 0, NULL, 'We say, then, that the necessity (وُجُوب) of the imamate and of the imams (عَلَيْهِمُ السَّلَامُ) rests upon natural disposition (جِبْلَة), innate constitution (اَلْفِطْرَة), nature (اَلطَّبِيعَة), intellect (اَلْعَقْل), governance (اَلسِّيَاسَة), prescription (اَلْوَضْع), and established norms (اَلرُّسُوم). It is obligatory in all revealed law (شَرِيْعَة), in religion, and in every religious community, just as the existence of the Creator is necessary by innate constitution, by natural disposition, and by intellect in every community and every religion. And yet people fell into disagreement about the Creator even after His necessity had been established and after they had accepted that He exists. They began to draw conclusions that followed their own whims and opinions, and that merely imitated their forebears and teachers without thought, until they claimed that the Creator whom innate constitution and natural disposition require is in truth nothing more than substance, or the elements, or the stars, or the sun, or something else of that kind. At times they described the Creator with attributes that liken Him to His creation, which is anthropomorphism, or with attributes that border on polytheism, and they rested all of this upon their own judgment, with no sound knowledge behind it. In exactly the same way, people fell into disagreement over the necessity of the imamate after committing themselves to the imam. Some insisted that the imam whom intellect and self-evidence establish is merely the wise man of each age — a view close to that of the philosophers, who call their teachers "imams" (أَئِمَّة), "sages" (حُكَمَاء), "head of the scholars" (رَأْسُ الْعُلَمَاء), "master of the world" (سَائِس), and "the teacher" (مُعَلِّم).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'we say then that the necessity وجوب of the imamate and of the imams عليهم السلام rests upon natural disposition جبله innate constitution الفطره nature الطبيعه intellect العقل governance السياسه prescription الوضع and established norms الرسوم it is obligatory in all revealed law شريعه in religion and in every religious community just as the existence of the creator is necessary by innate constitution by natural disposition and by intellect in every community and every religion and yet people fell into disagreement about the creator even after his necessity had been established and after they had accepted that he exists they began to draw conclusions that followed their own whims and opinions and that merely imitated their forebears and teachers without thought until they claimed that the creator whom innate constitution and natural disposition require is in truth nothing more than substance or the elements or the stars or the sun or something else of that kind at times they described the creator with attributes that liken him to his creation which is anthropomorphism or with attributes that border on polytheism and they rested all of this upon their own judgment with no sound knowledge behind it in exactly the same way people fell into disagreement over the necessity of the imamate after committing themselves to the imam some insisted that the imam whom intellect and self evidence establish is merely the wise man of each age a view close to that of the philosophers who call their teachers imams ايمه sages حكماء head of the scholars راس العلماء master of the world سايس and the teacher معلم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 1, NULL, 'The followers of the various religions have called the imams of their past "prophets" and "sages" in every cycle, while certain followers of Islam have given the title "imam" to usurping, oppressive false claimants, and have likewise given the name "imam" to their scholars and jurists. Yet if you weigh all these cases carefully, you find that every one of them confirms the existence of the imam as a necessity (اَلضَّرُورَة) and cannot deny it. Whoever seeks salvation and guidance must set aside his inclinations and desires and see the deficiency in every false claimant to this office: his lack of knowledge, gnosis, and cognition, his lack of piety, and his failure to meet the other conditions of the Imamate. Once such a person has recognized the pretender''s ignorance, the shallowness of his piety and modesty, and his inability to fulfill even one of the conditions of the imamate, he will reject that pretender''s claim until the day he attains recognition of the true imam (مَعْرِفَةُ إِمَامِ الْحَقِّ).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'the followers of the various religions have called the imams of their past prophets and sages in every cycle while certain followers of islam have given the title imam to usurping oppressive false claimants and have likewise given the name imam to their scholars and jurists yet if you weigh all these cases carefully you find that every one of them confirms the existence of the imam as a necessity الضروره and cannot deny it whoever seeks salvation and guidance must set aside his inclinations and desires and see the deficiency in every false claimant to this office his lack of knowledge gnosis and cognition his lack of piety and his failure to meet the other conditions of the imamate once such a person has recognized the pretenders ignorance the shallowness of his piety and modesty and his inability to fulfill even one of the conditions of the imamate he will reject that pretenders claim until the day he attains recognition of the true imam معرفه امام الحق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 2, NULL, 'We shall now examine some of the claims each pretender makes, together with his weaknesses and his limits. We shall turn his own principles against him and strip the imamate from those who are unfit for it. We shall then establish the imamate of the true imams with proofs and demonstrations, and establish the obligation of obeying them, of entrusting our affairs to their command, and of receiving revelation, interpretation, and the confession of Divine Unity from them, just as we set out in Kitab al-tawhid, the Book on Divine Unity. All those who truly know created beings come to see their incapacity and deficiency and reject any claim of divinity for them, until at last they deny divinity to every created thing. In this way Divine Unity remains pure, free of ascribing human qualities to God (تَشَبُّه) and free of denying His attributes altogether (تَعْطِيلْ).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'we shall now examine some of the claims each pretender makes together with his weaknesses and his limits we shall turn his own principles against him and strip the imamate from those who are unfit for it we shall then establish the imamate of the true imams with proofs and demonstrations and establish the obligation of obeying them of entrusting our affairs to their command and of receiving revelation interpretation and the confession of divine unity from them just as we set out in kitab al tawhid the book on divine unity all those who truly know created beings come to see their incapacity and deficiency and reject any claim of divinity for them until at last they deny divinity to every created thing in this way divine unity remains pure free of ascribing human qualities to god تشبه and free of denying his attributes altogether تعطيل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 3, NULL, 'We also say that God, the Exalted, through His subtle wisdom and His boundless power, created for the human body certain principles, causes, and means. He made all the derivatives and realms of nature appear in the body and through its effects, so that they would emerge in a fixed order and within a set term, until He brought forth from them a body furnished with senses that answer to those principles and are in harmony with them. He made those principles and means the body''s sustenance and nourishment, by which it survives and by which its bodily and perceptual reward and punishment are determined. In the same way, He set principles, causes, and means for souls, spirits, and religious noetic forms, and from their effects these forms appear. Through them their sustenance, nourishment, survival, and reward are determined, while their punishment is determined by the loss of their support and their distance from their origin.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'we also say that god the exalted through his subtle wisdom and his boundless power created for the human body certain principles causes and means he made all the derivatives and realms of nature appear in the body and through its effects so that they would emerge in a fixed order and within a set term until he brought forth from them a body furnished with senses that answer to those principles and are in harmony with them he made those principles and means the bodys sustenance and nourishment by which it survives and by which its bodily and perceptual reward and punishment are determined in the same way he set principles causes and means for souls spirits and religious noetic forms and from their effects these forms appear through them their sustenance nourishment survival and reward are determined while their punishment is determined by the loss of their support and their distance from their origin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 4, NULL, 'God, may His name be exalted, made the principles and causes of the body a testimony and a proof for the principles of the soul, and for its derivatives and its nourishment, so that the religious creation would mirror the physical creation, corresponding to it and running parallel with it. Just as the body appears and reaches its perfection only through the celestial spheres together with the stars (الْكَوَاكِب) — for it cannot be perfected through the spheres alone without the stars, even though the stars themselves revolve around the spheres, and even though the course of events is always shaped by the stars — so too the religious noetic forms and the everlasting souls appear and reach their perfection only through the influence of the imams. Their nourishment comes from the imams'' knowledge, for the imams are the religious stars, as the Prophet, may God bless him and his family, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'god may his name be exalted made the principles and causes of the body a testimony and a proof for the principles of the soul and for its derivatives and its nourishment so that the religious creation would mirror the physical creation corresponding to it and running parallel with it just as the body appears and reaches its perfection only through the celestial spheres together with the stars الكواكب for it cannot be perfected through the spheres alone without the stars even though the stars themselves revolve around the spheres and even though the course of events is always shaped by the stars so too the religious noetic forms and the everlasting souls appear and reach their perfection only through the influence of the imams their nourishment comes from the imams knowledge for the imams are the religious stars as the prophet may god bless him and his family said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 5, NULL, '"My companions are like the stars; whomsoever you emulate, you will be guided."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'my companions are like the stars whomsoever you emulate you will be guided', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 6, NULL, 'This holds even as the imams stand in the place of the prophets, who are like the celestial spheres. The course of affairs for all created beings, and their final recourse, is therefore toward the imams. Were we to draw out the parallel between the religious spheres and the natural spheres in full, this epistle would grow too long and pass beyond its intended scope. We shall therefore keep to certain indications in the introduction of this treatise, for those who wish to pursue the matter further and to grasp aspects of what we have left unmentioned, if God, the Exalted, wills.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'this holds even as the imams stand in the place of the prophets who are like the celestial spheres the course of affairs for all created beings and their final recourse is therefore toward the imams were we to draw out the parallel between the religious spheres and the natural spheres in full this epistle would grow too long and pass beyond its intended scope we shall therefore keep to certain indications in the introduction of this treatise for those who wish to pursue the matter further and to grasp aspects of what we have left unmentioned if god the exalted wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 7, NULL, 'We say, accordingly, that the existence of differences and degrees of excellence in all things — spanning the elements, the realms of nature, and their derivatives — is the firmest evidence and proof for affirming the imamate and the imams. This is because God, the Exalted, created all things different and unequal in their degree of excellence across every genus and species, and then assigned to each genus and species an upper limit (غَايَة), a summit (ذُرْوَة), an end (نِهَى), and a distinguishing virtue (فَضْل) that nothing else in that category can reach. Either He made those genera and species foundational to creation, such that humanity cannot manage without them, nor its bodily existence and function be complete without them, or else He made them sources of nourishment, remedy, elegance, adornment, and indispensable tools. In everything He placed an advantage (مَنْفَعَة) found nowhere else. He powerfully endowed in each thing a capacity that creation would necessarily need, one it can neither avoid nor carry on its physical affairs without. He also subjected each thing to a test and drove it to seek whatever would remedy its deficiency. So when one cannot find the cure for that deficiency where one stands, one seeks it elsewhere, or hurries to wherever it may be found.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'we say accordingly that the existence of differences and degrees of excellence in all things spanning the elements the realms of nature and their derivatives is the firmest evidence and proof for affirming the imamate and the imams this is because god the exalted created all things different and unequal in their degree of excellence across every genus and species and then assigned to each genus and species an upper limit غايه a summit ذروه an end نهي and a distinguishing virtue فضل that nothing else in that category can reach either he made those genera and species foundational to creation such that humanity cannot manage without them nor its bodily existence and function be complete without them or else he made them sources of nourishment remedy elegance adornment and indispensable tools in everything he placed an advantage منفعه found nowhere else he powerfully endowed in each thing a capacity that creation would necessarily need one it can neither avoid nor carry on its physical affairs without he also subjected each thing to a test and drove it to seek whatever would remedy its deficiency so when one cannot find the cure for that deficiency where one stands one seeks it elsewhere or hurries to wherever it may be found', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 8, NULL, 'As long as one remains in the world of the body, one cannot for a single moment do without breathing (اَلتَّنَسُّم), nor without drawing benefit from the elements of one''s world: its derivatives, its realms of nature, its vegetation, and its nourishment. All of this is a wisdom from God, the Exalted, and a mark of His justice, so that these things might serve as witnesses and as ephemeral, obligatory symbols (اَلْمِثَالَاتُ الْجَبْرِيَّات) for the symbolized realities that are religious, eternal, and chosen. The benefit of all the symbolized realities — spanning principles, realms of nature, nourishment, and religious remedies — is more deserving, more worthy, and more powerful than the obligatory symbols. The need for them is greater than the need for what nature compels, because the benefit of the natural symbols returns to the body, while the benefit of the symbolized realities returns to the spirit and the soul. As far as the intellectual symbolized realities excel the natural symbols, so far does the spirit excel the body. In the same measure, the superiority of the symbolized over the symbol matches the superiority of the everlasting over the perishable. The excellence in each of them reflects the deficiency of the other. For whoever is deprived of the physical things he needs will not necessarily be destroyed by that deprivation, and even if such destruction were to come, it would be only the destruction of his body, which will beyond doubt perish and die in any case. But in the absence of the symbolized religious reality, the soul itself faces destruction and plunges into perpetual punishment. If people''s striving to obtain what the soul needs were equal to their striving and longing to obtain what the body needs, then no two people would doubt, go astray, or fall into anthropomorphism (تَشَبُّه).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'as long as one remains in the world of the body one cannot for a single moment do without breathing التنسم nor without drawing benefit from the elements of ones world its derivatives its realms of nature its vegetation and its nourishment all of this is a wisdom from god the exalted and a mark of his justice so that these things might serve as witnesses and as ephemeral obligatory symbols المثالات الجبريات for the symbolized realities that are religious eternal and chosen the benefit of all the symbolized realities spanning principles realms of nature nourishment and religious remedies is more deserving more worthy and more powerful than the obligatory symbols the need for them is greater than the need for what nature compels because the benefit of the natural symbols returns to the body while the benefit of the symbolized realities returns to the spirit and the soul as far as the intellectual symbolized realities excel the natural symbols so far does the spirit excel the body in the same measure the superiority of the symbolized over the symbol matches the superiority of the everlasting over the perishable the excellence in each of them reflects the deficiency of the other for whoever is deprived of the physical things he needs will not necessarily be destroyed by that deprivation and even if such destruction were to come it would be only the destruction of his body which will beyond doubt perish and die in any case but in the absence of the symbolized religious reality the soul itself faces destruction and plunges into perpetual punishment if peoples striving to obtain what the soul needs were equal to their striving and longing to obtain what the body needs then no two people would doubt go astray or fall into anthropomorphism تشبه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 9, NULL, 'We also say that everything God, the Exalted, has created in this order, and humanity''s need of it, as we described above, is an admonition that directs people toward the symbolized religious reality. It is a witness for all who seek such testimony, a proof for all who ask for evidence, and an insight for all who observe and reflect. It is equally a proof against those who deny the symbolized religious reality of the imams and their hierarchies, denying their knowledge and the benefit they bring, while at the same time accepting the benefit they draw from the natural elements, the planets, and the celestial spheres.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'we also say that everything god the exalted has created in this order and humanitys need of it as we described above is an admonition that directs people toward the symbolized religious reality it is a witness for all who seek such testimony a proof for all who ask for evidence and an insight for all who observe and reflect it is equally a proof against those who deny the symbolized religious reality of the imams and their hierarchies denying their knowledge and the benefit they bring while at the same time accepting the benefit they draw from the natural elements the planets and the celestial spheres', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 10, NULL, 'God, the Exalted, established these elements, means, and natural causes so firmly that no one can deny them, argue them away, alter them, or change them in any way. This stands in sharp contrast to what certain people did with the religious law and with the testimony the Prophet had called them to bear: the affirmation of the imamate and the imams, the obligation to follow them, devotion to them, obedience to them, the condemnation of those who disobey them, and the promise of reward for those who obey. They distorted all of this, just as they altered and distorted the Quran. God, the Exalted, has told us of this in His words:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'god the exalted established these elements means and natural causes so firmly that no one can deny them argue them away alter them or change them in any way this stands in sharp contrast to what certain people did with the religious law and with the testimony the prophet had called them to bear the affirmation of the imamate and the imams the obligation to follow them devotion to them obedience to them the condemnation of those who disobey them and the promise of reward for those who obey they distorted all of this just as they altered and distorted the quran god the exalted has told us of this in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 11, NULL, 'Al-Ma''idah: 13يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ"…changing words from their context while they forgot a portion of what We have reminded them of." (Al-Maidah: 13)', '', NULL, 'Al-Ma''idah: 13', NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'al maidah 13يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به changing words from their context while they forgot a portion of what we have reminded them of al maidah 13', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 12, NULL, 'And God, Whose mention is exalted, has also said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'and god whose mention is exalted has also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 13, NULL, 'At-Tawbah: 37إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌۭ فِى ٱلْكُفْرِ"Indeed, forgetfulness is only an excess of disbelief…" (At-Tawbah: 37)', '', NULL, 'At-Tawbah: 37', NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'at tawbah 37انما النسيء زياده في الكفر indeed forgetfulness is only an excess of disbelief at tawbah 37', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 14, NULL, 'Yet what they committed was not forgetfulness at all. They abandoned the testimony deliberately, as though they had never seen it and never heard it.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'yet what they committed was not forgetfulness at all they abandoned the testimony deliberately as though they had never seen it and never heard it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 15, NULL, 'Just as the testimony of the outer horizons and the inner selves is compulsory rather than chosen, and therefore impossible for anyone to alter, to replace, or to suppress, so too did the Messenger, may God bless him, make testimony compulsory, leaving the witnesses no choice to change it, alter it, or conceal it. He threatened whoever would change or conceal it with a painful punishment. God, the Exalted, commanded that judgment be rendered upon the testimony of two witnesses, saying:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'just as the testimony of the outer horizons and the inner selves is compulsory rather than chosen and therefore impossible for anyone to alter to replace or to suppress so too did the messenger may god bless him make testimony compulsory leaving the witnesses no choice to change it alter it or conceal it he threatened whoever would change or conceal it with a painful punishment god the exalted commanded that judgment be rendered upon the testimony of two witnesses saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 16, NULL, 'Al-Baqarah: 282تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ ۚ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟"If one of them falls into error, the other will remind. And the witnesses must not refuse when they are summoned." (Al-Baqarah: 282)', '', NULL, 'Al-Baqarah: 282', NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'al baqarah 282تضل احداهما فتذكر احداهما الاخري ولا ياب الشهداء اذا ما دعوا if one of them falls into error the other will remind and the witnesses must not refuse when they are summoned al baqarah 282', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 17, NULL, 'By this He meant that true judgment in religion, and in affirming the imamate and the hierarchies, rests upon two witnesses: one established by law and the other compelled by nature. When people deny the legally established testimony, the one bound by nature — namely the horizons and our own inner selves — steps in to remind, to enforce, and to verify the conventional witnesses, just as God, the Exalted, says:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'by this he meant that true judgment in religion and in affirming the imamate and the hierarchies rests upon two witnesses one established by law and the other compelled by nature when people deny the legally established testimony the one bound by nature namely the horizons and our own inner selves steps in to remind to enforce and to verify the conventional witnesses just as god the exalted says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 18, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ"We shall show them Our signs on the horizons and within themselves until it becomes manifest to them that it is the Truth." (Fussilat: 53)', '', NULL, 'Fussilat: 53', NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق we shall show them our signs on the horizons and within themselves until it becomes manifest to them that it is the truth fussilat 53', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 19, NULL, 'And in the same way, when the Prophet was asked, "Who is the witness of your prophethood?" he answered:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'and in the same way when the prophet was asked who is the witness of your prophethood he answered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 20, NULL, '"My witness is every stone and every piece of clay."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'my witness is every stone and every piece of clay', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 21, NULL, 'By this he was pointing to the testimony of the horizons and the souls. When the legal and the natural witnesses both testify, and the intellect serves as the measure for weighing that testimony without preference or partiality, then truth swiftly becomes manifest.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'by this he was pointing to the testimony of the horizons and the souls when the legal and the natural witnesses both testify and the intellect serves as the measure for weighing that testimony without preference or partiality then truth swiftly becomes manifest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 22, NULL, 'We shall now discuss the differences and the degrees of excellence within each principle and realm of nature, and show that the ultimate limit and highest summit in every genus and species points to the imam in every age and time. And if these genera and species demonstrate the imamate and the imams through a different framework — such as the seven planets serving as testimony for the seven imams, and other groups of seven besides — that does not rule out drawing a proof, through the peak and perfection of every genus and species, for the imam in the manner we have just described.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'we shall now discuss the differences and the degrees of excellence within each principle and realm of nature and show that the ultimate limit and highest summit in every genus and species points to the imam in every age and time and if these genera and species demonstrate the imamate and the imams through a different framework such as the seven planets serving as testimony for the seven imams and other groups of seven besides that does not rule out drawing a proof through the peak and perfection of every genus and species for the imam in the manner we have just described', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'by nature and by reason', '2. By Nature and by Reason', 23, NULL, 'Editorial note (tradition-grounded). The chapter''s parallel between the natural spheres with their stars and the "religious spheres" of prophets with their imams draws on a cosmology a modern reader may not know. A related teaching preserved in this tradition describes a First Intellect that "journeyed through the spiritual realm and the station of unity without external guidance, becoming a plateau of knowledge" — the origin from which knowledge descends through the spiritual world. Read against that background, the image here becomes clearer: as the stars transmit the influence of the higher spheres to the body below, the imams transmit the light of prophecy to souls, their nourishment being knowledge itself. The hierarchy is one of guidance, not of divinity — which is why the chapter is at pains to deny divinity to every created thing.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 2 by nature and by reason', 'editorial note tradition grounded the chapters parallel between the natural spheres with their stars and the religious spheres of prophets with their imams draws on a cosmology a modern reader may not know a related teaching preserved in this tradition describes a first intellect that journeyed through the spiritual realm and the station of unity without external guidance becoming a plateau of knowledge the origin from which knowledge descends through the spiritual world read against that background the image here becomes clearer as the stars transmit the influence of the higher spheres to the body below the imams transmit the light of prophecy to souls their nourishment being knowledge itself the hierarchy is one of guidance not of divinity which is why the chapter is at pains to deny divinity to every created thing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 0, NULL, 'The wisest of the philosophers speak of ten categories, and they hold that nothing can be named or discussed except in relation to these ten: substance (الْجَوْهَر), quantity (الكمّية), quality (اَلْكَيْفِيَّة), relation (الْإِضَافَة), place (اَلْمَكَان), time (اَلزَّمَانْ), possession (الجِدة), posture (نُصبة), action (فَاعِل), and affection (الْمَفْعُول). The highest of the ten is substance. All the rest rest upon it, and it surpasses them all, for the remaining nine are established only through it. The substance the philosophers describe therefore stands as a proof for the permanent, intellectual, luminous, and authentic substance by which every soul is illumined, and upon which all nine religious accidents (الْأَعْرَاض) depend. This substance, however, needs no created thing. It draws benefit from nothing and from no one in the world; rather, everything benefits from it and stands in need of it. That is the imam (ع). Every other rank stands below him just as the nine accidents stand in relation to substance.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'the wisest of the philosophers speak of ten categories and they hold that nothing can be named or discussed except in relation to these ten substance الجوهر quantity الكميه quality الكيفيه relation الاضافه place المكان time الزمان possession الجده posture نصبه action فاعل and affection المفعول the highest of the ten is substance all the rest rest upon it and it surpasses them all for the remaining nine are established only through it the substance the philosophers describe therefore stands as a proof for the permanent intellectual luminous and authentic substance by which every soul is illumined and upon which all nine religious accidents الاعراض depend this substance however needs no created thing it draws benefit from nothing and from no one in the world rather everything benefits from it and stands in need of it that is the imam ع every other rank stands below him just as the nine accidents stand in relation to substance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 1, NULL, 'I say, too, that among the four basic constituents (اَلْعَنَاصِر) from which the first composites (التَّرَاكِيب) were formed, two are active and two are passive. The active ones are heat and cold; the passive ones are dryness and humidity. The highest and noblest of them is heat, which gives rise to luminosity, light, motion, movement, and elevation, while the other three are established through it. Heat therefore comes first both in origin and in existence, and no foundation or realm of nature is complete without it. In the same way, the imam illumines souls, and from him come intellectual light (اَلنُّورُ الْعَقْلِيّ), motion (اَلْحَرَكَة), and elevation (اَلْعُلُو). No principle or religious realm is complete without him.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i say too that among the four basic constituents العناصر from which the first composites التراكيب were formed two are active and two are passive the active ones are heat and cold the passive ones are dryness and humidity the highest and noblest of them is heat which gives rise to luminosity light motion movement and elevation while the other three are established through it heat therefore comes first both in origin and in existence and no foundation or realm of nature is complete without it in the same way the imam illumines souls and from him come intellectual light النور العقلي motion الحركه and elevation العلو no principle or religious realm is complete without him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 2, NULL, 'Among the celestial spheres, the most exalted and supreme is the outermost sphere (فَلَكُ الْأَفْلَاك), within which all the others turn. In the same way, the imam in his religion is the supreme religious sphere that encompasses all the rest, and every heavenly body and every religious sign of the zodiac moves under his command. Someone might argue that this is instead a symbol for the qaim, the Resurrector, on the ground that the highest principle in the world corresponds to the Intellect among the four principles. My reply is that the imam is the qaim in his own time; he is the proclaimer (اَلنَّاطِق) in his age, and he is the one who occupies the position of the qaim. The imam''s place in his own realm is that of the Universal Intellect (الْعَقْلُ الْكُلِّي).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'among the celestial spheres the most exalted and supreme is the outermost sphere فلك الافلاك within which all the others turn in the same way the imam in his religion is the supreme religious sphere that encompasses all the rest and every heavenly body and every religious sign of the zodiac moves under his command someone might argue that this is instead a symbol for the qaim the resurrector on the ground that the highest principle in the world corresponds to the intellect among the four principles my reply is that the imam is the qaim in his own time he is the proclaimer الناطق in his age and he is the one who occupies the position of the qaim the imams place in his own realm is that of the universal intellect العقل الكلي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 4, NULL, 'I say, too, that among the four elements (اَلْأَرْكَان), the highest and noblest is fire, which stands at the summit and the peak, a height no other element or nature can reach. In the same way, the imam in his age and time is the highest religious pillar, through whom souls are illumined. It was on this basis that Abraham commanded that fire be glorified, if what is reported from him is accurate, and forbade that it be extinguished or put out. His true intent, however, pointed toward glorifying the imamate, which no one may extinguish through the injustice of those who falsely claim its position. The fire worshippers fell into confusion, failing to grasp the reality behind the symbol. God, the Exalted, described the adversaries and the usurpers of the imamate in His words:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i say too that among the four elements الاركان the highest and noblest is fire which stands at the summit and the peak a height no other element or nature can reach in the same way the imam in his age and time is the highest religious pillar through whom souls are illumined it was on this basis that abraham commanded that fire be glorified if what is reported from him is accurate and forbade that it be extinguished or put out his true intent however pointed toward glorifying the imamate which no one may extinguish through the injustice of those who falsely claim its position the fire worshippers fell into confusion failing to grasp the reality behind the symbol god the exalted described the adversaries and the usurpers of the imamate in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'degrees of excellence', '3. Degrees of Excellence', 5, NULL, 'At-Tawbah: 32يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَفِرُونَ', '', 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَفِرُونَ', 'At-Tawbah: 32', 9, 32, 'degrees of excellence 3 degrees of excellence', 'at tawbah 32يريدون ان يطفوا نور الله بافوههم ويابي الله الا ان يتم نوره ولو كره الكفرون', 'يريدون ان يطفوا نور الله بافوههم ويابي الله الا ان يتم نوره ولو كره الكفرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 6, NULL, 'They would like to extinguish God''s light with their mouths, but God will not allow that to happen until He perfects His light, even if the unbelievers may detest it (At-Tawbah: 32).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'they would like to extinguish gods light with their mouths but god will not allow that to happen until he perfects his light even if the unbelievers may detest it at tawbah 32', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 7, NULL, 'I maintain, too, that among the many planets (الْكَوَاكِب) there are differences and gradations in degrees of excellence. Their peak and summit in nobility and merit is the sun, through which the eye draws its light, and through which every plant, animal, and newborn grows and comes to perfection. No plant or newborn grows without the influence of the sun. In the same way, the imam is the sun of the religion, through which insight is enlightened and souls are illumined by the light of guidance and wisdom, which radiates through the hearts of God''s friends. It is for this reason that some people were moved to glorify the sun. Yet the sun worshippers, too, fell into confusion, grasping only the symbol without recognizing the reality it signified. For this reason the Prophet spoke of the rising of the sun from the west as a sign of the imam''s own rising in the Maghrib.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i maintain too that among the many planets الكواكب there are differences and gradations in degrees of excellence their peak and summit in nobility and merit is the sun through which the eye draws its light and through which every plant animal and newborn grows and comes to perfection no plant or newborn grows without the influence of the sun in the same way the imam is the sun of the religion through which insight is enlightened and souls are illumined by the light of guidance and wisdom which radiates through the hearts of gods friends it is for this reason that some people were moved to glorify the sun yet the sun worshippers too fell into confusion grasping only the symbol without recognizing the reality it signified for this reason the prophet spoke of the rising of the sun from the west as a sign of the imams own rising in the maghrib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 8, NULL, 'Were the physical sun to swerve from its established orbit, from its ascent and descent about its center, even for the blink of an eye, the whole world would be destroyed. That, as we know, is impossible both rationally and naturally. The Prophet''s statement therefore holds true only on the basis of esoteric interpretation. And indeed that interpretation has proven correct, as we have witnessed with our own eyes, by the grace and favor of God.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'were the physical sun to swerve from its established orbit from its ascent and descent about its center even for the blink of an eye the whole world would be destroyed that as we know is impossible both rationally and naturally the prophets statement therefore holds true only on the basis of esoteric interpretation and indeed that interpretation has proven correct as we have witnessed with our own eyes by the grace and favor of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 9, NULL, 'I say, too, that among the twelve signs of the zodiac, four are the most glorious and excellent, and among those four one stands at the peak and summit in nobility. In the same way, among the twelve proofs (اَلْحُجَج), the one connected to the imamate is the most excellent, the noblest, and the most exalted of them all.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i say too that among the twelve signs of the zodiac four are the most glorious and excellent and among those four one stands at the peak and summit in nobility in the same way among the twelve proofs الحجج the one connected to the imamate is the most excellent the noblest and the most exalted of them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 11, NULL, 'I maintain that the fourth clime (قَلَم), which corresponds to the fourth heaven and aligns with the sun, is the most temperate as well as the most excellent and noble of all. In the same way, the imam is the most excellent and most glorious within the hierarchy, standing as their peak and apex.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i maintain that the fourth clime قلم which corresponds to the fourth heaven and aligns with the sun is the most temperate as well as the most excellent and noble of all in the same way the imam is the most excellent and most glorious within the hierarchy standing as their peak and apex', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 12, NULL, 'I say, too, that among the minerals that melt, the most excellent is gold. It is the medium through which people carry out their transactions; it fixes the value of all valuables, and it is unharmed by fire or water and cannot be destroyed. In the same way, the imam is the most excellent religious and intellectual substance in his age and time. Through him the transactions of creation and the well-being of people, in this world and in religion alike, are brought to completion. Each melting substance has its own peak of nobility.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i say too that among the minerals that melt the most excellent is gold it is the medium through which people carry out their transactions it fixes the value of all valuables and it is unharmed by fire or water and cannot be destroyed in the same way the imam is the most excellent religious and intellectual substance in his age and time through him the transactions of creation and the well being of people in this world and in religion alike are brought to completion each melting substance has its own peak of nobility', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 13, NULL, 'Among precious stones, the finest is the sapphire, and among all sapphires — white, green, yellow, and red — it is the red ruby that surpasses them all. No other jewel endures as the ruby does: it keeps its essence unchanged by fire or water, holding at all times its purity, its radiance, and its weight. It draws from its source properties that no other substance can. Not even the other sapphires, the emerald, the Badakhshi stone, carnelian, agate, diamond, turquoise, or jade can hold those qualities. The crown among jewels is therefore the red ruby, just as the imam is the pinnacle of all creation in his age and time, unique among all the ranks of the hierarchy: the proofs (اَلْحُجَج), the adjuncts (اَللَّوَاحِق), the summoner (اَلدَّاعِي), the wing (اَلْجَنَاح), the licensee (الْمَأْذُون), and the motivator (المكلّب).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'among precious stones the finest is the sapphire and among all sapphires white green yellow and red it is the red ruby that surpasses them all no other jewel endures as the ruby does it keeps its essence unchanged by fire or water holding at all times its purity its radiance and its weight it draws from its source properties that no other substance can not even the other sapphires the emerald the badakhshi stone carnelian agate diamond turquoise or jade can hold those qualities the crown among jewels is therefore the red ruby just as the imam is the pinnacle of all creation in his age and time unique among all the ranks of the hierarchy the proofs الحجج the adjuncts اللواحق the summoner الداعي the wing الجناح the licensee الماذون and the motivator المكلب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 14, NULL, 'The imam is thus the apex, whose standing, rank, and position no one in his age or time can attain. From another angle, the seven jewels serve as proofs for the seven proclaimers and the seven imams. But the argument I am relying on here, degrees of excellence, carries greater force. This is because the natural symbol is present in every age and time, and so the reality it symbolizes must also be present in every age and time. Since the stars, the natural elements, the realms of nature, and the substances are ever-present, it is equally necessary that the ranks of the hierarchy exist in every age and time, so that they may always exercise their influence upon souls.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'the imam is thus the apex whose standing rank and position no one in his age or time can attain from another angle the seven jewels serve as proofs for the seven proclaimers and the seven imams but the argument i am relying on here degrees of excellence carries greater force this is because the natural symbol is present in every age and time and so the reality it symbolizes must also be present in every age and time since the stars the natural elements the realms of nature and the substances are ever present it is equally necessary that the ranks of the hierarchy exist in every age and time so that they may always exercise their influence upon souls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'degrees of excellence', '3. Degrees of Excellence', 15, NULL, 'I maintain that there are seven grains that give human beings food and nourishment, and their peak and summit is wheat, the most balanced in nature and nobility, the grain that builds the body. In the same way, the imam is the peak and summit through whom souls are nourished and benefit. From him comes their livelihood and their life, and from him they receive knowledge.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 3 degrees of excellence', 'i maintain that there are seven grains that give human beings food and nourishment and their peak and summit is wheat the most balanced in nature and nobility the grain that builds the body in the same way the imam is the peak and summit through whom souls are nourished and benefit from him comes their livelihood and their life and from him they receive knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 0, NULL, 'Section Six', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'section six', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 1, NULL, 'As for the trees that bear fruit, the highest and most excellent of them is the date palm. It is like human beings in having male and female, and it needs to be fertilized just as animals need to mate. What is more, every part of the date palm is useful and nothing about it is wasted: its fruit can be eaten at any time, whether raw or cooked. If a sleeper dreams that he is picking dates from a date palm, the meaning is that he will receive some benefit from a certain believer. That believer, in truth, is the imam, who is the head of all believers.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'as for the trees that bear fruit the highest and most excellent of them is the date palm it is like human beings in having male and female and it needs to be fertilized just as animals need to mate what is more every part of the date palm is useful and nothing about it is wasted its fruit can be eaten at any time whether raw or cooked if a sleeper dreams that he is picking dates from a date palm the meaning is that he will receive some benefit from a certain believer that believer in truth is the imam who is the head of all believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 2, NULL, 'I say, too, that among plants certain gentle medicines have reached so fine a degree of excellence that they have become antidotes (ترياقاً) for those on the point of death. Some of these cure long-standing diseases, while others rank lower. The highest and most excellent of them points to the imam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'i say too that among plants certain gentle medicines have reached so fine a degree of excellence that they have become antidotes ترياقا for those on the point of death some of these cure long standing diseases while others rank lower the highest and most excellent of them points to the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 3, NULL, 'The imam and his word become an antidote for souls, a means of healing and of relief from death, sickness, doubt, and discord. The opponents who seize the station of the imams (عَلَيْهِمُ السَّلَامُ) by force are like the fatal poisons and harmful substances found among medicines. They are deadly poisons that destroy anyone who listens to them, keeps their company, or leans toward them, unless the imam reaches such people with the great antidote that rescues their souls from ruin. These opponents are also like useless, worthless stones. It is for this reason that God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'the imam and his word become an antidote for souls a means of healing and of relief from death sickness doubt and discord the opponents who seize the station of the imams عليهم السلام by force are like the fatal poisons and harmful substances found among medicines they are deadly poisons that destroy anyone who listens to them keeps their company or leans toward them unless the imam reaches such people with the great antidote that rescues their souls from ruin these opponents are also like useless worthless stones it is for this reason that god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 4, NULL, 'Al-Anbiya: 98حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَرِدُونَ"... pebble-covered hell where you will return." (Al-Anbiya: 98)', '', NULL, 'Al-Anbiya: 98', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'al anbiya 98حصب جهنم انتم لها وردون pebble covered hell where you will return al anbiya 98', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 5, NULL, 'And His words:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'and his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 6, NULL, 'Al-Baqarah: 24فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَفِرِينَ"... and guard yourself against the Fire that has been ignited for the people and the stones that have been prepared for the non-believers." (Al-Baqarah: 24)', '', NULL, 'Al-Baqarah: 24', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'al baqarah 24فاتقوا النار التي وقودها الناس والحجاره اعدت للكفرين and guard yourself against the fire that has been ignited for the people and the stones that have been prepared for the non believers al baqarah 24', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 7, NULL, 'I say, too, that among animals the horse is the finest, among birds the eagle, and among beasts of prey the lion holds the first place. The differences among these various kinds — in strength, usefulness, capacity to be trained, and the height each reaches within its own species — point to the fact that there is a summit within the genus of animals, just as within the human species that summit is the imam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'i say too that among animals the horse is the finest among birds the eagle and among beasts of prey the lion holds the first place the differences among these various kinds in strength usefulness capacity to be trained and the height each reaches within its own species point to the fact that there is a summit within the genus of animals just as within the human species that summit is the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 8, NULL, 'I say further that some plants are sweet, delicious, and pleasing, and people benefit from them. Others are bitter, giving neither nourishment nor pleasure. Still others bear no fruit and are covered with thorns, wounding those who come near them. The sweet and pleasant plants are like the imams, a symbol of their speech and knowledge, which win the soul and delight the eye. The bitter, foul, and thorny ones stand for the leaders of the literalists (أَهْلُ الظَّاهِر). For this reason God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'i say further that some plants are sweet delicious and pleasing and people benefit from them others are bitter giving neither nourishment nor pleasure still others bear no fruit and are covered with thorns wounding those who come near them the sweet and pleasant plants are like the imams a symbol of their speech and knowledge which win the soul and delight the eye the bitter foul and thorny ones stand for the leaders of the literalists اهل الظاهر for this reason god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 9, NULL, 'Sayingأَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًۭا كَلِمَةًۭ طَيِّبَةًۭ كَشَجَرَةٍۢ طَيِّبَةٍ أَصْلُهَا ثَابِتٌۭ وَفَرْعُهَا فِى ٱلسَّمَآءِ تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا ۗ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ وَمَثَلُ كَلِمَةٍ خَبِيثَةٍۢ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍۢ"The example of a good word is like a good tree whose roots are firmly established and whose branches reach the heavens, giving its fruit perpetually in every season by the permission of its Lord. So God sets forth similitudes for mankind in order that they may reflect. And the similitude of a bad word is like that of a bad tree uprooted from the top of the earth, having no stability." (Ibrahim: 24-26)', '', NULL, 'Saying', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'sayingالم تر كيف ضرب الله مثلا كلمه طيبه كشجره طيبه اصلها ثابت وفرعها في السماء توتي اكلها كل حين باذن ربها ويضرب الله الامثال للناس لعلهم يتذكرون ومثل كلمه خبيثه كشجره خبيثه اجتثت من فوق الارض ما لها من قرار the example of a good word is like a good tree whose roots are firmly established and whose branches reach the heavens giving its fruit perpetually in every season by the permission of its lord so god sets forth similitudes for mankind in order that they may reflect and the similitude of a bad word is like that of a bad tree uprooted from the top of the earth having no stability ibrahim 24 26', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 10, NULL, 'I say, too, that some plants are sweet-smelling, their fragrance reviving people and healing them of every disease and ailment. The height of their goodness and fragrance is a symbol of the imam and his words, which revive people and bring them ease, while the foul, repellent, and offensive plants point to the imams of error, whose speech harms souls and may even destroy them.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'i say too that some plants are sweet smelling their fragrance reviving people and healing them of every disease and ailment the height of their goodness and fragrance is a symbol of the imam and his words which revive people and bring them ease while the foul repellent and offensive plants point to the imams of error whose speech harms souls and may even destroy them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 11, NULL, 'I say that the gazelle that yields musk and the bee that yields honey — indeed their chief (يَعْسُوب) — point to the imam. It is for this reason that the Prophet, may God bless him, said to the Commander of the Faithful, Ali:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'i say that the gazelle that yields musk and the bee that yields honey indeed their chief يعسوب point to the imam it is for this reason that the prophet may god bless him said to the commander of the faithful ali', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 12, NULL, '"You are the chief (يَعْسُوب) of the believers." (al-Majlisi, Bihar al-anwar, vol. 38, p. 144)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'you are the chief يعسوب of the believers al majlisi bihar al anwar vol 38 p 144', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 13, NULL, 'And God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'and god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 14, NULL, 'Sayingوَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًۭا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًۭا ۚ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌۭ مُّخْتَلِفٌ أَلْوَنُهُۥ فِيهِ شِفَآءٌۭ لِّلنَّاسِ"And your Lord inspired the bee to choose its homes in the mountains and on the trees and on that which they thatch; then eat from all the fruits and follow the path of your Lord skillfully, that He has made smooth for you. From within its bellies a drink of varying colors comes forth in which there is healing for mankind ..." (An-Nahl: 68-69)', '', NULL, 'Saying', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'sayingواوحي ربك الي النحل ان اتخذي من الجبال بيوتا ومن الشجر ومما يعرشون ثم كلي من كل الثمرت فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف الونه فيه شفاء للناس and your lord inspired the bee to choose its homes in the mountains and on the trees and on that which they thatch then eat from all the fruits and follow the path of your lord skillfully that he has made smooth for you from within its bellies a drink of varying colors comes forth in which there is healing for mankind an nahl 68 69', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 15, NULL, 'In the same way, I say that humankind is the highest among the animals and within all the realms of nature. Whatever advantage lies in everything created before mankind — principles, derivatives, and the realms of nature alike — returns in the end to humankind. The merits of the world, of animals, of plants, and of all other things are held within the human being; their benefit, their glory, their value, and their goodness all become plain through mankind. Were it not for mankind, the merit of all things would never appear, nor would the order of the world hold together. Nothing would be complete, no benefit would come, and nothing would be preserved, whether from plants or from animals. It is the human being who masters water and irrigates the land, bringing it under rational control and drawing it out of valleys, rivers, and wells. It is man who tills the earth, cultivates it, raises dwellings upon it, and waters plants and fields, bringing the land under his rational governance.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'in the same way i say that humankind is the highest among the animals and within all the realms of nature whatever advantage lies in everything created before mankind principles derivatives and the realms of nature alike returns in the end to humankind the merits of the world of animals of plants and of all other things are held within the human being their benefit their glory their value and their goodness all become plain through mankind were it not for mankind the merit of all things would never appear nor would the order of the world hold together nothing would be complete no benefit would come and nothing would be preserved whether from plants or from animals it is the human being who masters water and irrigates the land bringing it under rational control and drawing it out of valleys rivers and wells it is man who tills the earth cultivates it raises dwellings upon it and waters plants and fields bringing the land under his rational governance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 16, NULL, 'Beyond this, it is the human being who has put wind and air to use; it is man who discovered fire by means of flint and who crossbred animals where no such crossing had been before. Man grafted different trees together to produce fruits the world had never known. He drew jewels out of minerals and brought useful trees, seeds, and fruits under his control and governance. He guarded the welfare of animals and plants and their produce, and brought animals under his command. Man is the summit of animals, plants, minerals, and every other realm of nature. Through him the welfare of animals and of all that came before was perfected and set in order. In the same way, the imam is the summit and the peak of all human beings, their quintessence and their perfection. It is through the imam that the affairs of mankind are set in order. Just as the benefit of everything created before human beings returns to mankind, so too the benefit of all humanity, and their quintessence, returns to the imams. Human beings learn virtues and knowledge from them, and gain minds and understanding through them. It is through the imams that human welfare is safeguarded in worldly matters, in religious matters, and in the life to come. The imams guide people toward knowledge of the Creator (مَعْرِفَةُ الصَّانِع), teaching them that they must be grateful to their benefactor and how that gratitude is properly shown. It is through the imams that mankind comes to recognize the messengers and learns how they ought to be obeyed.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'beyond this it is the human being who has put wind and air to use it is man who discovered fire by means of flint and who crossbred animals where no such crossing had been before man grafted different trees together to produce fruits the world had never known he drew jewels out of minerals and brought useful trees seeds and fruits under his control and governance he guarded the welfare of animals and plants and their produce and brought animals under his command man is the summit of animals plants minerals and every other realm of nature through him the welfare of animals and of all that came before was perfected and set in order in the same way the imam is the summit and the peak of all human beings their quintessence and their perfection it is through the imam that the affairs of mankind are set in order just as the benefit of everything created before human beings returns to mankind so too the benefit of all humanity and their quintessence returns to the imams human beings learn virtues and knowledge from them and gain minds and understanding through them it is through the imams that human welfare is safeguarded in worldly matters in religious matters and in the life to come the imams guide people toward knowledge of the creator معرفه الصانع teaching them that they must be grateful to their benefactor and how that gratitude is properly shown it is through the imams that mankind comes to recognize the messengers and learns how they ought to be obeyed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 17, NULL, 'Just as the benefit of all animals and of everything before them returns to mankind, so that man became their leader, so too the benefit of all human beings returns to the imams, who became their leaders, their commanders, and their restrainers. Were it not for the imams — for the direction and guidance they give humanity, for their protection of human welfare in this life and the next, and for their urging people to gain virtues and to shun vices and the habits of animals — there would be no difference between beasts and human beings; indeed, the animals would be the better of the two. If man did not accept the training he needs in order to gain virtues for his soul, and did not learn to rouse his intellect through the imams, he would be worse off than the animals, since animals are not as inclined to evil as human beings are, and animals hold many benefits. Without intellect and religion, man would be given over wholly to evil and corruption. It is on this account that God, the Exalted and Glorious, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'just as the benefit of all animals and of everything before them returns to mankind so that man became their leader so too the benefit of all human beings returns to the imams who became their leaders their commanders and their restrainers were it not for the imams for the direction and guidance they give humanity for their protection of human welfare in this life and the next and for their urging people to gain virtues and to shun vices and the habits of animals there would be no difference between beasts and human beings indeed the animals would be the better of the two if man did not accept the training he needs in order to gain virtues for his soul and did not learn to rouse his intellect through the imams he would be worse off than the animals since animals are not as inclined to evil as human beings are and animals hold many benefits without intellect and religion man would be given over wholly to evil and corruption it is on this account that god the exalted and glorious said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 18, NULL, 'Al-Anfal: 22إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ"For the worst of beasts in the sight of God are the deaf and dumb, those who understand not." (Al-Anfal: 22)', '', NULL, 'Al-Anfal: 22', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'al anfal 22ان شر الدواب عند الله الصم البكم الذين لا يعقلون for the worst of beasts in the sight of god are the deaf and dumb those who understand not al anfal 22', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 19, NULL, 'The Exalted also said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'the exalted also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 20, NULL, 'Al-A''raf: 179أُو۟لَٓئِكَ كَٱلْأَنْعَمِ بَلْ هُمْ أَضَلُّ ۚ أُو۟لَٓئِكَ هُمُ ٱلْغَفِلُونَ"They are like cattle, nay, more misguided, for they are heedless of warning." (Al-Araf: 179)', '', NULL, 'Al-A''raf: 179', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'al araf 179اوليك كالانعم بل هم اضل اوليك هم الغفلون they are like cattle nay more misguided for they are heedless of warning al araf 179', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 21, NULL, 'Were there no humanity, there would be no wisdom in the creation of animals and plants, for there would be no one to benefit from them. In the same way, were it not for the imams, there would be no wisdom in the creation of humanity, and their superiority would never become plain. Human beings have been created for religion and for the gaining of virtues and knowledge. So learn knowledge and religion from the imams, for through them religion is established and made complete. If the excellence of man were not made plain through religion, then the value of plants and animals would not become known either, and there would be no wisdom in the creation of humanity, plants, and animals. And if there were no wisdom in their creation, there would be no wisdom in the creation of all the worlds.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'were there no humanity there would be no wisdom in the creation of animals and plants for there would be no one to benefit from them in the same way were it not for the imams there would be no wisdom in the creation of humanity and their superiority would never become plain human beings have been created for religion and for the gaining of virtues and knowledge so learn knowledge and religion from the imams for through them religion is established and made complete if the excellence of man were not made plain through religion then the value of plants and animals would not become known either and there would be no wisdom in the creation of humanity plants and animals and if there were no wisdom in their creation there would be no wisdom in the creation of all the worlds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 22, NULL, 'It is therefore true to say that all the worlds, the whole of natural creation, have been created for humanity, and that humanity has been created for the imams: to receive religion from them, to be perfected through them, and to make plain their virtues, their order, and their foundation. Since all the worlds and all creatures were created for the imams, and all the benefits of the worlds belong to them, and the rest of creation depends on them and stands to them as children stand to a parent, whatever they bestow upon creation is given by their favor, their generosity, and their mercy. If they withhold anything, they are under no obligation to give it, nor do they owe any gratitude for it. Whoever takes anything from this world and what it holds without the permission and approval of the imam has taken what is haram, forbidden, and has committed an act of usurpation. Thus God said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'it is therefore true to say that all the worlds the whole of natural creation have been created for humanity and that humanity has been created for the imams to receive religion from them to be perfected through them and to make plain their virtues their order and their foundation since all the worlds and all creatures were created for the imams and all the benefits of the worlds belong to them and the rest of creation depends on them and stands to them as children stand to a parent whatever they bestow upon creation is given by their favor their generosity and their mercy if they withhold anything they are under no obligation to give it nor do they owe any gratitude for it whoever takes anything from this world and what it holds without the permission and approval of the imam has taken what is haram forbidden and has committed an act of usurpation thus god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 23, NULL, 'Al-Hashr: 7أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ"And that which God bestows on the Messenger from the people of the villages, it is for God and His Messenger." (Al-Hashr: 7)', '', NULL, 'Al-Hashr: 7', NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'al hashr 7افاء الله علي رسوله من اهل القري فلله وللرسول and that which god bestows on the messenger from the people of the villages it is for god and his messenger al hashr 7', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 24, NULL, 'The word "bestowal" (اَلْفَيْء) means "return," and it is for this reason that a shadow is called اَلْفَيْء, because it returns to the place from which it first came. The whole world comes from the fortune and property of the imams, and whatever returns to their property is, in truth, a اَلْفَيْء, a return.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'the word bestowal الفيء means return and it is for this reason that a shadow is called الفيء because it returns to the place from which it first came the whole world comes from the fortune and property of the imams and whatever returns to their property is in truth a الفيء a return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 25, NULL, 'I say further that plants surpass the earth by a single added spirit, the spirit of growth (رُوحُ النَّمَاء), and so the earth becomes subject to the plants that grow upon it and draw their strength from it. Animals surpass plants by yet another spirit added to the spirit of growth, the spirit of sensation (رُوحُ الْحِسّ), and so they master the earth by moving across it and master the plants by eating them. Since human beings surpass animals by the spirit of articulate speech, or reason (رُوحُ النُّطْق), they take charge of the earth: they build, sow, and plant upon it, bringing it under their wisdom and control. They eat plants and fruits, using what they wish and burning what they will. Man also masters the animals, riding those he needs, slaughtering some, milking others, shearing their wool, and putting them to work as he sees fit, even against the animals'' own will.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'i say further that plants surpass the earth by a single added spirit the spirit of growth روح النماء and so the earth becomes subject to the plants that grow upon it and draw their strength from it animals surpass plants by yet another spirit added to the spirit of growth the spirit of sensation روح الحس and so they master the earth by moving across it and master the plants by eating them since human beings surpass animals by the spirit of articulate speech or reason روح النطق they take charge of the earth they build sow and plant upon it bringing it under their wisdom and control they eat plants and fruits using what they wish and burning what they will man also masters the animals riding those he needs slaughtering some milking others shearing their wool and putting them to work as he sees fit even against the animals own will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 26, NULL, 'When the imam takes up his charge, he is granted added spirits, added powers, and a purity that no ordinary human being possesses. So the highest purity in the human being is joined in the imam to the subtlety and fineness of nature. The peak of the sentient animals, their choicest elements, the furthest happiness of the celestial spheres, the balance of nature, and the subtlest influence of all the celestial spheres and stars are so joined in him that he becomes the quintessence of the whole world. Then the subtleties of the spirit of reason, of pure thought, and of the whole intellectual spirit are united in the imam, together with the entire sanctified spirit (رُوحُ الْقُدْس). Man possesses only a portion of this spirit, no more than what he receives from the imam, and no more than the imam chooses to grant by his grace. Bound up with this is the creative spirit (رُوحُ الْإِبْدَاعِ), which is the perfect seventh spirit that God has prepared for humanity in the world of reward. It is the spirit of Oneness (رُوحُ الْوَحْدَةِ).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'when the imam takes up his charge he is granted added spirits added powers and a purity that no ordinary human being possesses so the highest purity in the human being is joined in the imam to the subtlety and fineness of nature the peak of the sentient animals their choicest elements the furthest happiness of the celestial spheres the balance of nature and the subtlest influence of all the celestial spheres and stars are so joined in him that he becomes the quintessence of the whole world then the subtleties of the spirit of reason of pure thought and of the whole intellectual spirit are united in the imam together with the entire sanctified spirit روح القدس man possesses only a portion of this spirit no more than what he receives from the imam and no more than the imam chooses to grant by his grace bound up with this is the creative spirit روح الابداع which is the perfect seventh spirit that god has prepared for humanity in the world of reward it is the spirit of oneness روح الوحده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 27, NULL, 'These are some of the merits that God, the Exalted, has bestowed upon him, over and above what he attains purely through purity of character, generosity, giving, forbearance, courage, and other qualities that the likes of us cannot count, along with his freedom from every impurity, shame, and defect. So when God gathered in the imams all these faculties, merits, and spirits, over and above what mankind already possesses, He made all humanity subject to them, giving them charge over everything created before mankind — animals, plants, earth, and minerals — and making all of it subject to the imams. This is like the way human beings dominate the animals and rule over them by virtue of one added spirit, the way animals rule the plants by virtue of one added spirit, and the way plants dominate the earth by virtue of yet another added spirit. Moreover, the great number of spirits residing in the imams sets the measure of their control and dominion over humanity, giving them the right to rule over people convincingly, in keeping with what those faculties and spirits require, and in light of what I described earlier concerning human beings. It is therefore not for human beings to withdraw themselves from the imam''s domain and reign, just as it is not for animals to withdraw themselves from the control of man. Those animals that refuse to submit to human control, such as beasts of prey that offer no benefit or merit, are judged by reason and by law to be lawfully killed, destroyed, and removed, because they refuse to obey human beings and to remain under the authority of their supremacy.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'these are some of the merits that god the exalted has bestowed upon him over and above what he attains purely through purity of character generosity giving forbearance courage and other qualities that the likes of us cannot count along with his freedom from every impurity shame and defect so when god gathered in the imams all these faculties merits and spirits over and above what mankind already possesses he made all humanity subject to them giving them charge over everything created before mankind animals plants earth and minerals and making all of it subject to the imams this is like the way human beings dominate the animals and rule over them by virtue of one added spirit the way animals rule the plants by virtue of one added spirit and the way plants dominate the earth by virtue of yet another added spirit moreover the great number of spirits residing in the imams sets the measure of their control and dominion over humanity giving them the right to rule over people convincingly in keeping with what those faculties and spirits require and in light of what i described earlier concerning human beings it is therefore not for human beings to withdraw themselves from the imams domain and reign just as it is not for animals to withdraw themselves from the control of man those animals that refuse to submit to human control such as beasts of prey that offer no benefit or merit are judged by reason and by law to be lawfully killed destroyed and removed because they refuse to obey human beings and to remain under the authority of their supremacy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 28, NULL, 'In the same way, those who hold themselves apart from obedience to the imam show themselves to be like wild beasts, whose killing, destruction, and removal becomes lawful, on account of their rejection of the imams'' rule as required by religious law, by intellect, by nature, and by sound governance.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'in the same way those who hold themselves apart from obedience to the imam show themselves to be like wild beasts whose killing destruction and removal becomes lawful on account of their rejection of the imams rule as required by religious law by intellect by nature and by sound governance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 29, NULL, 'But whoever obeys the imams and submits to their rulings in this world will escape the sword and punishment here, and will live in peace, well-being, and justice. It is a duty upon the imam, by the norm of kingship, the demands of nature, sound policy, and law, to guard the welfare of mankind, just as man, in governing the animals, guards their well-being, their nourishment, and their flourishing. Whoever submits to the imams'' rule over his own spirit and body will be steeped in knowledge and wisdom, quickened by it and enabled to stand out among other people, living in the tranquillity of knowledge and enjoying its fragrance. Such a person will leave this abode of deeds for the abode of recompense in an upright form, fully ready to receive his recompense and eternal life.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'but whoever obeys the imams and submits to their rulings in this world will escape the sword and punishment here and will live in peace well being and justice it is a duty upon the imam by the norm of kingship the demands of nature sound policy and law to guard the welfare of mankind just as man in governing the animals guards their well being their nourishment and their flourishing whoever submits to the imams rule over his own spirit and body will be steeped in knowledge and wisdom quickened by it and enabled to stand out among other people living in the tranquillity of knowledge and enjoying its fragrance such a person will leave this abode of deeds for the abode of recompense in an upright form fully ready to receive his recompense and eternal life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 30, NULL, 'Whoever submits to the imams'' rule outwardly but not inwardly will fall into the torment of ignorance, bewilderment, doubt, discord, and regret, and will reach the abode of recompense in a crooked form, unready to receive recompense, and will remain in torment and punishment.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'whoever submits to the imams rule outwardly but not inwardly will fall into the torment of ignorance bewilderment doubt discord and regret and will reach the abode of recompense in a crooked form unready to receive recompense and will remain in torment and punishment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the ladder of creation', '4. The Ladder of Creation', 31, NULL, 'Editorial note (tradition-grounded). The ascending order this chapter traces — mineral, plant, animal, human — echoes a related teaching preserved in this tradition, which holds that the principal purpose of the celestial spheres was to generate minerals, plants, animals, and human seed, each sphere shaping the terrestrial realm according to its nature. The wider tradition also explains why creation should culminate in the human being: it calls the world itself the Macrocosm, or Great Human, a body possessing distinct organs as humanity does — so that the summit of the outer world and the perfection of the human mirror a single order. That same teaching frames such ascent as a passage from potentiality (bi-al-quwwa) into actuality (bi-al-fil), and from a primary perfection (kamal awwal) toward a secondary one — the very completion this chapter locates in mankind, and above mankind, in the imam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 4 the ladder of creation', 'editorial note tradition grounded the ascending order this chapter traces mineral plant animal human echoes a related teaching preserved in this tradition which holds that the principal purpose of the celestial spheres was to generate minerals plants animals and human seed each sphere shaping the terrestrial realm according to its nature the wider tradition also explains why creation should culminate in the human being it calls the world itself the macrocosm or great human a body possessing distinct organs as humanity does so that the summit of the outer world and the perfection of the human mirror a single order that same teaching frames such ascent as a passage from potentiality bi al quwwa into actuality bi al fil and from a primary perfection kamal awwal toward a secondary one the very completion this chapter locates in mankind and above mankind in the imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 0, NULL, 'We further say that human beings, at all times and in every moment, look after the welfare of animals, protecting them from what harms them and leading them toward what benefits them. A man guards their watering places and their grazing grounds, their seasons of mating and of bearing young; he shields them from destruction and from surroundings that would spoil their eating and drinking. Cattle often crave what would harm them, and a man holds them back, safeguarding their well-being even against the animals'' own will.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we further say that human beings at all times and in every moment look after the welfare of animals protecting them from what harms them and leading them toward what benefits them a man guards their watering places and their grazing grounds their seasons of mating and of bearing young he shields them from destruction and from surroundings that would spoil their eating and drinking cattle often crave what would harm them and a man holds them back safeguarding their well being even against the animals own will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 1, NULL, 'In the same way, the imam (ع) protects the outcome of human affairs, their welfare, and all their conditions, their means of livelihood, their dealings, and their hidden interests, out of compassion for them. Were it not for the imam, a man would have no order in his worldly affairs, no safety or escape from those stronger than himself, no security from disputes, and no protection from punishment in the hereafter. What is more, a man endures the pain animals cause him and bears their bad behavior patiently, hoping they will improve; for the judgment of wisdom requires that one who possesses knowledge must not destroy, harm, or kill any living creature without good reason, but is bound instead to save it from destruction. In the same way, wisdom requires that property be protected from ruin and never be withheld from human use. So too the imam endures the misconduct of people and bears pain and hardship at their hands, since the principles of sovereignty and the wisdom of sound judgment require that the ignorant be guided, their welfare protected, and they themselves shielded from perdition and ruin, in the hope that they will one day return to good conduct and attain salvation. The imam does not look upon people with contempt for their ignorance or their disobedience; he looks upon them with an eye of mercy.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'in the same way the imam ع protects the outcome of human affairs their welfare and all their conditions their means of livelihood their dealings and their hidden interests out of compassion for them were it not for the imam a man would have no order in his worldly affairs no safety or escape from those stronger than himself no security from disputes and no protection from punishment in the hereafter what is more a man endures the pain animals cause him and bears their bad behavior patiently hoping they will improve for the judgment of wisdom requires that one who possesses knowledge must not destroy harm or kill any living creature without good reason but is bound instead to save it from destruction in the same way wisdom requires that property be protected from ruin and never be withheld from human use so too the imam endures the misconduct of people and bears pain and hardship at their hands since the principles of sovereignty and the wisdom of sound judgment require that the ignorant be guided their welfare protected and they themselves shielded from perdition and ruin in the hope that they will one day return to good conduct and attain salvation the imam does not look upon people with contempt for their ignorance or their disobedience he looks upon them with an eye of mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 2, NULL, 'We also say that a man endures pain and hardship from his young children and prays for them, hoping they will grow into their full human potential and be rightly guided. In the same way, the imam endures pain and hardship from people out of mercy and compassion, a compassion like that of parents for their children. He provides for them in both worldly and religious matters, hoping they will be rightly guided and saved.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we also say that a man endures pain and hardship from his young children and prays for them hoping they will grow into their full human potential and be rightly guided in the same way the imam endures pain and hardship from people out of mercy and compassion a compassion like that of parents for their children he provides for them in both worldly and religious matters hoping they will be rightly guided and saved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 3, NULL, 'We say further that a teacher endures hardship for the sake of young boys, compelling them to learn the sciences and good conduct, while the child resists, resenting the teacher and preferring play and idleness. The teacher cares for the child and bears with him, knowing that if the child could see the benefit he stands to gain, he would not resent his teacher. The teacher also knows that when the boy comes of age he will recognize the worth of that discipline and feel grateful, regretting his earlier failings and disobedience. In the same way, the imam guides people toward their own worldly and religious good, even as they resist it and object to how he deals with them. In time, when the benefit becomes plain to them, they regret their disobedience.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we say further that a teacher endures hardship for the sake of young boys compelling them to learn the sciences and good conduct while the child resists resenting the teacher and preferring play and idleness the teacher cares for the child and bears with him knowing that if the child could see the benefit he stands to gain he would not resent his teacher the teacher also knows that when the boy comes of age he will recognize the worth of that discipline and feel grateful regretting his earlier failings and disobedience in the same way the imam guides people toward their own worldly and religious good even as they resist it and object to how he deals with them in time when the benefit becomes plain to them they regret their disobedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 4, NULL, 'We also say that because a man is made from various opposing natures, he is never wholly free of natural sickness, illness, and disease. The influence of time and place, of the celestial spheres and the stars, the effects of food and of other opposing elements in his nature, over-indulgence, too little eating, exhaustion, sexual intercourse, and other such things all give rise to illness and disease. Yet people had no knowledge of medicine. Had they stayed uninformed and ignorant in the face of so many illnesses, most of them would have died and perished, bringing ruin upon the world. But God, the Exalted, created a cure to match each illness, and He inspired the prophets and imams, so that they came to understand the benefits of remedies and to recognize poisons and illnesses alike. They taught mankind, opening for them the way of medicine, so that people began to build on that foundation and to improve it through experience and practice, just as they made progress in every other trade, craft, and science, such as engineering, agriculture, navigation, and the rest, until physicians arose among mankind to treat the sick, gathering remedies from far and distant lands. They labored in that field, some for profit and some for the good of humanity, treating patients at times with wholesome and pleasant remedies and at other times with hot and bitter ones. A patient may loathe the bitter, foul-smelling substance that will cure him, yet the physician makes him drink it, willing or unwilling, assuring him of the good it will do, warning him that he faces death if he refuses, or gently coaxing him to endure the hardship. At times the physician forbids the patient to eat and drink, even while he craves both. He may forbid foods the patient enjoys and that agreed with him in health. He may give him something harsh that strains an already weakened body, all while the patient stands in danger of death. And if medicine alone fails, the physician may order lancing, the opening of a wound, cauterization, or the amputation of a limb, in the hope of saving the rest.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we also say that because a man is made from various opposing natures he is never wholly free of natural sickness illness and disease the influence of time and place of the celestial spheres and the stars the effects of food and of other opposing elements in his nature over indulgence too little eating exhaustion sexual intercourse and other such things all give rise to illness and disease yet people had no knowledge of medicine had they stayed uninformed and ignorant in the face of so many illnesses most of them would have died and perished bringing ruin upon the world but god the exalted created a cure to match each illness and he inspired the prophets and imams so that they came to understand the benefits of remedies and to recognize poisons and illnesses alike they taught mankind opening for them the way of medicine so that people began to build on that foundation and to improve it through experience and practice just as they made progress in every other trade craft and science such as engineering agriculture navigation and the rest until physicians arose among mankind to treat the sick gathering remedies from far and distant lands they labored in that field some for profit and some for the good of humanity treating patients at times with wholesome and pleasant remedies and at other times with hot and bitter ones a patient may loathe the bitter foul smelling substance that will cure him yet the physician makes him drink it willing or unwilling assuring him of the good it will do warning him that he faces death if he refuses or gently coaxing him to endure the hardship at times the physician forbids the patient to eat and drink even while he craves both he may forbid foods the patient enjoys and that agreed with him in health he may give him something harsh that strains an already weakened body all while the patient stands in danger of death and if medicine alone fails the physician may order lancing the opening of a wound cauterization or the amputation of a limb in the hope of saving the rest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 5, NULL, 'A person of sound mind will accept all of this, persuaded that the physician knows his condition better than he does himself and that the physician is a trustworthy guarantor who seeks only his welfare and his recovery. But a person lacking in reason will resent and despise the physician, while the physician meets him with understanding when he sees a man of cold constitution stricken with illness. Knowing that without treatment the patient will die, the physician, out of kindness and compassion, restrains him and forces him to drink the medicine. The patient may curse him, grow agitated, and threaten to strike him, but the physician bears it patiently, knowing that if the patient were aware and rational he would not resist treatment. The physician is not turned aside by the patient''s bad behavior; he remains kind and continues treating him until his health is restored.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'a person of sound mind will accept all of this persuaded that the physician knows his condition better than he does himself and that the physician is a trustworthy guarantor who seeks only his welfare and his recovery but a person lacking in reason will resent and despise the physician while the physician meets him with understanding when he sees a man of cold constitution stricken with illness knowing that without treatment the patient will die the physician out of kindness and compassion restrains him and forces him to drink the medicine the patient may curse him grow agitated and threaten to strike him but the physician bears it patiently knowing that if the patient were aware and rational he would not resist treatment the physician is not turned aside by the patients bad behavior he remains kind and continues treating him until his health is restored', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 6, NULL, 'In the same way, spiritual diseases multiply. They arise from disputes among people; from their arbitrary desires and their leaning toward leisure, comfort, and self-display; from innovation, worldly ambitions, clashing doctrines, contradictory statements, and conflicting opinions; and from the lower self that goads a man toward evil, while the night is dark and the path obscure, and people know nothing of the medicine of the soul, nothing of its cure, of how to preserve its health, or of how to guard against the conditions and things that harm it, and nothing of the ways and paths of religion. Then humanity needs a guide and a physician to treat their illnesses, show them right action, and save their spirits. This must be done with gentleness, compassion, counsel, affection, forbearance, and encouragement, calling for many times more patience and compassion than the physicians of the body show. There must be no greed in their treatment, no seeking of personal gain, no warding off of harm for selfish ends. These guides must be the most reliable and trustworthy keepers of souls and of religion, surpassing even the most dependable physicians of the body in skill, experience, and knowledge.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'in the same way spiritual diseases multiply they arise from disputes among people from their arbitrary desires and their leaning toward leisure comfort and self display from innovation worldly ambitions clashing doctrines contradictory statements and conflicting opinions and from the lower self that goads a man toward evil while the night is dark and the path obscure and people know nothing of the medicine of the soul nothing of its cure of how to preserve its health or of how to guard against the conditions and things that harm it and nothing of the ways and paths of religion then humanity needs a guide and a physician to treat their illnesses show them right action and save their spirits this must be done with gentleness compassion counsel affection forbearance and encouragement calling for many times more patience and compassion than the physicians of the body show there must be no greed in their treatment no seeking of personal gain no warding off of harm for selfish ends these guides must be the most reliable and trustworthy keepers of souls and of religion surpassing even the most dependable physicians of the body in skill experience and knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 7, NULL, 'For the risk and the danger in treating the soul are greater than those in treating the body, and errors in it can be far more severe. The need for such a guide is as inescapable to the intellect as the need for a physician is inescapable in practice. This knowing and compassionate physician of souls is the imam in every age and time. Were it not for the mercy, compassion, and kindness of the imams toward all of creation, people would perish in both their worldly and their religious affairs, in this life and the next. The imams treat created beings with delicate kindness, forbearance, and gentleness. They do not dwell on people''s failure to obey, their bad manners, or their evil deeds; they look upon them instead with an eye of mercy, working to preserve their spiritual health and cure their illnesses, sometimes through a balanced and delicate diet, guarding their spiritual well-being through subtle sciences that strengthen the soul, at other times by withholding nourishment so that it neither sickens nor burdens. At still other times they compel people to drink a bitter, foul-smelling medicine so as to drive out the corrupting humors (اَلْكَيْمُوسَات). At yet other times they impose a strict regimen until a person is brought to the utmost humility, all the while offering encouragement and warning, just as the Commander of the Faithful [al-Hakim] does with these people. Even as they go on desiring corruption and he sees no good in them, he remains patient with the pain they cause. We pray that He allows us to be among those who benefit from the treatment of the imam of the age, and that He does not place us among those who require burning or the amputation of limbs through his turning away from us. Were it not for the mercy of the imams, not a single person would remain on the face of the earth, just as God has said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'for the risk and the danger in treating the soul are greater than those in treating the body and errors in it can be far more severe the need for such a guide is as inescapable to the intellect as the need for a physician is inescapable in practice this knowing and compassionate physician of souls is the imam in every age and time were it not for the mercy compassion and kindness of the imams toward all of creation people would perish in both their worldly and their religious affairs in this life and the next the imams treat created beings with delicate kindness forbearance and gentleness they do not dwell on peoples failure to obey their bad manners or their evil deeds they look upon them instead with an eye of mercy working to preserve their spiritual health and cure their illnesses sometimes through a balanced and delicate diet guarding their spiritual well being through subtle sciences that strengthen the soul at other times by withholding nourishment so that it neither sickens nor burdens at still other times they compel people to drink a bitter foul smelling medicine so as to drive out the corrupting humors الكيموسات at yet other times they impose a strict regimen until a person is brought to the utmost humility all the while offering encouragement and warning just as the commander of the faithful al hakim does with these people even as they go on desiring corruption and he sees no good in them he remains patient with the pain they cause we pray that he allows us to be among those who benefit from the treatment of the imam of the age and that he does not place us among those who require burning or the amputation of limbs through his turning away from us were it not for the mercy of the imams not a single person would remain on the face of the earth just as god has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'the physician of souls', '5. The Physician of Souls', 8, NULL, 'Fatir: 45وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍۢ', '', 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍۢ', 'Fatir: 45', 35, 45, 'degrees of excellence 5 the physician of souls', 'fatir 45ولو يواخذ الله الناس بما كسبوا ما ترك علي ظهرها من دابه', 'ولو يواخذ الله الناس بما كسبوا ما ترك علي ظهرها من دابه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 9, NULL, 'If God took humanity to task for what they deserve, He would not leave a [single] living creature on the surface of the earth ... (Fatir: 45)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'if god took humanity to task for what they deserve he would not leave a single living creature on the surface of the earth fatir 45', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 10, NULL, 'We also say that wise men and men of insight, when they cultivate the world, regard their work as an image of God''s own acts in creating the world, ordering its surroundings, and preserving human welfare. When they find good, fertile land, they know it will take seed and bring forth growth. When they discover water in distant deep valleys or beneath the ground, they labor to draw it out by digging canals and wells, directing that water to the fertile lands. They see no wisdom in leaving good, fertile land idle and wasted, or in leaving water untapped, for they are moved by compassion for living creatures and by concern for their welfare and the flourishing of the world.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we also say that wise men and men of insight when they cultivate the world regard their work as an image of gods own acts in creating the world ordering its surroundings and preserving human welfare when they find good fertile land they know it will take seed and bring forth growth when they discover water in distant deep valleys or beneath the ground they labor to draw it out by digging canals and wells directing that water to the fertile lands they see no wisdom in leaving good fertile land idle and wasted or in leaving water untapped for they are moved by compassion for living creatures and by concern for their welfare and the flourishing of the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 11, NULL, 'In the same way, when the imams see people ready to receive the seed of wisdom and knowledge, even though they may be very far from truly being able to receive it, the imams pour great effort into digging channels through preparatory religious exercises on many occasions. People may not grasp the purpose of such an exercise until they come to see its wisdom and grow prepared and able to receive it. And when the imams cannot raise people to that level through religious exercise alone, they set wisdom within dense symbols, whether in words or in deeds, so that people may take in those symbols and gradually arrive at their meaning, and so be lifted to that level of understanding.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'in the same way when the imams see people ready to receive the seed of wisdom and knowledge even though they may be very far from truly being able to receive it the imams pour great effort into digging channels through preparatory religious exercises on many occasions people may not grasp the purpose of such an exercise until they come to see its wisdom and grow prepared and able to receive it and when the imams cannot raise people to that level through religious exercise alone they set wisdom within dense symbols whether in words or in deeds so that people may take in those symbols and gradually arrive at their meaning and so be lifted to that level of understanding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 12, NULL, 'It is therefore necessary to believe in the supreme leadership, the imamate, of the imam of the age; to know that he is the head of the world and the vicegerent of God over His creation; and to raise no objection to any of the imams'' commands, prohibitions, deeds, or teachings. One must know, in a general way, that all of this holds wisdom within it and is for the welfare of creation. The true meaning of a particular matter may at times be hard for a believer to grasp, but in the end its benefit will become clear, just as many things once unknown have in time become plain and clear. So too, in much of the sharia, the faithful do not at first understand the Lawgiver''s purpose or the wisdom behind a ruling and may feel resistance to it; yet those to whom God grants recognition of its meaning come to perceive the wisdom within it. In the same way, many people meet things in the world whose wisdom they do not understand and wrongly conclude that no benefit lies in them, only to realize later that wisdom was there after all.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'it is therefore necessary to believe in the supreme leadership the imamate of the imam of the age to know that he is the head of the world and the vicegerent of god over his creation and to raise no objection to any of the imams commands prohibitions deeds or teachings one must know in a general way that all of this holds wisdom within it and is for the welfare of creation the true meaning of a particular matter may at times be hard for a believer to grasp but in the end its benefit will become clear just as many things once unknown have in time become plain and clear so too in much of the sharia the faithful do not at first understand the lawgivers purpose or the wisdom behind a ruling and may feel resistance to it yet those to whom god grants recognition of its meaning come to perceive the wisdom within it in the same way many people meet things in the world whose wisdom they do not understand and wrongly conclude that no benefit lies in them only to realize later that wisdom was there after all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 13, NULL, 'There are countless things whose very creation people count as harmful and destructive, seeing in them no wisdom and no benefit, yet when they come to understand their wisdom they grow calm and their objections fall away. Whoever recognizes the Wise One (al-Hakim) and grants that He is wise must inevitably grant that everything the Wise One does is full of wisdom, that He would do nothing devoid of wisdom, and that He would command, forbid, or say nothing except out of wisdom. A futile act is not permissible for the Wise One; and were it permissible for the Wise One to act, speak, command, or forbid without wisdom, that would be a vain act, and vain acts are not permissible for the Wise One. Whoever does a thing whose doing and whose leaving undone are entirely alike acts foolishly and steps outside the domain of wisdom.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'there are countless things whose very creation people count as harmful and destructive seeing in them no wisdom and no benefit yet when they come to understand their wisdom they grow calm and their objections fall away whoever recognizes the wise one al hakim and grants that he is wise must inevitably grant that everything the wise one does is full of wisdom that he would do nothing devoid of wisdom and that he would command forbid or say nothing except out of wisdom a futile act is not permissible for the wise one and were it permissible for the wise one to act speak command or forbid without wisdom that would be a vain act and vain acts are not permissible for the wise one whoever does a thing whose doing and whose leaving undone are entirely alike acts foolishly and steps outside the domain of wisdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 14, NULL, 'Furthermore, if it is not permissible for the Wise One to perform an act whose existence and non-existence come to the same thing, how then could the imam perform an act when wisdom lies in something other than what he has done, or in its very opposite, and when the welfare of creation lies elsewhere? The imam is wise without qualification, and his bestowal of wisdom upon any of his servants makes them wise. Whoever acts without wisdom and goodness acts corruptly and in vain; and may God protect us from those who hold such a belief about the imam of the age. To hold such a belief is to say that this person has departed from wisdom, and whoever departs from wisdom has departed from the domain of his imamate, and that is a departure from the faith. May God protect us and all believers from any such doubt, notion, or belief, and may He grant us contentment and unquestioning submission (اَلتَّسْلِيم).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'furthermore if it is not permissible for the wise one to perform an act whose existence and non existence come to the same thing how then could the imam perform an act when wisdom lies in something other than what he has done or in its very opposite and when the welfare of creation lies elsewhere the imam is wise without qualification and his bestowal of wisdom upon any of his servants makes them wise whoever acts without wisdom and goodness acts corruptly and in vain and may god protect us from those who hold such a belief about the imam of the age to hold such a belief is to say that this person has departed from wisdom and whoever departs from wisdom has departed from the domain of his imamate and that is a departure from the faith may god protect us and all believers from any such doubt notion or belief and may he grant us contentment and unquestioning submission التسليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 15, NULL, 'We also say that free-grazing livestock, for all their own benefits and worth, cannot do without a shepherd to tend them, care for and protect them, choose their pasture and watering places, and guard them from thieves and beasts of prey. Without someone to take on that role, they would perish, unable to manage their own affairs, defend themselves against predators, or secure their own good and well-being.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we also say that free grazing livestock for all their own benefits and worth cannot do without a shepherd to tend them care for and protect them choose their pasture and watering places and guard them from thieves and beasts of prey without someone to take on that role they would perish unable to manage their own affairs defend themselves against predators or secure their own good and well being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 16, NULL, 'People are likewise like sheep: without a shepherd to protect them, they would perish. The imam is their shepherd, safeguarding their worldly and religious affairs and protecting them from worldly and religious enemies alike. Were that role abandoned, not even two people would remain, nor would a single soul escape punishment. It is for this reason that people in every land are called subjects (رَعِيَّة), because they live under the care of their shepherd, while the true shepherd is the imam, and all others who lay claim to that role are wolves devouring the flock.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'people are likewise like sheep without a shepherd to protect them they would perish the imam is their shepherd safeguarding their worldly and religious affairs and protecting them from worldly and religious enemies alike were that role abandoned not even two people would remain nor would a single soul escape punishment it is for this reason that people in every land are called subjects رعيه because they live under the care of their shepherd while the true shepherd is the imam and all others who lay claim to that role are wolves devouring the flock', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 17, NULL, 'We hold that the world is like the human body. If the body had no head, it would be a rotting corpse of no use to anyone. In the same way, if the world had no head, leader, or master (سَائِس) to guide its worldly and religious affairs, people would turn into beasts devouring one another. The world would not last even a single day, and there would be no wisdom in its creation. The imam is indeed the head of the world, its leader and its master.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we hold that the world is like the human body if the body had no head it would be a rotting corpse of no use to anyone in the same way if the world had no head leader or master سايس to guide its worldly and religious affairs people would turn into beasts devouring one another the world would not last even a single day and there would be no wisdom in its creation the imam is indeed the head of the world its leader and its master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 18, NULL, 'We say further that among the organs of the body there are disparities (اَلتَّفَاوُت) and differences in degrees of excellence (التَّفَاضُل); the foremost and finest of them is the head. In the head resides the face, the face by which each human being is known and set apart from every other. Among the inner organs, the finest is the brain, their chief and the seat of the intellect. The imam holds a place in the world like that of the head among the limbs and like that of the brain among the inner organs. All the affairs of creation turn about him, just as all the actions of the body turn about the brain. Among all the faculties and spirits in a man, the finest is the intellect, and the imam is the Universal Intellect (الْعَقْلُ الْكُلِّي) in the world, the one in whom and through whom all the people of the world are made one.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'we say further that among the organs of the body there are disparities التفاوت and differences in degrees of excellence التفاضل the foremost and finest of them is the head in the head resides the face the face by which each human being is known and set apart from every other among the inner organs the finest is the brain their chief and the seat of the intellect the imam holds a place in the world like that of the head among the limbs and like that of the brain among the inner organs all the affairs of creation turn about him just as all the actions of the body turn about the brain among all the faculties and spirits in a man the finest is the intellect and the imam is the universal intellect العقل الكلي in the world the one in whom and through whom all the people of the world are made one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 19, NULL, 'As was said earlier, leadership in nature is present in everything. It is found among animals and birds: the stallion, for instance, protects and disciplines the mares. So too the rooster protects its fowl and disciplines it. Each species protects its young according to its capacity, defends its females, and guides the weak among them as each one needs, benefiting from and learning from those above it. The crane obeys its leader, and the bee obeys its queen.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'as was said earlier leadership in nature is present in everything it is found among animals and birds the stallion for instance protects and disciplines the mares so too the rooster protects its fowl and disciplines it each species protects its young according to its capacity defends its females and guides the weak among them as each one needs benefiting from and learning from those above it the crane obeys its leader and the bee obeys its queen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the physician of souls', '5. The Physician of Souls', 20, NULL, 'God, the Exalted, created the world and ordered its creatures — as we have described in some measure earlier — according to this pattern of classification, disparity, and gradation in degrees of excellence, with varying levels of strength, nobility, and rank, so that it would be plain that within every species and genus there is a peak, a summit, and a chief in nobility and merit. By the same reasoning, all of mankind too must have a peak and summit in nobility and merit, to serve as their leader and guide in the world. It has thus been established that headship and leadership are necessary features of nature and creation, and of natural disposition and intuition as well, and that even those who deny revelation and religion cannot deny, whether by reason or by plain observation, that the world requires leadership, headship, and authority, for these are obligatory and necessary. It is therefore mandatory that this leader be the best of all people: the most noble, the most perfect, the most knowing, and the most pure, in keeping with the arguments we have drawn from creation and nature. The foremost must be the imam in all things, the chief and the head. The title supreme leader (اَلْإِمَام) cannot be given to the one who is led (الْمَأْمُوم), nor the title the excellent one (فَضْل) to the one who is preferred over others (الْمَفْضُول), nor the title the one who supersedes (اَلسَّابِق) to the one who is preceded (اَلْمَسْبُوق). Indeed, the people of every community and religion, philosophers, atheists, and those who deny God all attributes among them, affirm that the leader of the world ought to be the best of them, the most perfect in merit, and the most knowing of all people. And in all the world, no one fits this description except the imams.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 5 the physician of souls', 'god the exalted created the world and ordered its creatures as we have described in some measure earlier according to this pattern of classification disparity and gradation in degrees of excellence with varying levels of strength nobility and rank so that it would be plain that within every species and genus there is a peak a summit and a chief in nobility and merit by the same reasoning all of mankind too must have a peak and summit in nobility and merit to serve as their leader and guide in the world it has thus been established that headship and leadership are necessary features of nature and creation and of natural disposition and intuition as well and that even those who deny revelation and religion cannot deny whether by reason or by plain observation that the world requires leadership headship and authority for these are obligatory and necessary it is therefore mandatory that this leader be the best of all people the most noble the most perfect the most knowing and the most pure in keeping with the arguments we have drawn from creation and nature the foremost must be the imam in all things the chief and the head the title supreme leader الامام cannot be given to the one who is led الماموم nor the title the excellent one فضل to the one who is preferred over others المفضول nor the title the one who supersedes السابق to the one who is preceded المسبوق indeed the people of every community and religion philosophers atheists and those who deny god all attributes among them affirm that the leader of the world ought to be the best of them the most perfect in merit and the most knowing of all people and in all the world no one fits this description except the imams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 0, NULL, 'The philosophers, I say, divided politics, or governance, into three kinds: governance of the individual (سِيَاسَة اَلْخَاصَّة), governance of the family (سِيَاسَةُ الْحَامَّة), and governance of the general public (سِيَاسَةُ الْعَامَّة). The governance of the individual is a person''s rule over himself. The governance of the family is a man''s management of his household and dependents. The governance of the general public is the administration of cities and provinces. To govern himself well, a person must hold himself back from every vice, every flaw of character, every beastly habit, and every blameworthy desire. He must rule his own soul with firm resolve, rebuking it and turning it to repentance when it errs, and, when it does well, praising it and holding it steady in good conduct. To govern his family is to manage his household and dependents: to guard their welfare, to urge them toward the virtues and praiseworthy character, to correct those who err by reprimand and the like, and to reward those who do well with praise and the like.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'the philosophers i say divided politics or governance into three kinds governance of the individual سياسه الخاصه governance of the family سياسه الحامه and governance of the general public سياسه العامه the governance of the individual is a persons rule over himself the governance of the family is a mans management of his household and dependents the governance of the general public is the administration of cities and provinces to govern himself well a person must hold himself back from every vice every flaw of character every beastly habit and every blameworthy desire he must rule his own soul with firm resolve rebuking it and turning it to repentance when it errs and when it does well praising it and holding it steady in good conduct to govern his family is to manage his household and dependents to guard their welfare to urge them toward the virtues and praiseworthy character to correct those who err by reprimand and the like and to reward those who do well with praise and the like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 1, NULL, 'The governance of the general public means that a man governs cities, safeguards the welfare of the people''s livelihoods, and keeps them away from base morals and bad conduct. He protects everyone in their proper stations, corrects those who err by reprimand, rewards those who do well by praise, and watches over the affairs of their religion and their hereafter. This is what the philosophers call governance, and yet nowhere in the world is it found among those who falsely claim the imamate, nor among the rulers, nor among their scholars. This quality belongs only to the imams from the family of Muhammad (عَلَيْهِمُ السَّلَامُ); no one else in the world is able to carry this charge.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'the governance of the general public means that a man governs cities safeguards the welfare of the peoples livelihoods and keeps them away from base morals and bad conduct he protects everyone in their proper stations corrects those who err by reprimand rewards those who do well by praise and watches over the affairs of their religion and their hereafter this is what the philosophers call governance and yet nowhere in the world is it found among those who falsely claim the imamate nor among the rulers nor among their scholars this quality belongs only to the imams from the family of muhammad عليهم السلام no one else in the world is able to carry this charge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 2, NULL, 'The philosophers agree that a man who cannot govern himself has no business governing his family, and that a man who cannot manage his own family well has no claim at all to the governance of the general public. Yet the literalists (أَهْلُ الظَّاهِر), their rulers, and their scholars do not hold this qualification. Those who have taken the place of the imams and borne their titles can govern neither themselves, nor their families, nor the people. They are the very ones we see today sunk in amusement, moral corruption, and depravity. Not one of these rulers has the qualities by which the philosophers define the political leader. It seems plain that whoever devised this classification meant to lead people toward obedience to the imam, for he described the imam by the attributes of the ideal ruler, so that people would seek a ruler who fit exactly this description. Whoever fell short of it would not be accepted, until at last the people found the true imam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'the philosophers agree that a man who cannot govern himself has no business governing his family and that a man who cannot manage his own family well has no claim at all to the governance of the general public yet the literalists اهل الظاهر their rulers and their scholars do not hold this qualification those who have taken the place of the imams and borne their titles can govern neither themselves nor their families nor the people they are the very ones we see today sunk in amusement moral corruption and depravity not one of these rulers has the qualities by which the philosophers define the political leader it seems plain that whoever devised this classification meant to lead people toward obedience to the imam for he described the imam by the attributes of the ideal ruler so that people would seek a ruler who fit exactly this description whoever fell short of it would not be accepted until at last the people found the true imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 3, NULL, 'I say also that human beings are born ignorant, holding no knowledge, and knowledge does not arise in them by nature, nor does speech; so they stand in need of instruction. The proof that knowledge does not come by nature is this: if it did, people would be scholars by nature and would speak by nature, just as donkeys bray and dogs bark with no instruction at all, for it is clear that these animals need no teaching for those sounds. The braying of the donkey and the barking of the dog are one and the same whether in Hind, in Sind, in Rum, or in the land of the Arabs.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'i say also that human beings are born ignorant holding no knowledge and knowledge does not arise in them by nature nor does speech so they stand in need of instruction the proof that knowledge does not come by nature is this if it did people would be scholars by nature and would speak by nature just as donkeys bray and dogs bark with no instruction at all for it is clear that these animals need no teaching for those sounds the braying of the donkey and the barking of the dog are one and the same whether in hind in sind in rum or in the land of the arabs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 4, NULL, 'Further, if speech and knowledge were natural, as I have just said, people would need no instruction for them, and all people would be equal in these matters with no differences among them, just as the braying of donkeys does not differ from one place to another. Since people do need instruction, each learns from another, in a chain that leads back to the one who received no instruction from any human being but received his knowledge by divine inspiration rather than by teaching. This deficiency in human beings and their need for instruction makes a teacher necessary, and this in turn makes necessary a final end-point in the chain of teachers, namely the prophet and the imam (عَلَيْهِمُ السَّلَامُ). This is among the strongest and most convincing proofs for confirming the imamate and the prophethood.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'further if speech and knowledge were natural as i have just said people would need no instruction for them and all people would be equal in these matters with no differences among them just as the braying of donkeys does not differ from one place to another since people do need instruction each learns from another in a chain that leads back to the one who received no instruction from any human being but received his knowledge by divine inspiration rather than by teaching this deficiency in human beings and their need for instruction makes a teacher necessary and this in turn makes necessary a final end point in the chain of teachers namely the prophet and the imam عليهم السلام this is among the strongest and most convincing proofs for confirming the imamate and the prophethood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 5, NULL, 'I say also that God, the Exalted, created human beings deficient and ignorant so that they would be ready to receive knowledge and wisdom. Had He left them to themselves, no obligation would lie upon them, there would be no deeds to perform, no reward, and no punishment, and there would be no wisdom in creating them at all. So when God inspired the prophets and the imams with wisdom and knowledge, they in turn conveyed it to mankind, setting out their guidance and their path to the Truth, and laying upon them obligations, commands, and prohibitions.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'i say also that god the exalted created human beings deficient and ignorant so that they would be ready to receive knowledge and wisdom had he left them to themselves no obligation would lie upon them there would be no deeds to perform no reward and no punishment and there would be no wisdom in creating them at all so when god inspired the prophets and the imams with wisdom and knowledge they in turn conveyed it to mankind setting out their guidance and their path to the truth and laying upon them obligations commands and prohibitions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 6, NULL, 'Moreover, were it not for the imams, humanity would bear no responsibility, and there would be no guarantor and no proof set over them. The imams, therefore, are God''s proofs to His creation at all times, from the very beginning of their moral responsibility and whenever they fall into disagreement. If people fell into sectarian strife, each group citing a verse of the Quran, a hadith, or an analogy, no proof would stand for any of them against the others. If there were no imam in the world to rescue them from disagreement, confusion, and bewilderment and to guide them to the Truth, then God would have no proof against His creatures. Rather, the creatures would have a proof against God, for they would say: "We found no one to guide us from falsehood to the truth." It is through the imam, then, that God''s proof is established over the people, just as God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'moreover were it not for the imams humanity would bear no responsibility and there would be no guarantor and no proof set over them the imams therefore are gods proofs to his creation at all times from the very beginning of their moral responsibility and whenever they fall into disagreement if people fell into sectarian strife each group citing a verse of the quran a hadith or an analogy no proof would stand for any of them against the others if there were no imam in the world to rescue them from disagreement confusion and bewilderment and to guide them to the truth then god would have no proof against his creatures rather the creatures would have a proof against god for they would say we found no one to guide us from falsehood to the truth it is through the imam then that gods proof is established over the people just as god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'governance and the first principle', '6. Governance and the First Principle', 7, NULL, 'Al-An''am: 149فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَلِغَةُ', '', 'فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَلِغَةُ', 'Al-An''am: 149', 6, 149, 'degrees of excellence 6 governance and the first principle', 'al anam 149فلله الحجه البلغه', 'فلله الحجه البلغه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 8, NULL, '"Say, to God belongs the most apparent proof." (Al-Anam: 149)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'say to god belongs the most apparent proof al anam 149', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 9, NULL, 'I say also that the rules and principles ascribed to the sages are, in truth, the teachings of the imams. From them people drew the foundations of every branch of knowledge and wisdom, arithmetic and geometry among them. Each discipline has a purpose and a final point that leads back to the imam. Among the geometric figures — the squares, the triangles, the arcs, and all the rest — the highest is the circle. The circle is the best and most perfect of all figures, and it is the foundation from which every other figure can be derived: the square, the triangle, and the arc alike. When a circle is divided, a square appears and arcs remain at the edges; and if we extend the horizontal and the vertical lines, four triangles come forth. Every other figure is derived from the circle, and every figure is contained within it. The relation of the figures to one another mirrors the world and creation. Among the figures, the circle serves as a proof and a symbol of the imam, who is the circle of religion (دَائِرَة الدِّين). All the الْحُدُود, the ranks of the hierarchy, fall within his command and his prohibition and draw their benefit from him. The circle needs no other figure, while every other figure needs it, just as the imam needs no other rank of the hierarchy in his age and his time, while all the ranks need him, and he encompasses them all.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'i say also that the rules and principles ascribed to the sages are in truth the teachings of the imams from them people drew the foundations of every branch of knowledge and wisdom arithmetic and geometry among them each discipline has a purpose and a final point that leads back to the imam among the geometric figures the squares the triangles the arcs and all the rest the highest is the circle the circle is the best and most perfect of all figures and it is the foundation from which every other figure can be derived the square the triangle and the arc alike when a circle is divided a square appears and arcs remain at the edges and if we extend the horizontal and the vertical lines four triangles come forth every other figure is derived from the circle and every figure is contained within it the relation of the figures to one another mirrors the world and creation among the figures the circle serves as a proof and a symbol of the imam who is the circle of religion دايره الدين all the الحدود the ranks of the hierarchy fall within his command and his prohibition and draw their benefit from him the circle needs no other figure while every other figure needs it just as the imam needs no other rank of the hierarchy in his age and his time while all the ranks need him and he encompasses them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 10, NULL, 'I say also that the origin and source of numbers is the number one. It is the most perfect of numbers, standing independent of two and of everything above it up to a thousand, while the thousand and everything below it depends upon the number one. The imam is uniquely one in his age and his time: all the ranks of the hierarchy need him, while he needs none of them. Some may suppose that the number one points to the Creator of all creatures, but this is mistaken, for the number one is the cause of mathematics and the foundation of numbers, since two is one plus one, and three is one plus one plus one, and so on. Rather, the one truly signifies the imam in his rank and his station, unique and without equal. No other creature in his age and his time shares his place.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'i say also that the origin and source of numbers is the number one it is the most perfect of numbers standing independent of two and of everything above it up to a thousand while the thousand and everything below it depends upon the number one the imam is uniquely one in his age and his time all the ranks of the hierarchy need him while he needs none of them some may suppose that the number one points to the creator of all creatures but this is mistaken for the number one is the cause of mathematics and the foundation of numbers since two is one plus one and three is one plus one plus one and so on rather the one truly signifies the imam in his rank and his station unique and without equal no other creature in his age and his time shares his place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 11, NULL, 'I say also that the dot, which the mathematicians describe as having no parts and as the origin of the line, the surface, and the body, is a symbol of the imam, whose rank no one can attain and who cannot be truly known. No one can rightly describe his attributes; people can only confess their own inability to do so.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'i say also that the dot which the mathematicians describe as having no parts and as the origin of the line the surface and the body is a symbol of the imam whose rank no one can attain and who cannot be truly known no one can rightly describe his attributes people can only confess their own inability to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'governance and the first principle', '6. Governance and the First Principle', 12, NULL, 'Further, I say that among all the days Saturday holds the greatest distinction, and among all the months Ramadan is the finest, and within each day there is one hour in which supplication (الدُّعَاء) is answered. Every genus and every species in the world, whether created or posited, has a peak and a summit in nobility and merit that none other can reach, and this points to the imam, as I have already explained. Were I to set down everything that deserves mention in this chapter, this treatise would run far beyond its proper bounds. What I have already put down should be enough for those who reflect with care, allowing them to draw conclusions by analogy from the principles and the branches I have outlined. I shall, however, mention a few further points in brief (نُكَتًا عَلَى الْاِخْتِصَارِ), drawing on the obligatory religious duties (اَلْفَرَائِض) and their structure.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 6 governance and the first principle', 'further i say that among all the days saturday holds the greatest distinction and among all the months ramadan is the finest and within each day there is one hour in which supplication الدعاء is answered every genus and every species in the world whether created or posited has a peak and a summit in nobility and merit that none other can reach and this points to the imam as i have already explained were i to set down everything that deserves mention in this chapter this treatise would run far beyond its proper bounds what i have already put down should be enough for those who reflect with care allowing them to draw conclusions by analogy from the principles and the branches i have outlined i shall however mention a few further points in brief نكتا علي الاختصار drawing on the obligatory religious duties الفرايض and their structure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 0, NULL, 'The ritual prayer is a powerful proof of the imamate — in how it is ordered, in the standing it prescribes, in its turning toward the qibla, and in the place of the prayer leader (أَمَام) at the head of the rows. The Prophet ﷺ first commanded the Muslims to face the qibla. The word qibla comes from qabala, which means "face to face": whoever faces the qibla turns his face straight toward it, and that direction is the imam. It is said that to be before (أَمَام) a thing is to stand in front of it and so to precede it, which is the opposite of standing behind or after it. The word imam belongs to this same root, and the leader of the prayer is called imam precisely because he goes before the worshippers. To direct people toward the qibla is therefore to direct them toward the imam, and the Prophet commanded people to follow him, to obey him in every act of worship, and to accept his direction. When a person faces forward in prayer, he faces the qibla, and this mirrors, across the whole of his worship and obedience, his orientation toward the imam. When a person prays with his imam, the merit of that prayer comes precisely from its being performed with the imam — facing him, following him, and led by him in both intention and action — for the Prophet said that a prayer prayed in congregation equals twenty-seven prayers prayed alone. This shows that the whole of obedience lies in being led by the supreme imam (الْإِمَامُ الْأَعْظَم), guided by him, following him, and directed by him, so that obedience itself becomes excellent. The Prophet also commanded the worshippers to stand in even rows, so that there would be no unevenness among them as they stood. This signals that the hearts of those whom the imam guides and leads must not differ from one another, and neither must their actions nor their words.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'the ritual prayer is a powerful proof of the imamate in how it is ordered in the standing it prescribes in its turning toward the qibla and in the place of the prayer leader امام at the head of the rows the prophet ﷺ first commanded the muslims to face the qibla the word qibla comes from qabala which means face to face whoever faces the qibla turns his face straight toward it and that direction is the imam it is said that to be before امام a thing is to stand in front of it and so to precede it which is the opposite of standing behind or after it the word imam belongs to this same root and the leader of the prayer is called imam precisely because he goes before the worshippers to direct people toward the qibla is therefore to direct them toward the imam and the prophet commanded people to follow him to obey him in every act of worship and to accept his direction when a person faces forward in prayer he faces the qibla and this mirrors across the whole of his worship and obedience his orientation toward the imam when a person prays with his imam the merit of that prayer comes precisely from its being performed with the imam facing him following him and led by him in both intention and action for the prophet said that a prayer prayed in congregation equals twenty seven prayers prayed alone this shows that the whole of obedience lies in being led by the supreme imam الامام الاعظم guided by him following him and directed by him so that obedience itself becomes excellent the prophet also commanded the worshippers to stand in even rows so that there would be no unevenness among them as they stood this signals that the hearts of those whom the imam guides and leads must not differ from one another and neither must their actions nor their words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 1, NULL, 'The Prophet commanded the worshippers to follow the prayer leader even when the recitation, the rising, or the prostration is drawn out, and never to move against him in gesture or in intention. Indeed, if a worshipper matches the imam''s physical action but not his intention, that prayer is not accepted; and if one who is being led falls short, the imam makes up for his shortcoming. All of this makes plain that if obedience to a partial (اَلْجُزْئِيّ) imam — one who is not an imam in the absolute sense — is made obligatory, and the reward of that worship is multiplied, then what must be said of obedience to the supreme (الْأَعْظَم) imam, who leads in the whole of the revealed law (شَرِيْعَة) and its inner interpretation (التَّأْوِيل)? And if it is forbidden to move against the prayer leader in even one act of worship, how can it be allowed to move against the supreme imam in the commands and prohibitions that govern a believer''s entire life? The believer stays under the care of the dawa in his prayer for as long as he remains within the allegiance (وَلَايَة) of the imam. If he moves against the imam in action, in intention, or in decision, he will have voided his prayers and stepped outside the way of the worshipper — just as when a worshipper sets himself to oppose the prayer leader, his bowing, prostration, standing, and sitting are made worthless, his act is empty, and he must begin the prayer again. How much more vital, then, is obedience to the supreme imam, which God has made absolutely obligatory. The Prophet said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'the prophet commanded the worshippers to follow the prayer leader even when the recitation the rising or the prostration is drawn out and never to move against him in gesture or in intention indeed if a worshipper matches the imams physical action but not his intention that prayer is not accepted and if one who is being led falls short the imam makes up for his shortcoming all of this makes plain that if obedience to a partial الجزيي imam one who is not an imam in the absolute sense is made obligatory and the reward of that worship is multiplied then what must be said of obedience to the supreme الاعظم imam who leads in the whole of the revealed law شريعه and its inner interpretation التاويل and if it is forbidden to move against the prayer leader in even one act of worship how can it be allowed to move against the supreme imam in the commands and prohibitions that govern a believers entire life the believer stays under the care of the dawa in his prayer for as long as he remains within the allegiance ولايه of the imam if he moves against the imam in action in intention or in decision he will have voided his prayers and stepped outside the way of the worshipper just as when a worshipper sets himself to oppose the prayer leader his bowing prostration standing and sitting are made worthless his act is empty and he must begin the prayer again how much more vital then is obedience to the supreme imam which god has made absolutely obligatory the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 2, NULL, '"The imam is the guarantor for those who follow him."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'the imam is the guarantor for those who follow him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 3, NULL, 'This surely does not mean the prayer leader alone, for such a leader himself needs someone who can vouch for him. It means, in truth, the supreme imam (ع), who guarantees the purification of those he leads — freeing them from doubt, suspicion, confusion, and forgetfulness — and who guarantees their salvation as long as they are guided by him and follow him. The Prophet pointed to the imam''s place as going before everyone, and he commanded them not to vie with the imam in reciting the Quran, saying:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'this surely does not mean the prayer leader alone for such a leader himself needs someone who can vouch for him it means in truth the supreme imam ع who guarantees the purification of those he leads freeing them from doubt suspicion confusion and forgetfulness and who guarantees their salvation as long as they are guided by him and follow him the prophet pointed to the imams place as going before everyone and he commanded them not to vie with the imam in reciting the quran saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 4, NULL, '"When he prostrates you should prostrate, when he bows you bow, when he recites you listen, and when he says the salutations (taslim) then you should say it too."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'when he prostrates you should prostrate when he bows you bow when he recites you listen and when he says the salutations taslim then you should say it too', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 5, NULL, 'All of this points to obedience to the imams and to their exaltation in every matter, to the permanence of their authority in their own age, to the duty of obeying them, and to the handing over (اَلتَّسْلِيم) of the command (الْأَمْر), at the close of each imam''s term, to whomever he appoints. Even if there were no proof of the imam and of obedience to him in the sharia other than what is found in the prayer, that alone would be enough. For the Prophet explained that the imam clears the worshippers of their shortcomings in prayer — meaning that the imam covers their lapses and seeks forgiveness on their behalf — just as God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'all of this points to obedience to the imams and to their exaltation in every matter to the permanence of their authority in their own age to the duty of obeying them and to the handing over التسليم of the command الامر at the close of each imams term to whomever he appoints even if there were no proof of the imam and of obedience to him in the sharia other than what is found in the prayer that alone would be enough for the prophet explained that the imam clears the worshippers of their shortcomings in prayer meaning that the imam covers their lapses and seeks forgiveness on their behalf just as god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 6, NULL, '"If only when they wronged themselves, they had come to you seeking forgiveness of God and the Prophet, they would have surely found God Most Forgiving and Merciful."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'if only when they wronged themselves they had come to you seeking forgiveness of god and the prophet they would have surely found god most forgiving and merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 7, NULL, 'If the imam were to withhold forgiveness and the acceptance of repentance from this community (الْأُمَّة), they would surely perish, for they stand in the greatest need of forgiveness. What endures, in every age and every time, is this: whoever comes to the imam, the imam seeks forgiveness for him, and God forgives him, just as He forgave those earlier people.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'if the imam were to withhold forgiveness and the acceptance of repentance from this community الامه they would surely perish for they stand in the greatest need of forgiveness what endures in every age and every time is this whoever comes to the imam the imam seeks forgiveness for him and god forgives him just as he forgave those earlier people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 8, NULL, 'I say also that the Friday prayer is not valid without the sermon (اَلْخُطْبَة) delivered from the pulpits (الْمَنَابِر). People pray behind the imam so that they may understand that obedience to the imam is lifted from no creature anywhere. Furthermore, the pilgrimage in its entirety is a proof for the imamate. The pilgrimage begins with an intention, and an intention must be directed toward something known, so that when it is made with full knowledge (مَعْرِفَة) it becomes a clear and deliberate act needing no further explanation — which is itself a sign of the intention directed toward the imam. The Kaba, in some of the inner interpretations, is a proof for the imam. It was set in a desert empty of settlement, reachable only with great hardship, in a place without crops or trees and stripped of worldly gain, so arranged that worshippers may understand that what it stands for (مَمْثُول) can likewise be reached only through great effort, hardship, and injury from enemies. They should understand too that turning toward the imam and seeking him must not be for worldly ends — out of greed, pleasure, or worldly standing — but that visiting the imam must arise from pure faith alone. If a person meets hardship, weariness, attacks from enemies, or exhaustion, his heart must not waver; he must bear it with patience. He will then see and know all of this in its symbol (مَثَل), which is the pilgrimage. Its circling of the Kaba, the touching and receiving of it (اَلْاِسْتِلَام), the pointing toward it, the running, the throwing of stones, the wearing of the white garments (الْإِحْرَام), and the giving up of perfume and marital relations — all of this points to the affirmation of the imamate and to obedience to him under every condition, to the seeking of guidance and the guarding of one''s soul, and to the casting off of blameworthy doctrines and corrupt beliefs.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'i say also that the friday prayer is not valid without the sermon الخطبه delivered from the pulpits المنابر people pray behind the imam so that they may understand that obedience to the imam is lifted from no creature anywhere furthermore the pilgrimage in its entirety is a proof for the imamate the pilgrimage begins with an intention and an intention must be directed toward something known so that when it is made with full knowledge معرفه it becomes a clear and deliberate act needing no further explanation which is itself a sign of the intention directed toward the imam the kaba in some of the inner interpretations is a proof for the imam it was set in a desert empty of settlement reachable only with great hardship in a place without crops or trees and stripped of worldly gain so arranged that worshippers may understand that what it stands for ممثول can likewise be reached only through great effort hardship and injury from enemies they should understand too that turning toward the imam and seeking him must not be for worldly ends out of greed pleasure or worldly standing but that visiting the imam must arise from pure faith alone if a person meets hardship weariness attacks from enemies or exhaustion his heart must not waver he must bear it with patience he will then see and know all of this in its symbol مثل which is the pilgrimage its circling of the kaba the touching and receiving of it الاستلام the pointing toward it the running the throwing of stones the wearing of the white garments الاحرام and the giving up of perfume and marital relations all of this points to the affirmation of the imamate and to obedience to him under every condition to the seeking of guidance and the guarding of ones soul and to the casting off of blameworthy doctrines and corrupt beliefs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 9, NULL, 'I say also that among the strongest proofs for the necessity of the imamate is the obligation of alms (اَلزَّكَاة) — in its religious duties, its safekeeping, and its distribution. God, the Exalted, commanded the Prophet to take almsgiving (صَدَقَة) from the believers when He said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'i say also that among the strongest proofs for the necessity of the imamate is the obligation of alms الزكاه in its religious duties its safekeeping and its distribution god the exalted commanded the prophet to take almsgiving صدقه from the believers when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 10, NULL, '"Take alms (sadaqa) from their wealth, purify them and cleanse them through it and pray for them. Your prayers will indeed bring them tranquillity."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'take alms sadaqa from their wealth purify them and cleanse them through it and pray for them your prayers will indeed bring them tranquillity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 11, NULL, 'The Prophet then set out the duties of zakat, its amounts, and how it should be collected. He himself collected it until the community understood both how to give it and how to receive it. Whoever afterward sat in the place of the imams also collected zakat, claiming that the collection of alms was his and citing this verse and the practice of God''s Messenger to justify it. For that reason he waged war against the Banu Hanifa and killed them. Those who sat in the place of the imams after him likewise collected the alms, until the matter at last reached their own leaders, who took offense at it, kept the alms money for themselves, and stopped it from being collected on behalf of the imam. Is it any wonder, then, to see the state of this community? They affirm that the verse in question abrogates (نَاسِخَة) in both ruling and recitation, that it is not itself abrogated (مَنْسُوخَة), and that the Prophetic sunna still requires the collection of alms. How, then, did they allow themselves to change the ruling of the verse and of God''s command, and to change the sunna of the Prophet and the sunna of those whose imamate they claim? The only motive for that change was their denial of the imams'' rightful standing and their rejection of the imamate within the Prophet''s family (أَهْلُ الْبَيْت). God, the Exalted, had made plain, through His rulings on alms (اَلزَّكَاة) and the manner of collecting them, the standing of the imamate and the imams: He forbade صَدَقَة to the Prophet so that no one could accuse him of collecting it for his own gain, and He likewise forbade it to the Prophet''s family so that they would know that the imam among them is the one who holds the Prophet''s place in collecting alms, and that they, the imams, are fully trustworthy in this.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'the prophet then set out the duties of zakat its amounts and how it should be collected he himself collected it until the community understood both how to give it and how to receive it whoever afterward sat in the place of the imams also collected zakat claiming that the collection of alms was his and citing this verse and the practice of gods messenger to justify it for that reason he waged war against the banu hanifa and killed them those who sat in the place of the imams after him likewise collected the alms until the matter at last reached their own leaders who took offense at it kept the alms money for themselves and stopped it from being collected on behalf of the imam is it any wonder then to see the state of this community they affirm that the verse in question abrogates ناسخه in both ruling and recitation that it is not itself abrogated منسوخه and that the prophetic sunna still requires the collection of alms how then did they allow themselves to change the ruling of the verse and of gods command and to change the sunna of the prophet and the sunna of those whose imamate they claim the only motive for that change was their denial of the imams rightful standing and their rejection of the imamate within the prophets family اهل البيت god the exalted had made plain through his rulings on alms الزكاه and the manner of collecting them the standing of the imamate and the imams he forbade صدقه to the prophet so that no one could accuse him of collecting it for his own gain and he likewise forbade it to the prophets family so that they would know that the imam among them is the one who holds the prophets place in collecting alms and that they the imams are fully trustworthy in this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 12, NULL, 'Had the people been entrusted to carry out the duty of almsgiving and its distribution themselves, God would have commanded them to do so, just as He commanded them regarding prayer, fasting, and the other obligatory duties. But He did not order them to distribute the صَدَقَة; He commanded the Prophet to do so. If it had been allowed for the people to distribute it themselves, it would have been allowed in the Prophet''s own time, when they were far steadier in their religion, more certain in their faith, and of greater integrity. How is it, then, that later generations have made themselves trustees of almsgiving? And why is it allowed for them that prayer — which is more meritorious than almsgiving — be performed behind their imams, and the other duties likewise, yet it is not acceptable to give their imams the alms? Why, further, are they held trustworthy in matters of bloodshed and sexual offenses and in every other matter of property, yet not reliable or trustworthy when it comes to alms? If the people are truthful in what they say about their imams being untrustworthy with alms, then those imams are not imams at all but embezzlers. And if they are embezzlers, it is not allowed to pray behind them, nor to wage jihad or make the pilgrimage under them, nor to accept their rulings on sexual offenses, bloodshed, or property. But if these people are lying in what they say and claim, then the scholars among them who issue religious opinions (فَتْوَى) to that effect are liars as well, since they are the ones who bear witness to the leadership of those imams, and the testimony of liars is not acceptable. God, the Exalted, also commanded the Prophet to purify the believers and pray for them when He said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'had the people been entrusted to carry out the duty of almsgiving and its distribution themselves god would have commanded them to do so just as he commanded them regarding prayer fasting and the other obligatory duties but he did not order them to distribute the صدقه he commanded the prophet to do so if it had been allowed for the people to distribute it themselves it would have been allowed in the prophets own time when they were far steadier in their religion more certain in their faith and of greater integrity how is it then that later generations have made themselves trustees of almsgiving and why is it allowed for them that prayer which is more meritorious than almsgiving be performed behind their imams and the other duties likewise yet it is not acceptable to give their imams the alms why further are they held trustworthy in matters of bloodshed and sexual offenses and in every other matter of property yet not reliable or trustworthy when it comes to alms if the people are truthful in what they say about their imams being untrustworthy with alms then those imams are not imams at all but embezzlers and if they are embezzlers it is not allowed to pray behind them nor to wage jihad or make the pilgrimage under them nor to accept their rulings on sexual offenses bloodshed or property but if these people are lying in what they say and claim then the scholars among them who issue religious opinions فتوي to that effect are liars as well since they are the ones who bear witness to the leadership of those imams and the testimony of liars is not acceptable god the exalted also commanded the prophet to purify the believers and pray for them when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 13, NULL, '"...purify them and pray for them; your prayers will indeed bring them tranquillity."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'purify them and pray for them your prayers will indeed bring them tranquillity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 14, NULL, 'He thus made the imam''s purification of them and his prayer over them a source of their tranquillity, and that prayer was the recompense for the alms He took from them. If God had granted this recompense to those present in the time of the Prophet and withheld it from those who came after — even though the later generations need it more than those who lived in the Prophet''s time — that would be an injustice against those who came after that age. God is far exalted above injustice toward His worshippers, and He, may His name be exalted, does not impose an obligation and assign a recompense (عوضاً) for it, in this world or the next, without making that recompense universal. Rather, the purification, the prayer, and the tranquillity belong forever to whoever comes to the imam and gives alms (اَلزَّكَاة) from his property, whether openly or in secret. The imam then purifies him and prays for him. Were the imam needed for this alone, that would be enough. His distribution of the alms to those entitled to it rests on his knowledge of who may rightfully receive it and who may not, and on his awareness of when a class of eligible recipients has no one in it and how the share meant for them should then be handled. The imam is thus the one who safeguards the treasury of the Muslims, distributing it according to the needs of religion and the demands of the time.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'he thus made the imams purification of them and his prayer over them a source of their tranquillity and that prayer was the recompense for the alms he took from them if god had granted this recompense to those present in the time of the prophet and withheld it from those who came after even though the later generations need it more than those who lived in the prophets time that would be an injustice against those who came after that age god is far exalted above injustice toward his worshippers and he may his name be exalted does not impose an obligation and assign a recompense عوضا for it in this world or the next without making that recompense universal rather the purification the prayer and the tranquillity belong forever to whoever comes to the imam and gives alms الزكاه from his property whether openly or in secret the imam then purifies him and prays for him were the imam needed for this alone that would be enough his distribution of the alms to those entitled to it rests on his knowledge of who may rightfully receive it and who may not and on his awareness of when a class of eligible recipients has no one in it and how the share meant for them should then be handled the imam is thus the one who safeguards the treasury of the muslims distributing it according to the needs of religion and the demands of the time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 15, NULL, 'I say also that jihad is one of the pillars of religion, and that it is allowed to wage war only under the banner of an imam. No command to wage war can stand except from the imam, for the imam must first protect the treasury (بَيْتُ مَال) of the Muslims, which is under his guarantee, and protect the border towns and the Muslim army, and ransom Muslim prisoners of war from the hands of the unbelievers. An army, moreover, may be sent out only under a commander appointed by the imam, or by someone the imam has himself appointed. The imam knows better the right times for peace, for agreements, and for treaties, and it is he who concludes them. When prisoners of war are taken, he knows whom to pardon, whom to ransom, and whom to put to death. He is better acquainted with the ways of gathering the land tax (اَلْخَرَاج) and the revenues, so that they serve as a means of benefit and support for the Muslims. The imam also identifies the rebel, and it is by standing with him that a party (اَلْفِئَة) becomes the party of truth. The rebel is the one who leaves the obedience of the imam, and it then falls to the imam to decide whether to wage war, to make peace, or to conclude a truce. Al-Shafii said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'i say also that jihad is one of the pillars of religion and that it is allowed to wage war only under the banner of an imam no command to wage war can stand except from the imam for the imam must first protect the treasury بيت مال of the muslims which is under his guarantee and protect the border towns and the muslim army and ransom muslim prisoners of war from the hands of the unbelievers an army moreover may be sent out only under a commander appointed by the imam or by someone the imam has himself appointed the imam knows better the right times for peace for agreements and for treaties and it is he who concludes them when prisoners of war are taken he knows whom to pardon whom to ransom and whom to put to death he is better acquainted with the ways of gathering the land tax الخراج and the revenues so that they serve as a means of benefit and support for the muslims the imam also identifies the rebel and it is by standing with him that a party الفيه becomes the party of truth the rebel is the one who leaves the obedience of the imam and it then falls to the imam to decide whether to wage war to make peace or to conclude a truce al shafii said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 16, NULL, '"If it were not for the Commander of the Faithful, Ali b. Abi Talib (ع), we would not have known how to wage war against rebels, nor would we have been able to distinguish the rebel from the rightful believers."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'if it were not for the commander of the faithful ali b abi talib ع we would not have known how to wage war against rebels nor would we have been able to distinguish the rebel from the rightful believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 17, NULL, 'There is also the fifth (اَلْخُمْس), which God assigned to the Prophet''s family and to the imams in place of the alms (صَدَقَة) that He had forbidden them. All the benefits of alms and zakat, together with all the duties tied to them, are bound to the imam. Beyond this there are the id feasts and the month of Ramadan, in which the imam keeps order and accepts the testimony of witnesses — whether opponents hold that the fasting and the breaking of the fast are set by the sighting of the moon or by the one the imam appoints. And the two feast prayers and the Friday prayer are not valid in congregation without a sermon (اَلْخُطْبَة) from the imam and his presence, or from someone he has appointed, even if the congregation is reduced from four to two on account of the imam''s sermon.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'there is also the fifth الخمس which god assigned to the prophets family and to the imams in place of the alms صدقه that he had forbidden them all the benefits of alms and zakat together with all the duties tied to them are bound to the imam beyond this there are the id feasts and the month of ramadan in which the imam keeps order and accepts the testimony of witnesses whether opponents hold that the fasting and the breaking of the fast are set by the sighting of the moon or by the one the imam appoints and the two feast prayers and the friday prayer are not valid in congregation without a sermon الخطبه from the imam and his presence or from someone he has appointed even if the congregation is reduced from four to two on account of the imams sermon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 18, NULL, 'As for the carrying out of legal punishments (الْحُدُود), only the imam, or someone the imam appoints, may carry them out. The cutting off of hands, flogging, stoning, imprisonment, the indemnity for injuries (أَرْشُ اَلْجِرَاحَات), and judgment concerning them can all be carried out only on the imam''s orders. Were these rules the only proof for the imamate in the Messenger''s family, that alone would be enough. For the opponents themselves agree that whoever holds no authority (وَلَايَة) may not rule on legal punishments. If a man witnesses another killing someone unjustly, it is not for him to kill that person. If he sees someone stealing, it is not for him to cut off his hand, stone him, or take any other such measure. This principle reaches so far that most people agree that not even a slave''s owner may carry out legal punishments or chastise him; only the imam may do so.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'as for the carrying out of legal punishments الحدود only the imam or someone the imam appoints may carry them out the cutting off of hands flogging stoning imprisonment the indemnity for injuries ارش الجراحات and judgment concerning them can all be carried out only on the imams orders were these rules the only proof for the imamate in the messengers family that alone would be enough for the opponents themselves agree that whoever holds no authority ولايه may not rule on legal punishments if a man witnesses another killing someone unjustly it is not for him to kill that person if he sees someone stealing it is not for him to cut off his hand stone him or take any other such measure this principle reaches so far that most people agree that not even a slaves owner may carry out legal punishments or chastise him only the imam may do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 19, NULL, 'Legal punishments cannot simply be abolished, for were they abolished, the people would perish and the lands would fall to ruin. Yet if everyone were allowed to carry them out, every person of violent or harmful intent would claim to be administering a lawful punishment, saying that the one he struck or killed had committed some act that deserved it. But how can a man who himself incurs twenty legal punishments every day rule on legal punishments and be allowed to carry them out? Were that allowed for such a person, it would be allowed for every oppressor and rebel, and the result would be the ruin of the people. Rather, when a rebellious party carries out legal punishments and destroys lives, and the imam has power over them, he fines them for whatever harm they did to the righteous party, and so keeps the wrongdoers from destroying the people and damaging their property.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'legal punishments cannot simply be abolished for were they abolished the people would perish and the lands would fall to ruin yet if everyone were allowed to carry them out every person of violent or harmful intent would claim to be administering a lawful punishment saying that the one he struck or killed had committed some act that deserved it but how can a man who himself incurs twenty legal punishments every day rule on legal punishments and be allowed to carry them out were that allowed for such a person it would be allowed for every oppressor and rebel and the result would be the ruin of the people rather when a rebellious party carries out legal punishments and destroys lives and the imam has power over them he fines them for whatever harm they did to the righteous party and so keeps the wrongdoers from destroying the people and damaging their property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 20, NULL, 'Such people then claim that everything they did was in keeping with a legal rule laid upon them. But God, the Exalted, has spoken to this directly:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'such people then claim that everything they did was in keeping with a legal rule laid upon them but god the exalted has spoken to this directly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 21, NULL, 'Al-Baqarah: 44أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ', '', 'أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ', 'Al-Baqarah: 44', 2, 44, 'degrees of excellence 7 the imam in the pillars of faith', 'al baqarah 44اتامرون الناس بالبر وتنسون انفسكم', 'اتامرون الناس بالبر وتنسون انفسكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 22, NULL, '"Do you command people to do good and forget it yourselves?"', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'do you command people to do good and forget it yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 23, NULL, 'God, the Exalted, made plain that whoever himself needs to be commanded to do good and restrained from evil is in no position to command others to good or forbid them evil. And God explained in another verse that the enjoining of good and the forbidding of evil (الْأَمْر bil-maruf wa nahy an al-munkar) is a duty of the imams, when He said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'god the exalted made plain that whoever himself needs to be commanded to do good and restrained from evil is in no position to command others to good or forbid them evil and god explained in another verse that the enjoining of good and the forbidding of evil الامر bil maruf wa nahy an al munkar is a duty of the imams when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 24, NULL, 'Ali ''Imran: 110كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ', '', 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ', 'Ali ''Imran: 110', 3, 110, 'degrees of excellence 7 the imam in the pillars of faith', 'ali imran 110كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر', 'كنتم خير امه اخرجت للناس تامرون بالمعروف وتنهون عن المنكر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 25, NULL, '"You are the best community (umma) that has been raised for the people. You enjoin good conduct and forbid evil."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'you are the best community umma that has been raised for the people you enjoin good conduct and forbid evil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 26, NULL, 'They are the equitable leaders (اَلْأَئِمَّةُ الْوَسَطْ) who stand as witnesses over the people.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'they are the equitable leaders الايمه الوسط who stand as witnesses over the people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 27, NULL, 'How can a man command good if he does not practice it himself? How can he forbid evil if he loves evil and commits it a hundred times a day? How is it allowed for their imams — when they commit daily the very acts that call for legal punishment, driven by lust and desire, and when they draw close to themselves those who love such acts and share in them — to forbid those same acts, all the while regarding those who do them as elegant, victorious, agreeable, and refined? Whoever will not join them in drinking and debauchery they neither draw close nor employ, for such a man is disagreeable to them. Is that not itself a lesson to those they lead, and an incitement toward corruption and debauchery?', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'how can a man command good if he does not practice it himself how can he forbid evil if he loves evil and commits it a hundred times a day how is it allowed for their imams when they commit daily the very acts that call for legal punishment driven by lust and desire and when they draw close to themselves those who love such acts and share in them to forbid those same acts all the while regarding those who do them as elegant victorious agreeable and refined whoever will not join them in drinking and debauchery they neither draw close nor employ for such a man is disagreeable to them is that not itself a lesson to those they lead and an incitement toward corruption and debauchery', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 28, NULL, 'We also say: it is agreed by all that legal judgment among the people in matters of bloodshed, sexual offenses, and property may be exercised only by one who knows the relevant cases and the legal opinions concerning them, who understands the legal norms, the Quranic revelation and its meaning — including the abrogating and the abrogated verses (النَّاسِخ وَالْمَنْسُوخ) — and the analogical deduction (اَلْقِيَاس) in their view, and who meets its conditions, such that he can be trusted in rulings on bloodshed, property, and sexual offenses. Does any of the usurpers who claim the imamate actually meet these conditions? On the contrary, every one of them leans on those so-called jurists who are said to have knowledge yet lack its substance. The usurpers shower these men with the petty goods of this world, appoint them governors of provinces, and let them preside over public sessions. When an incident arises, they turn to the jurists for answers, and what do they produce? One says, "According to Abu Hanifa, this man should be executed," while another says, "According to al-Shafii, he should not be executed." A third says, "According to Malik, this woman should be divorced," and a fourth says, "According to Ahmad b. Hanbal, the woman is not forbidden to him." The usurpers handed the leadership of religious affairs to these jurists so that the jurists would judge according to their own desires and opinions, and in return the jurists would leave worldly authority to the usurpers and bear false witness on their behalf. In doing so, the jurists disgraced themselves through their compliance. I do not know which of the two is more astonishing: the one who shamelessly claims the imamate while having no knowledge whatever of religion or its legal norms, and therefore needs such scholars, or the one who clings to his leadership and rewards their ignorance and their shame. If the jurists were true scholars, and authority truly rested on their pronouncements, then they would be the imams — not the man who falsely claims the title while being nothing more than an idol set up with no real authority, able neither to benefit nor to harm. Or should the greater wonder be kept for him who clings to such a leader and rewards his ignorance? In the end, their imam is the mirror image of the one he leads, and the one led is the mirror image of his imam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'we also say it is agreed by all that legal judgment among the people in matters of bloodshed sexual offenses and property may be exercised only by one who knows the relevant cases and the legal opinions concerning them who understands the legal norms the quranic revelation and its meaning including the abrogating and the abrogated verses الناسخ والمنسوخ and the analogical deduction القياس in their view and who meets its conditions such that he can be trusted in rulings on bloodshed property and sexual offenses does any of the usurpers who claim the imamate actually meet these conditions on the contrary every one of them leans on those so called jurists who are said to have knowledge yet lack its substance the usurpers shower these men with the petty goods of this world appoint them governors of provinces and let them preside over public sessions when an incident arises they turn to the jurists for answers and what do they produce one says according to abu hanifa this man should be executed while another says according to al shafii he should not be executed a third says according to malik this woman should be divorced and a fourth says according to ahmad b hanbal the woman is not forbidden to him the usurpers handed the leadership of religious affairs to these jurists so that the jurists would judge according to their own desires and opinions and in return the jurists would leave worldly authority to the usurpers and bear false witness on their behalf in doing so the jurists disgraced themselves through their compliance i do not know which of the two is more astonishing the one who shamelessly claims the imamate while having no knowledge whatever of religion or its legal norms and therefore needs such scholars or the one who clings to his leadership and rewards their ignorance and their shame if the jurists were true scholars and authority truly rested on their pronouncements then they would be the imams not the man who falsely claims the title while being nothing more than an idol set up with no real authority able neither to benefit nor to harm or should the greater wonder be kept for him who clings to such a leader and rewards his ignorance in the end their imam is the mirror image of the one he leads and the one led is the mirror image of his imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 29, NULL, 'If their imams have no right to exercise legal judgment and authority (وَلَايَة) — because they lack knowledge, fail to meet its conditions, and possess neither modesty nor integrity — then it must be noted that most adherents of the doctrine of choice (اَلْاِخْتِيَار) themselves hold that an imam who is unjust and immoral forfeits the imamate, and, in the view of some, ought to be removed from it. Likewise, a judge among them who betrays the people''s trust should be removed from office, and a legal guardian should likewise lose his guardianship. Some go further, holding that the community is obliged to remove an imam who is unjust and immoral. Al-Shafii said: "A sinner has no legal guardianship; if he had a daughter, he would have no right to give her in marriage. That right would pass to the judge, not to him." And moreover, according to all these jurist-imams, the testimony of a sinner is inadmissible. Thus, by agreement (اَلْاِتِّفَاق) and consensus (اَلْإِجْمَاع), their imams are not among those qualified to exercise legal reasoning (اَلْاِجْتِهَاد) in religion, nor to give their daughters in marriage, nor to have their testimony accepted, nor to carry out legal punishments.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'if their imams have no right to exercise legal judgment and authority ولايه because they lack knowledge fail to meet its conditions and possess neither modesty nor integrity then it must be noted that most adherents of the doctrine of choice الاختيار themselves hold that an imam who is unjust and immoral forfeits the imamate and in the view of some ought to be removed from it likewise a judge among them who betrays the peoples trust should be removed from office and a legal guardian should likewise lose his guardianship some go further holding that the community is obliged to remove an imam who is unjust and immoral al shafii said a sinner has no legal guardianship if he had a daughter he would have no right to give her in marriage that right would pass to the judge not to him and moreover according to all these jurist imams the testimony of a sinner is inadmissible thus by agreement الاتفاق and consensus الاجماع their imams are not among those qualified to exercise legal reasoning الاجتهاد in religion nor to give their daughters in marriage nor to have their testimony accepted nor to carry out legal punishments', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 30, NULL, 'These men have been notorious and infamous offenders, and those who came after them walked the same path. How could anyone with such qualities be the Commander of the Faithful, the vicegerent (خَلِيفَة) of the Lord of the worlds, and an imam whose obedience is obligatory? If they hold no right of guardianship, legal judgment, or testimony, how can those they appoint exercise guardianship, and how can testimony be accepted from those they endorse? How can their recommendation of a man as fit for judgment, witnessing, and guardianship carry any weight at all? Is there anything in this world more remarkable than these people — than the contradictions in their rulings, the principles of their legal school (مَذْهَب), and their doctrine? And is there anyone more infamous than their imam and the people he leads?', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'these men have been notorious and infamous offenders and those who came after them walked the same path how could anyone with such qualities be the commander of the faithful the vicegerent خليفه of the lord of the worlds and an imam whose obedience is obligatory if they hold no right of guardianship legal judgment or testimony how can those they appoint exercise guardianship and how can testimony be accepted from those they endorse how can their recommendation of a man as fit for judgment witnessing and guardianship carry any weight at all is there anything in this world more remarkable than these people than the contradictions in their rulings the principles of their legal school مذهب and their doctrine and is there anyone more infamous than their imam and the people he leads', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 31, NULL, 'Were we to count every contradiction and disgrace lodged in their principles, this treatise would have to be stretched far beyond its intended scope. What we have already said is a sufficient refutation of their claim to the imamate and a clear proof that everything they have done and go on doing amounts to falsehood, injustice, and transgression. That alone is shame and disgrace enough for them. If their imamate is false, as we have shown, and if it is true that the imamate is one of the foundations of religion (أُصُولُ الدِّين), an inevitable necessity to which all revealed laws and norms are bound, then the imamate truly belongs to the pure imams from among the progeny of Taha and Yasin — protected from corruption and oppression, from lying and transgression, and cleansed of all filth and blame. What we have set out through rational deduction and through the religious law is sufficient.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'were we to count every contradiction and disgrace lodged in their principles this treatise would have to be stretched far beyond its intended scope what we have already said is a sufficient refutation of their claim to the imamate and a clear proof that everything they have done and go on doing amounts to falsehood injustice and transgression that alone is shame and disgrace enough for them if their imamate is false as we have shown and if it is true that the imamate is one of the foundations of religion اصول الدين an inevitable necessity to which all revealed laws and norms are bound then the imamate truly belongs to the pure imams from among the progeny of taha and yasin protected from corruption and oppression from lying and transgression and cleansed of all filth and blame what we have set out through rational deduction and through the religious law is sufficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'the imam in the pillars of faith', '7. The Imam in the Pillars of Faith', 32, NULL, 'We shall now turn to establishing the necessity of the imamate on the basis of the past prophetic cycles, and to showing that there has never been an age or a period without a true imam whose obedience is obligatory.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 7 the imam in the pillars of faith', 'we shall now turn to establishing the necessity of the imamate on the basis of the past prophetic cycles and to showing that there has never been an age or a period without a true imam whose obedience is obligatory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 0, NULL, 'Section Seven', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'section seven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 1, NULL, 'I say this: if it were acceptable for there to be creatures on earth without an imam or caliph, it would have been acceptable in the days of Adam (ع), when only the angels existed. Yet even then God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'i say this if it were acceptable for there to be creatures on earth without an imam or caliph it would have been acceptable in the days of adam ع when only the angels existed yet even then god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 2, NULL, 'Al-Baqarah: 30إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', '', 'إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', 'Al-Baqarah: 30', 2, 30, 'degrees of excellence 8 from adam to ali', 'al baqarah 30اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون', 'اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 3, NULL, '"Indeed, I am placing a vicegerent on earth. They said: Are You going to create one that will corrupt and shed blood on it while we glorify Your praises and regard You holy? He said: Surely, I know what you know not." (Al-Baqarah: 30)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'indeed i am placing a vicegerent on earth they said are you going to create one that will corrupt and shed blood on it while we glorify your praises and regard you holy he said surely i know what you know not al baqarah 30', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 4, NULL, 'In that passage God, may He be glorified, made plain that there would never be a time when the earth stood without an imam — not even if every one of its inhabitants were sinless and saintly. They too must recognize how indispensable the imam is, given their own ignorance, while most people, in truth, are corrupt. God, the Exalted, made something else plain in the same passage: that if it were acceptable for the imam to be chosen (اَلْاِخْتِيَار), the angels above all would have been granted that choice. God would not have overruled them, for they were immune from base inclinations, from false desires, and from any craving for worldly power and mastery. Since the choice was not granted to the angels, it cannot belong to those beneath them. This same meaning lies within the words of God, the Exalted, concerning the rights of parents:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'in that passage god may he be glorified made plain that there would never be a time when the earth stood without an imam not even if every one of its inhabitants were sinless and saintly they too must recognize how indispensable the imam is given their own ignorance while most people in truth are corrupt god the exalted made something else plain in the same passage that if it were acceptable for the imam to be chosen الاختيار the angels above all would have been granted that choice god would not have overruled them for they were immune from base inclinations from false desires and from any craving for worldly power and mastery since the choice was not granted to the angels it cannot belong to those beneath them this same meaning lies within the words of god the exalted concerning the rights of parents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 5, NULL, 'Al-Isra: 23فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا', '', 'فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا', 'Al-Isra: 23', 17, 23, 'degrees of excellence 8 from adam to ali', 'al isra 23فلا تقل لهما اف ولا تنهرهما', 'فلا تقل لهما اف ولا تنهرهما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 6, NULL, '"Do not even say fie to them or tell them off." (Al-Isra: 23)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'do not even say fie to them or tell them off al isra 23', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 7, NULL, 'By forbidding the lesser wrong, God thereby forbade the harsher one of striking or abusing them.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'by forbidding the lesser wrong god thereby forbade the harsher one of striking or abusing them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 8, NULL, 'God, the Exalted, has told the stories of past communities and their prophets so that people would see that the same pattern would run its course in the cycle of the Prophet Muhammad exactly as it had run in the cycles before him. The Prophet said: "My community will experience exactly what happened among the Banu Israil." He also said: "You will follow the footsteps of those before you, step by step in an identical manner (اَلْقُذَّةَ بِالْقُذَّةِ), to the point that if they entered the hole of a lizard, you would enter it too."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'god the exalted has told the stories of past communities and their prophets so that people would see that the same pattern would run its course in the cycle of the prophet muhammad exactly as it had run in the cycles before him the prophet said my community will experience exactly what happened among the banu israil he also said you will follow the footsteps of those before you step by step in an identical manner القذه بالقذه to the point that if they entered the hole of a lizard you would enter it too', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 9, NULL, 'In the story of Adam there is a sign that the imamate and the caliphate cannot be established by choice or by consultation. Had they been permissible by such means, the choice and consultation of the angels would have been the most fitting of all, for the angels were free of jealousy and rebellion. In that story there is also a sign that it is not for people to declare whether a given man is or is not fit for the imamate, or to set one candidate above another. God, the Exalted, showed those who objected to Adam how mistaken their position was; He reproached them, rebuked them, and exposed the falsehood of their words. He kept this account in the Quran so that people would take it to heart and would not dispute the imamate or contest the one whom God and His Messenger had chosen for it, as those angels had done. And in the appointment of Adam''s son to the imamate there is a further sign that the world can never be without an imam. People accept the imams of Adam''s age yet deny them in the age of Muhammad, may God bless him, even though God, the Almighty and Glorious, has declared:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'in the story of adam there is a sign that the imamate and the caliphate cannot be established by choice or by consultation had they been permissible by such means the choice and consultation of the angels would have been the most fitting of all for the angels were free of jealousy and rebellion in that story there is also a sign that it is not for people to declare whether a given man is or is not fit for the imamate or to set one candidate above another god the exalted showed those who objected to adam how mistaken their position was he reproached them rebuked them and exposed the falsehood of their words he kept this account in the quran so that people would take it to heart and would not dispute the imamate or contest the one whom god and his messenger had chosen for it as those angels had done and in the appointment of adams son to the imamate there is a further sign that the world can never be without an imam people accept the imams of adams age yet deny them in the age of muhammad may god bless him even though god the almighty and glorious has declared', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 10, NULL, 'Al-Isra: 77سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا ۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', '', 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا ۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 'Al-Isra: 77', 17, 77, 'degrees of excellence 8 from adam to ali', 'al isra 77سنه من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا', 'سنه من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 11, NULL, '"Such was Our way (sunna) with the messengers We sent before you, and you will find no change in Our way." (Al-Isra: 77)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'such was our way sunna with the messengers we sent before you and you will find no change in our way al isra 77', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 12, NULL, 'He also said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'he also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 13, NULL, 'Al-Ahzab: 62وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًۭا', '', 'وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًۭا', 'Al-Ahzab: 62', 33, 62, 'degrees of excellence 8 from adam to ali', 'al ahzab 62ولن تجد لسنه الله تبديلا', 'ولن تجد لسنه الله تبديلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 14, NULL, '"You will find no change whatsoever in Our way (sunna)." (Al-Ahzab: 62)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'you will find no change whatsoever in our way sunna al ahzab 62', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 15, NULL, 'What is meant here is the way of the imamate, not the way of ritual practice such as prayer, fasting, and the like. For the Prophet, may God bless him, did indeed change the practice of every prophet before him in the acts of worship (الْعِبَادَات), yet he did not change the way of the imamate.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'what is meant here is the way of the imamate not the way of ritual practice such as prayer fasting and the like for the prophet may god bless him did indeed change the practice of every prophet before him in the acts of worship العبادات yet he did not change the way of the imamate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 16, NULL, 'I say further: when Noah (ع) called the people to the ark out of compassion, he knew full well that those who stayed behind would perish and drown, by their own choice and by their conviction that their good lay elsewhere. The pattern is clear: every people whose prophet and imam summoned them to a matter, and who then refused it and turned away, were destroyed for that refusal. The ark was none other than the imam himself, and Noah''s call to the people was a call to the imam — just as the Prophet said: "The likeness of my family (أَهْلُ الْبَيْت) among you is like Noah''s ark: whoever boards it will be saved, and whoever stays behind will be drowned."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'i say further when noah ع called the people to the ark out of compassion he knew full well that those who stayed behind would perish and drown by their own choice and by their conviction that their good lay elsewhere the pattern is clear every people whose prophet and imam summoned them to a matter and who then refused it and turned away were destroyed for that refusal the ark was none other than the imam himself and noahs call to the people was a call to the imam just as the prophet said the likeness of my family اهل البيت among you is like noahs ark whoever boards it will be saved and whoever stays behind will be drowned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 17, NULL, 'Noah appointed his son Shem (سَام) to the legateeship and the imamate by designation (النصّ) and appointment (التَّوْقِيف), and after him the line ran on, one after another, until the time of Abraham (ع). Those who oppose us accept the imams of Noah''s cycle yet deny them in the family of Muhammad, though the way has not been replaced or changed and people cannot do without an imam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'noah appointed his son shem سام to the legateeship and the imamate by designation النص and appointment التوقيف and after him the line ran on one after another until the time of abraham ع those who oppose us accept the imams of noahs cycle yet deny them in the family of muhammad though the way has not been replaced or changed and people cannot do without an imam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 18, NULL, 'When Abraham arose, he commanded that fire be glorified. If what has been said of this is correct, then it was a symbol pointing to the glorification of the light of the imamate (نُورُ الْإِمَامَة), as I have already said. Then Abraham and Ismail (عَلَيْهِمُ السَّلَامُ) built the House, the Kaba, and commanded the people to venerate it — itself a sign that the imamate was to dwell within Abraham''s household and lineage. He urged the people to honor the imamate and to venerate and obey the imams of his family.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'when abraham arose he commanded that fire be glorified if what has been said of this is correct then it was a symbol pointing to the glorification of the light of the imamate نور الامامه as i have already said then abraham and ismail عليهم السلام built the house the kaba and commanded the people to venerate it itself a sign that the imamate was to dwell within abrahams household and lineage he urged the people to honor the imamate and to venerate and obey the imams of his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 19, NULL, 'When Moses (ع) arose, he directed the people to face toward Jerusalem in prayer. Since Moses had no children or family in whom the imamate could continue, he pointed toward Jerusalem (بَيْتُ الْمُقَدَّس), meaning that whoever among the Banu Israil possesses the sanctified spirit is your imam and your direction of prayer (قِبْلَتَكُمْ). Then Jesus (ع) arose. He too had neither family nor children, and it is reported that he directed the people to face toward the east. If this is true, his command to face east meant turning toward the place from which the light of the imamate rises — that is, whoever radiates that light is your imam and your direction of prayer.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'when moses ع arose he directed the people to face toward jerusalem in prayer since moses had no children or family in whom the imamate could continue he pointed toward jerusalem بيت المقدس meaning that whoever among the banu israil possesses the sanctified spirit is your imam and your direction of prayer قبلتكم then jesus ع arose he too had neither family nor children and it is reported that he directed the people to face toward the east if this is true his command to face east meant turning toward the place from which the light of the imamate rises that is whoever radiates that light is your imam and your direction of prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 20, NULL, 'When the Prophet Muhammad, the seal of the prophets, may God bless him and his family, arose, he directed the people to turn away from Jerusalem toward the Kaba as the qibla of the Muslims. The Kaba had been built by Abraham and Ismail. In giving this command, the Prophet showed that the direction had returned to the house of Abraham — that is, to the family of Ismail — and that the imamate had therefore returned to the children of Ismail, who are the children of the Prophet Muhammad, may God bless him. He commanded the people to venerate the House and to make the pilgrimage to it, a thing no prophet before him had commanded, so as to impress upon them the supreme excellence of the imams of Muhammad''s family above every other imam of the cycles that had passed. Is there anyone in this world more iniquitous than this community? It accepted the imams of every prophetic age, affirmed that the world cannot be without an imam, and affirmed that no imam in any earlier cycle ever came to power by choice (اَلْاِخْتِيَار) — yet now it denies the imamate of Muhammad''s family, rejects designation (النصّ), and calls instead for choice. God, the Exalted, has said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'when the prophet muhammad the seal of the prophets may god bless him and his family arose he directed the people to turn away from jerusalem toward the kaba as the qibla of the muslims the kaba had been built by abraham and ismail in giving this command the prophet showed that the direction had returned to the house of abraham that is to the family of ismail and that the imamate had therefore returned to the children of ismail who are the children of the prophet muhammad may god bless him he commanded the people to venerate the house and to make the pilgrimage to it a thing no prophet before him had commanded so as to impress upon them the supreme excellence of the imams of muhammads family above every other imam of the cycles that had passed is there anyone in this world more iniquitous than this community it accepted the imams of every prophetic age affirmed that the world cannot be without an imam and affirmed that no imam in any earlier cycle ever came to power by choice الاختيار yet now it denies the imamate of muhammads family rejects designation النص and calls instead for choice god the exalted has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 21, NULL, 'Al-Qasas: 68وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ ۗ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ', '', 'وَرَبُّكَ يَخْلُقُ مَا يَشَآءُ وَيَخْتَارُ ۗ مَا كَانَ لَهُمُ ٱلْخِيَرَةُ', 'Al-Qasas: 68', 28, 68, 'degrees of excellence 8 from adam to ali', 'al qasas 68وربك يخلق ما يشاء ويختار ما كان لهم الخيره', 'وربك يخلق ما يشاء ويختار ما كان لهم الخيره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 22, NULL, '"Your Lord creates what He wills and chooses what is good for them." (Al-Qasas: 68)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'your lord creates what he wills and chooses what is good for them al qasas 68', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 23, NULL, 'If the imamate were settled by choice, every people would simply choose whomever they pleased. The elders have treated the dispute between designation and choice at length. I have said that I mean to present what the elders left unaddressed in the books on affirming the imamate, and what I have said here is enough. I shall now establish that the imam must be the most excellent, the most knowledgeable, and the noblest of mankind.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'if the imamate were settled by choice every people would simply choose whomever they pleased the elders have treated the dispute between designation and choice at length i have said that i mean to present what the elders left unaddressed in the books on affirming the imamate and what i have said here is enough i shall now establish that the imam must be the most excellent the most knowledgeable and the noblest of mankind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 24, NULL, 'I say that the virtues God, the Exalted, has named, and by which He has raised some people above others, are of three kinds (أَشْيَاء): knowledge, jihad, and piety. God, the Exalted, said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'i say that the virtues god the exalted has named and by which he has raised some people above others are of three kinds اشياء knowledge jihad and piety god the exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 25, NULL, 'An-Nisa: 95فَضَّلَ ٱللَّهُ ٱلْمُجَهِدِينَ بِأَمْوَلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَعِدِينَ', '', 'فَضَّلَ ٱللَّهُ ٱلْمُجَهِدِينَ بِأَمْوَلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَعِدِينَ', 'An-Nisa: 95', 4, 95, 'degrees of excellence 8 from adam to ali', 'an nisa 95فضل الله المجهدين بامولهم وانفسهم علي القعدين', 'فضل الله المجهدين بامولهم وانفسهم علي القعدين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 26, NULL, '"God has preferred those who strive and struggle over those who sit back by a great reward in degrees of rank." (An-Nisa: 95-96)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'god has preferred those who strive and struggle over those who sit back by a great reward in degrees of rank an nisa 95 96', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 27, NULL, 'He also said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'he also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 28, NULL, 'Az-Zumar: 9ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ', '', 'ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ', 'Az-Zumar: 9', 39, 9, 'degrees of excellence 8 from adam to ali', 'az zumar 9الذين يعلمون والذين لا يعلمون', 'الذين يعلمون والذين لا يعلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 29, NULL, '"Are those who know and those who do not, equal?" (Az-Zumar: 9)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'are those who know and those who do not equal az zumar 9', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 30, NULL, 'And:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 31, NULL, 'Al-Mujadila: 11أُوتُوا۟ ٱلْعِلْمَ دَرَجَتٍۢ', '', 'أُوتُوا۟ ٱلْعِلْمَ دَرَجَتٍۢ', 'Al-Mujadila: 11', 58, 11, 'degrees of excellence 8 from adam to ali', 'al mujadila 11اوتوا العلم درجت', 'اوتوا العلم درجت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 32, NULL, '"Those who have been given knowledge have degrees of rank." (Al-Mujadila: 11)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'those who have been given knowledge have degrees of rank al mujadila 11', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 33, NULL, 'And:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'from adam to ali', '8. From Adam to Ali', 34, NULL, 'Al-Hujurat: 13أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ', '', 'أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ', 'Al-Hujurat: 13', 49, 13, 'degrees of excellence 8 from adam to ali', 'al hujurat 13اكرمكم عند الله اتقاكم', 'اكرمكم عند الله اتقاكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 35, NULL, '"The most noble among you in the presence of God is the most pious among you." (Al-Hujurat: 13)', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'the most noble among you in the presence of god is the most pious among you al hujurat 13', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 36, NULL, 'As for jihad, both the elite (الْخَاصّ) and the ordinary Muslims (الْعَامّ) know well that these men never once fought in a single battle in person. The exploits of the Commander of the Faithful, Ali (ع), in war are famous and celebrated. The only mark these others left upon holy war was their flight at the battle of Hunayn, when Umar disobeyed the Prophet''s plain order and counsel to hold the mountain pass and so drew the censure of the Muslims, while the Prophet and Ali fought on and cut the enemy down until they were routed.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'as for jihad both the elite الخاص and the ordinary muslims العام know well that these men never once fought in a single battle in person the exploits of the commander of the faithful ali ع in war are famous and celebrated the only mark these others left upon holy war was their flight at the battle of hunayn when umar disobeyed the prophets plain order and counsel to hold the mountain pass and so drew the censure of the muslims while the prophet and ali fought on and cut the enemy down until they were routed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 37, NULL, 'As for piety (اَلتَّقْوَى), where there is no knowledge there can be no piety, for piety comes through knowledge — through knowing what belongs to oneself and what belongs to others. It is reported that a God-fearing man (الْمُحْتَسِبِين) once asked Muhammad b. al-Hasan, the companion of Abu Hanifa, to compile a book on asceticism. He compiled a book on trade instead, and when he was asked why, he replied: "Whoever has not mastered the law of buying and selling, how can he eat only what is lawful? And whoever does not eat only what is lawful has no asceticism." It follows, then, from the Quranic verses I have cited, that the imamate rightly belonged to the Commander of the Faithful (ع), for he had precedence (اَلسَّابِق) in every virtue: he was the most knowledgeable, the most pious, and the one who fought most in the cause of Islam.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'as for piety التقوي where there is no knowledge there can be no piety for piety comes through knowledge through knowing what belongs to oneself and what belongs to others it is reported that a god fearing man المحتسبين once asked muhammad b al hasan the companion of abu hanifa to compile a book on asceticism he compiled a book on trade instead and when he was asked why he replied whoever has not mastered the law of buying and selling how can he eat only what is lawful and whoever does not eat only what is lawful has no asceticism it follows then from the quranic verses i have cited that the imamate rightly belonged to the commander of the faithful ع for he had precedence السابق in every virtue he was the most knowledgeable the most pious and the one who fought most in the cause of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 38, NULL, 'I maintain further that those who ruled never claimed excellence, knowledge, or piety for themselves. It was their companions who made those claims on their behalf. Indeed, Abu Bakr was the first to climb the pulpit and say: "You have appointed me, although I am not the best among you." If he spoke the truth, then those who claim greater excellence for him are liars. If he lied, then a liar cannot be an imam. And should it be said that he spoke out of humility, I answer that humility has its proper time and place. The Prophet himself, may God bless him, would speak openly of the rank and honor with which God had singled him out, and that was no arrogance. He said: "I am the master of the Arabs, without boasting"; "I am the master of humanity, without boasting"; and "I am the most eloquent of the Arabs, without boasting."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'i maintain further that those who ruled never claimed excellence knowledge or piety for themselves it was their companions who made those claims on their behalf indeed abu bakr was the first to climb the pulpit and say you have appointed me although i am not the best among you if he spoke the truth then those who claim greater excellence for him are liars if he lied then a liar cannot be an imam and should it be said that he spoke out of humility i answer that humility has its proper time and place the prophet himself may god bless him would speak openly of the rank and honor with which god had singled him out and that was no arrogance he said i am the master of the arabs without boasting i am the master of humanity without boasting and i am the most eloquent of the arabs without boasting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 39, NULL, 'The Commander of the Faithful, Ali b. Abi Talib (ع), said: "Ask me before you lose me." He also said: "If a cushion were folded for me to sit upon, I would judge the followers of the Torah by the Torah, the followers of the Bible by the Bible, and the followers of the Furqan (اَلْفُرْقَان) by the Furqan." Many such sayings could be cited, and not one of them is arrogance or a denial of humility. Abu Bakr''s words, "I have been put in charge of you although I am not the best among you," show that neither God nor His Messenger had granted him preference or designated him — not by ordering him to lead the prayer, nor in any other way. He confirmed of himself everything that was to be expected of him, and so he added: "Put me right." Correction of that kind is needed only in the case of grave and serious sins, since the lesser ones are wiped away by seeking forgiveness.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'the commander of the faithful ali b abi talib ع said ask me before you lose me he also said if a cushion were folded for me to sit upon i would judge the followers of the torah by the torah the followers of the bible by the bible and the followers of the furqan الفرقان by the furqan many such sayings could be cited and not one of them is arrogance or a denial of humility abu bakrs words i have been put in charge of you although i am not the best among you show that neither god nor his messenger had granted him preference or designated him not by ordering him to lead the prayer nor in any other way he confirmed of himself everything that was to be expected of him and so he added put me right correction of that kind is needed only in the case of grave and serious sins since the lesser ones are wiped away by seeking forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'from adam to ali', '8. From Adam to Ali', 40, NULL, 'When Umar climbed the pulpit after Abu Bakr, he declared: "The oath (بَيْعَة) to Abu Bakr was a falta, a hasty and unconsidered thing, but God has spared us its evil. Whoever repeats the like of it, kill him." In saying this, he himself tore down the literalists'' claim that the Prophet''s instruction to have Abu Bakr lead the prayer made his imamate binding and served as its designation. His statement also refutes what they cite from the traditions, such as: "Follow the two who come after me, Abu Bakr and Umar."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 8 from adam to ali', 'when umar climbed the pulpit after abu bakr he declared the oath بيعه to abu bakr was a falta a hasty and unconsidered thing but god has spared us its evil whoever repeats the like of it kill him in saying this he himself tore down the literalists claim that the prophets instruction to have abu bakr lead the prayer made his imamate binding and served as its designation his statement also refutes what they cite from the traditions such as follow the two who come after me abu bakr and umar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 0, NULL, 'We shall now set down some of the merits of the lord of the age and time (وَلِيُّ الْعَصْرِ وَالزَّمَانِ), the Commander of the Faithful (al-Hakim) — though a man of my standing could never rise to the rank that would allow a true account of his merits, just as God the Exalted has said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'we shall now set down some of the merits of the lord of the age and time ولي العصر والزمان the commander of the faithful al hakim though a man of my standing could never rise to the rank that would allow a true account of his merits just as god the exalted has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 1, NULL, '"They have not valued God according to His true value."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'they have not valued god according to his true value', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 2, NULL, 'Still, I will speak according to my slight knowledge and small capacity, and the Commander of the Faithful is most worthy to accept his servant''s excuse. God the Exalted, in the fullness of His bounty toward His servants, called upon them to give thanks for His blessings; and when they proved unable to render thanks in proportion to those blessings, He forgave them and was content that they say al-hamdulillah (praise be to God). In this there was a lesson for His creation: whenever thanks are owed to a benefactor yet one cannot express them in full measure with the bounty received, one should give thanks as best one can and not abandon gratitude altogether merely because one cannot render it in full.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'still i will speak according to my slight knowledge and small capacity and the commander of the faithful is most worthy to accept his servants excuse god the exalted in the fullness of his bounty toward his servants called upon them to give thanks for his blessings and when they proved unable to render thanks in proportion to those blessings he forgave them and was content that they say al hamdulillah praise be to god in this there was a lesson for his creation whenever thanks are owed to a benefactor yet one cannot express them in full measure with the bounty received one should give thanks as best one can and not abandon gratitude altogether merely because one cannot render it in full', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 3, NULL, 'We say further that God the Exalted has made the earth radiant with His light, as He promised and declared:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'we say further that god the exalted has made the earth radiant with his light as he promised and declared', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 4, NULL, '"And the earth shines by the light of her Lord ..."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'and the earth shines by the light of her lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 5, NULL, 'By this He means that the earth of outward reality shines through the justice of the Commander of the Faithful, and the earth of inner meaning shines through knowledge and interpretation.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'by this he means that the earth of outward reality shines through the justice of the commander of the faithful and the earth of inner meaning shines through knowledge and interpretation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 6, NULL, 'In every species, genus, root, branch, and law there is a peak and a summit of nobility, merit, rank, degree, and station that nothing else can reach. It follows that the imams (عَلَيْهِمُ السَّلَامُ) must likewise possess a peak, a summit, and an utmost degree that no one before them has attained. That peak and utmost degree is the Commander of the Faithful, Ali. He is the summit of all summits, the furthest limit beyond which no other limit lies. Just as the wisdom of the world, and of the animals and plants within it, came to full expression in the emergence of human beings — the well-being of all creation completed through humanity, and the benefit of all created things returning at last to mankind — and just as it is through the imams that the merits of humanity have been perfected and wisdom has become manifest in creation, so that the benefit of all human beings flows back to the imams: in the same way, through the Commander of the Faithful, all the affairs (أُمُور) of the prophets, legatees, and imams reached their completion, their order (أَمْر) was set in place, and perfect wisdom became manifest in their dispensation, their laws, and their inner interpretations. He is like the head, and they are like the body. They are the body, and the Commander of the Faithful is the spirit, and no body is complete without its spirit. The Commander of the Faithful is like the heart, and all those who have passed away are like the limbs. It is through the joining of spirit and life in the heart that all the limbs receive life and sustenance. Every nail, every hair, every limb receives its share of nourishment and vitality by way of the heart. This is the sensory knowledge, the recompense of action, that comes to the embryo in its womb (دَار عَمَلِه) through the six stages of development from sperm to fully formed creature.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'in every species genus root branch and law there is a peak and a summit of nobility merit rank degree and station that nothing else can reach it follows that the imams عليهم السلام must likewise possess a peak a summit and an utmost degree that no one before them has attained that peak and utmost degree is the commander of the faithful ali he is the summit of all summits the furthest limit beyond which no other limit lies just as the wisdom of the world and of the animals and plants within it came to full expression in the emergence of human beings the well being of all creation completed through humanity and the benefit of all created things returning at last to mankind and just as it is through the imams that the merits of humanity have been perfected and wisdom has become manifest in creation so that the benefit of all human beings flows back to the imams in the same way through the commander of the faithful all the affairs امور of the prophets legatees and imams reached their completion their order امر was set in place and perfect wisdom became manifest in their dispensation their laws and their inner interpretations he is like the head and they are like the body they are the body and the commander of the faithful is the spirit and no body is complete without its spirit the commander of the faithful is like the heart and all those who have passed away are like the limbs it is through the joining of spirit and life in the heart that all the limbs receive life and sustenance every nail every hair every limb receives its share of nourishment and vitality by way of the heart this is the sensory knowledge the recompense of action that comes to the embryo in its womb دار عمله through the six stages of development from sperm to fully formed creature', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 7, NULL, 'In the same way, it is through the Commander of the Faithful that people attain recompense and the fullness of life in the seventh stage. He is the one who awakens in every soul the longing to draw near to him, and he is the one through whom God has promised creation the fulfillment of its reward on His day. As God said of the Judgment:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'in the same way it is through the commander of the faithful that people attain recompense and the fullness of life in the seventh stage he is the one who awakens in every soul the longing to draw near to him and he is the one through whom god has promised creation the fulfillment of its reward on his day as god said of the judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 8, NULL, '"... And you will be paid only that which you have earned fairly on the Day of Resurrection. Whoever is removed from the Fire and allowed to enter Paradise will indeed be triumphant."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'and you will be paid only that which you have earned fairly on the day of resurrection whoever is removed from the fire and allowed to enter paradise will indeed be triumphant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 9, NULL, 'God commands creation to believe in Him and in His Day of Judgment when He says:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'god commands creation to believe in him and in his day of judgment when he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 10, NULL, '"... They believe in God and the Last Day ..."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'they believe in god and the last day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 11, NULL, 'Just as the whole of humanity stands as the final realm of nature (مَوَالِيد) in the world, having absorbed all that existed in the earlier realms and surpassing it in ways those realms could not share; and just as the imams gathered within themselves all the merits that existed in humanity, being its peak, its summit, and its quintessence, able to receive what lay beyond ordinary human capacity, so that the benefit of all who preceded them flows to the imams: in the same way, the Commander of the Faithful (ع) gathers within himself all the merits of those who came before him, and all their benefit and knowledge converge in him, surpassing what came before many times over. Just as the Prophet''s power and merit came from gathering within himself the merits of those in earlier cycles, all their knowledge and more, so too the Commander of the Faithful gathers within himself the merits of all the prophets, imams, and sages who preceded him in earlier cycles, and exceeds them in matters beyond their reach. Had he not arisen in this station, the perfection of wisdom in their arising would not have been achieved. The Commander of the Faithful is therefore the sum of everything in the worlds today — spiritual, physical, and conventional (اَلْوَضْعِيّ). It is for his sake that these worlds were created, and all of them are his agents and heralds until His Day of Judgment. He is the one who arose in the world to bring the Creator''s vicegerency among humanity to its perfection in the universe. We have indeed said that he is the perfector (مُتِمّ) of all those who have passed away.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'just as the whole of humanity stands as the final realm of nature مواليد in the world having absorbed all that existed in the earlier realms and surpassing it in ways those realms could not share and just as the imams gathered within themselves all the merits that existed in humanity being its peak its summit and its quintessence able to receive what lay beyond ordinary human capacity so that the benefit of all who preceded them flows to the imams in the same way the commander of the faithful ع gathers within himself all the merits of those who came before him and all their benefit and knowledge converge in him surpassing what came before many times over just as the prophets power and merit came from gathering within himself the merits of those in earlier cycles all their knowledge and more so too the commander of the faithful gathers within himself the merits of all the prophets imams and sages who preceded him in earlier cycles and exceeds them in matters beyond their reach had he not arisen in this station the perfection of wisdom in their arising would not have been achieved the commander of the faithful is therefore the sum of everything in the worlds today spiritual physical and conventional الوضعي it is for his sake that these worlds were created and all of them are his agents and heralds until his day of judgment he is the one who arose in the world to bring the creators vicegerency among humanity to its perfection in the universe we have indeed said that he is the perfector متم of all those who have passed away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 12, NULL, 'Some may object that this description belongs to the final qaim, and that the Commander of the Faithful is not the final one. We answer that the Commander of the Faithful [al-Hakim] is the qaim of his own time and age, and the qaim of all who preceded him, and the perfector of them all. He is the sixth, through whom the command of the seventh will be perfected. He will complete what the seventh requires, just as the Prophet, may God bless him, established all that the qaim would need in order to become the perfector of what the Prophet had established and arranged. By a different reckoning the Commander of the Faithful is the ninth. The command of the seventh, al-Muizz, who has passed away, is perfected through the ninth, al-Hakim — just as the seven members of the human body reach their perfection, order, and function through the nine, that is, the four natures and the five senses, and just as the perfection of the human creature is achieved in nine months. This reckoning rests on the number nine. Life in the hereafter rests on four spiritual natures and five spiritual senses, as God said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'some may object that this description belongs to the final qaim and that the commander of the faithful is not the final one we answer that the commander of the faithful al hakim is the qaim of his own time and age and the qaim of all who preceded him and the perfector of them all he is the sixth through whom the command of the seventh will be perfected he will complete what the seventh requires just as the prophet may god bless him established all that the qaim would need in order to become the perfector of what the prophet had established and arranged by a different reckoning the commander of the faithful is the ninth the command of the seventh al muizz who has passed away is perfected through the ninth al hakim just as the seven members of the human body reach their perfection order and function through the nine that is the four natures and the five senses and just as the perfection of the human creature is achieved in nine months this reckoning rests on the number nine life in the hereafter rests on four spiritual natures and five spiritual senses as god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 13, NULL, '"Indeed, the abode of the hereafter, that is life, if only they knew."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'indeed the abode of the hereafter that is life if only they knew', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 14, NULL, 'By yet another calculation the Commander of the Faithful [al-Hakim] is the second, for the order at the beginning of each cycle is perfected by the second. He is also the sixth, through whose sword God will conquer the whole world, just as He conquered through the Prophet, may God bless him, the sixth from Adam. The Commander of the Faithful arose in the world to bring to perfection the vicegerency (اَلْخِلَافَة) of the Creator of the universe among His creatures. He deals with creation in every circumstance as God the Exalted deals with His creatures — with regard to their constitution, their sustenance, and the abundance of His mercy toward them. Each of those who arose before him fulfilled only a small portion of this, but the Commander of the Faithful fulfilled the whole of it. A vicegerent is one who, over those entrusted to him, carries out everything that the one who appointed him would do.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'by yet another calculation the commander of the faithful al hakim is the second for the order at the beginning of each cycle is perfected by the second he is also the sixth through whose sword god will conquer the whole world just as he conquered through the prophet may god bless him the sixth from adam the commander of the faithful arose in the world to bring to perfection the vicegerency الخلافه of the creator of the universe among his creatures he deals with creation in every circumstance as god the exalted deals with his creatures with regard to their constitution their sustenance and the abundance of his mercy toward them each of those who arose before him fulfilled only a small portion of this but the commander of the faithful fulfilled the whole of it a vicegerent is one who over those entrusted to him carries out everything that the one who appointed him would do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 15, NULL, 'Indeed, Adam, like all the other vicegerents, was called "vicegerent" (خَلِيفَة) because he was the first to take up the vicegerency. Those who came after him fulfilled some of its conditions and so were called by that name, for whoever discharges part of a duty is known by its name. The Commander of the Faithful, however, performs both the worldly and the religious vicegerency in full reality. When the Prophet, may God bless him, said,', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'indeed adam like all the other vicegerents was called vicegerent خليفه because he was the first to take up the vicegerency those who came after him fulfilled some of its conditions and so were called by that name for whoever discharges part of a duty is known by its name the commander of the faithful however performs both the worldly and the religious vicegerency in full reality when the prophet may god bless him said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 16, NULL, '"The ruler is the shadow of God on earth,"', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'the ruler is the shadow of god on earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 17, NULL, 'he meant none other than the Commander of the Faithful, for a shadow copies in every detail the thing that casts it. No one deals with creation as God the Exalted does, except the Commander of the Faithful. The Prophet, may God bless him, also said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'he meant none other than the commander of the faithful for a shadow copies in every detail the thing that casts it no one deals with creation as god the exalted does except the commander of the faithful the prophet may god bless him also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 18, NULL, '"Indeed God, the Exalted, establishes (nazaa) proof through the ruler beyond what He establishes through the Quran,"', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'indeed god the exalted establishes nazaa proof through the ruler beyond what he establishes through the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 19, NULL, 'and the Commander of the Faithful is the one through whom God establishes what He does not establish through the Quran.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'and the commander of the faithful is the one through whom god establishes what he does not establish through the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 20, NULL, 'The philosophers have said that philosophy is the pursuit of resemblance to God (التَّشَبُّهُ بِالْبَارِئِ), glory be to Him, according to human capacity. To seek resemblance to the Creator, glory be to Him, means to deal with mankind as God, may His mention be exalted, deals with them — to interact with them, and with oneself, as God acts with both humanity and the individual, and in keeping with their nature. The philosophers borrowed this idea from the people of the truth (أَهْلُ الْحَقِيقَة), yet none of them has been able to realize its true meaning except the Commander of the Faithful. Indeed, everything he does with mankind mirrors God''s own dealings with them in the order of the world, in sustenance, and in all that pertains to these. We shall now mention a small portion of what suits the time in which we live.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'the philosophers have said that philosophy is the pursuit of resemblance to god التشبه بالباري glory be to him according to human capacity to seek resemblance to the creator glory be to him means to deal with mankind as god may his mention be exalted deals with them to interact with them and with oneself as god acts with both humanity and the individual and in keeping with their nature the philosophers borrowed this idea from the people of the truth اهل الحقيقه yet none of them has been able to realize its true meaning except the commander of the faithful indeed everything he does with mankind mirrors gods own dealings with them in the order of the world in sustenance and in all that pertains to these we shall now mention a small portion of what suits the time in which we live', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 21, NULL, 'Let us begin by saying that the compassion, mercy, bounty, and forgiveness of the Commander of the Faithful [al-Hakim], together with his forbearance toward people''s failings and disobedience, are beyond my power to describe. All of it follows God''s own conduct toward humanity, in obedience to God''s command and in emulation of His character.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'let us begin by saying that the compassion mercy bounty and forgiveness of the commander of the faithful al hakim together with his forbearance toward peoples failings and disobedience are beyond my power to describe all of it follows gods own conduct toward humanity in obedience to gods command and in emulation of his character', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 22, NULL, 'God in His bounty bestows blessings upon people whether they are pious or impious, believers or unbelievers. Had He granted worldly benefit to believers alone and withheld it from unbelievers, people''s faith would have been driven by worldly gain rather than by God or His religion. Conversely, had He denied it to all believers and given it only to unbelievers, most people''s belief (إِيْمَانْ) would surely have slipped back into unbelief (اَلْكُفْر). So He gave it to some unbelievers and withheld it from others, just as He gave it to some believers and withheld it from others, giving to each at certain times and withholding at others. Likewise, the Commander of the Faithful bestows worldly benefit on Muslims and unbelievers alike, and withholds it from them too; he bestows it on believers and hypocrites alike, and withholds it from them too. He gave to all of them at some times and withheld at others. Had he given everything to the believers, their faith would largely have been for the sake of this world; but had he withheld from all believers at all times, they would surely have grown disheartened and their good intentions would have weakened. So the Commander of the Faithful bestowed blessings on the believers for a season as no one else had ever bestowed, and he also withheld from them for a season, for their own good, lest they become like those of whom God said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'god in his bounty bestows blessings upon people whether they are pious or impious believers or unbelievers had he granted worldly benefit to believers alone and withheld it from unbelievers peoples faith would have been driven by worldly gain rather than by god or his religion conversely had he denied it to all believers and given it only to unbelievers most peoples belief ايمان would surely have slipped back into unbelief الكفر so he gave it to some unbelievers and withheld it from others just as he gave it to some believers and withheld it from others giving to each at certain times and withholding at others likewise the commander of the faithful bestows worldly benefit on muslims and unbelievers alike and withholds it from them too he bestows it on believers and hypocrites alike and withholds it from them too he gave to all of them at some times and withheld at others had he given everything to the believers their faith would largely have been for the sake of this world but had he withheld from all believers at all times they would surely have grown disheartened and their good intentions would have weakened so the commander of the faithful bestowed blessings on the believers for a season as no one else had ever bestowed and he also withheld from them for a season for their own good lest they become like those of whom god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 23, NULL, '"Nay, indeed man certainly becomes rebellious, considering himself self-sufficient."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'nay indeed man certainly becomes rebellious considering himself self sufficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 24, NULL, 'God gave worldly goods to the pious and the impious alike, so that the pious would not do good deeds merely for the sake of this world, nor refrain from wrongdoing merely for worldly reasons, nor hold back from disobedience only for worldly benefit — which would deprive them of their reward in the hereafter. Rather, their conduct should be purely for the sake of religion and God. Likewise, the Commander of the Faithful gives worldly benefits to the righteous and the immoral alike.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'god gave worldly goods to the pious and the impious alike so that the pious would not do good deeds merely for the sake of this world nor refrain from wrongdoing merely for worldly reasons nor hold back from disobedience only for worldly benefit which would deprive them of their reward in the hereafter rather their conduct should be purely for the sake of religion and god likewise the commander of the faithful gives worldly benefits to the righteous and the immoral alike', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 25, NULL, 'God the Exalted has given this passing world to those who obey and those who disobey, out of His wisdom, so that obedience should not be for the sake of the world, nor restraint from disobedience because of it; rather, both should be purely for the sake of God. In the same way, the Commander of the Faithful gives to the obedient and the disobedient alike, following the actions of God the Exalted, so that humanity''s obedience to him is not for worldly advantage and the reward of the hereafter is not lost.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'god the exalted has given this passing world to those who obey and those who disobey out of his wisdom so that obedience should not be for the sake of the world nor restraint from disobedience because of it rather both should be purely for the sake of god in the same way the commander of the faithful gives to the obedient and the disobedient alike following the actions of god the exalted so that humanitys obedience to him is not for worldly advantage and the reward of the hereafter is not lost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 26, NULL, 'God gives worldly goods to the worshipper and the non-worshipper alike, lest people''s worship be driven by worldly gain. In the same way, the Commander of the Faithful looks upon his people not with an eye fixed on their faults and disobedience, but with a merciful eye. God the Exalted has given worldly benefit to the simpleton and the ignorant, and has given it to the learned and the intelligent, while also withholding it from both. Likewise, the Commander of the Faithful gives to the simpleton and the ignorant, the learned and the intelligent alike, out of his wisdom and virtue. Were he to give only to the learned and the intelligent and withhold from all others, people would pursue knowledge solely for the sake of this world, and their use of reason and their gaining of virtues would likewise be for this world alone, leaving the ignorant and the simpleton in despair. But God has given the world equally to the simpleton and the ignorant.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'god gives worldly goods to the worshipper and the non worshipper alike lest peoples worship be driven by worldly gain in the same way the commander of the faithful looks upon his people not with an eye fixed on their faults and disobedience but with a merciful eye god the exalted has given worldly benefit to the simpleton and the ignorant and has given it to the learned and the intelligent while also withholding it from both likewise the commander of the faithful gives to the simpleton and the ignorant the learned and the intelligent alike out of his wisdom and virtue were he to give only to the learned and the intelligent and withhold from all others people would pursue knowledge solely for the sake of this world and their use of reason and their gaining of virtues would likewise be for this world alone leaving the ignorant and the simpleton in despair but god has given the world equally to the simpleton and the ignorant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 27, NULL, 'He has also given worldly benefit to the wrongdoer and the just, to the generous and the miserly, to the noble and the depraved and the lowly, to those possessing every virtue and those lacking it — giving to all of them equally out of His wisdom, mercy, and grace. Likewise, the Commander of the Faithful treats all of them equally, following the actions of God the Exalted and His mercy toward His creatures, so that everyone may receive a fair share of His bounty and kindness.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'he has also given worldly benefit to the wrongdoer and the just to the generous and the miserly to the noble and the depraved and the lowly to those possessing every virtue and those lacking it giving to all of them equally out of his wisdom mercy and grace likewise the commander of the faithful treats all of them equally following the actions of god the exalted and his mercy toward his creatures so that everyone may receive a fair share of his bounty and kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 28, NULL, 'Furthermore, God the Exalted has hidden the workings of the world and the means by which His creatures may benefit from it, concealing from mankind both the methods and the actions needed to acquire worldly goods. So one person becomes wealthy while another has nothing to eat; one grows rich through trade and commerce while another goes bankrupt; one prospers from farming while another loses even his seed; and one becomes self-sufficient through hunting while another is left destitute. All of this reflects God''s surpassing wisdom, lest a single path to worldly gain become known to everyone while every other path becomes useless, bringing disorder upon creation and corruption upon the world. The Commander of the Faithful''s dealings with mankind in this world follow the same pattern. He hides the means to worldly goods, so that one person seeks them by a particular means and receives them, while another who seeks them by the very same means is denied. Were people to discover a sure method for obtaining worldly goods from the Commander of the Faithful, every other means would certainly become useless. All those who lacked that one means would despair of his mercy, be left deprived, and there would be no merit in any of it.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'furthermore god the exalted has hidden the workings of the world and the means by which his creatures may benefit from it concealing from mankind both the methods and the actions needed to acquire worldly goods so one person becomes wealthy while another has nothing to eat one grows rich through trade and commerce while another goes bankrupt one prospers from farming while another loses even his seed and one becomes self sufficient through hunting while another is left destitute all of this reflects gods surpassing wisdom lest a single path to worldly gain become known to everyone while every other path becomes useless bringing disorder upon creation and corruption upon the world the commander of the faithfuls dealings with mankind in this world follow the same pattern he hides the means to worldly goods so that one person seeks them by a particular means and receives them while another who seeks them by the very same means is denied were people to discover a sure method for obtaining worldly goods from the commander of the faithful every other means would certainly become useless all those who lacked that one means would despair of his mercy be left deprived and there would be no merit in any of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 29, NULL, 'The Commander of the Faithful''s conduct in drawing people near or keeping his distance from them follows the same principle. Were he to push the hypocrites away and draw only the believers near, people would become believers to win his favor, not out of genuine religion. And were he to keep his distance from all believers at all times, they would withdraw from him, anxiety creeping into their hearts, either from a sense of the Commander of the Faithful''s displeasure or from a fear that some slip of theirs had warranted it. So he deals with people according to what the prevailing times and conditions require — arousing desire and alarm, drawing near and pushing away, granting and withholding, punishing and forgiving — all of it following the actions and character of God the Exalted, so that people remain forever in a state of both fear and hope: neither so secure that they grow bold, nor so despairing that they lose heart. In all of this he emulates God''s manner with His creation. Just as God, may He be glorified, gives abundantly to all, even to those who have no fear of poverty or of wealth running dry, so too the Commander of the Faithful gives to those who have no such fear, surpassing the generosity of every other human being.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'the commander of the faithfuls conduct in drawing people near or keeping his distance from them follows the same principle were he to push the hypocrites away and draw only the believers near people would become believers to win his favor not out of genuine religion and were he to keep his distance from all believers at all times they would withdraw from him anxiety creeping into their hearts either from a sense of the commander of the faithfuls displeasure or from a fear that some slip of theirs had warranted it so he deals with people according to what the prevailing times and conditions require arousing desire and alarm drawing near and pushing away granting and withholding punishing and forgiving all of it following the actions and character of god the exalted so that people remain forever in a state of both fear and hope neither so secure that they grow bold nor so despairing that they lose heart in all of this he emulates gods manner with his creation just as god may he be glorified gives abundantly to all even to those who have no fear of poverty or of wealth running dry so too the commander of the faithful gives to those who have no such fear surpassing the generosity of every other human being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 30, NULL, 'Whoever looks with clear sight at the actions of the Commander of the Faithful in matters of religion and the world will find that everything he does with creation — commanding good, forbidding evil, granting and withholding — runs parallel to the actions of God the Exalted. Yet people are baffled by this, because they judge his actions by the standard of ordinary human beings and of what they have heard before. They compare the actions of the Commander of the Faithful with those of other people and other rulers, against what they have heard, seen, and understood. Finding them at odds with what they are used to, they fall into perplexity, confusion, and guesswork. Were they instead to view his actions in relation to God''s dealings with creation, everything would become far clearer. The difficulty arises only because, from the time of Adam to our own day, no one has ever acted in this way. If anyone did act in this way at any time, it was only in a small portion, as is reported in the story of the sage Khidr with Moses (ع). Moses could not bear Khidr''s actions because he measured them against his own deeds, knowledge, and understanding. Had he viewed them in relation to God''s actions, the outcome would surely have been different. Another example is the reported judgment of David and God''s command in the perplexing and astonishing story of the owner of the vineyard and the owner of the bull. Likewise, God the Exalted has given warning in His words:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'whoever looks with clear sight at the actions of the commander of the faithful in matters of religion and the world will find that everything he does with creation commanding good forbidding evil granting and withholding runs parallel to the actions of god the exalted yet people are baffled by this because they judge his actions by the standard of ordinary human beings and of what they have heard before they compare the actions of the commander of the faithful with those of other people and other rulers against what they have heard seen and understood finding them at odds with what they are used to they fall into perplexity confusion and guesswork were they instead to view his actions in relation to gods dealings with creation everything would become far clearer the difficulty arises only because from the time of adam to our own day no one has ever acted in this way if anyone did act in this way at any time it was only in a small portion as is reported in the story of the sage khidr with moses ع moses could not bear khidrs actions because he measured them against his own deeds knowledge and understanding had he viewed them in relation to gods actions the outcome would surely have been different another example is the reported judgment of david and gods command in the perplexing and astonishing story of the owner of the vineyard and the owner of the bull likewise god the exalted has given warning in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 31, NULL, '"On the day when the summoner calls them to a painful end ... their eyes will be lowered in humiliation,"', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'on the day when the summoner calls them to a painful end their eyes will be lowered in humiliation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 32, NULL, 'and He said:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'verse', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 33, NULL, 'Al-Qalam: 43وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَلِمُونَ', '', 'وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَلِمُونَ', 'Al-Qalam: 43', 68, 43, 'degrees of excellence 9 gods vicegerent in his time', 'al qalam 43وقد كانوا يدعون الي السجود وهم سلمون', 'وقد كانوا يدعون الي السجود وهم سلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 34, NULL, '"They were called to prostrate while safe and secure."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'they were called to prostrate while safe and secure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 35, NULL, 'It is remarkable that if people cannot bear these worldly actions, how then can they bear the far greater demands of religious matters and things harder still? Everything found at the two extremes does not exist at the center, and what exists at the center does not exist at the extremes; yet people judge these matters by what they observe at the center while they themselves stand at the extremities. That is precisely why they become confused and confounded, unable to bear or endure it.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'it is remarkable that if people cannot bear these worldly actions how then can they bear the far greater demands of religious matters and things harder still everything found at the two extremes does not exist at the center and what exists at the center does not exist at the extremes yet people judge these matters by what they observe at the center while they themselves stand at the extremities that is precisely why they become confused and confounded unable to bear or endure it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 36, NULL, 'We also observe that the gifts of other monarchs are seen by people as given in return for a service, a relationship, an obligation, love, need, the pursuit of some benefit, or the warding off of some harm. Such gifts may also spring from other motives that make them necessary: fear of calamity, hope of good fortune, fear of someone''s censure, the desire for praise or exaltation, the wish for gratitude or goodwill, payment to an official, or the provision of sustenance. All of this is conducted on the basis of calculation and assessment. The gifts of the Commander of the Faithful, however, rise above all of that, for gifts given for any of the reasons named above cannot truly be called generosity, virtue, or beneficence. They amount to either the discharge of a past obligation or an advance toward a future one. To delay what one owes and fulfill rights late is blameworthy and miserly; and to advance money in expectation of future benefit is neither generosity nor virtue. Nor is anything given in connection with a debt counted as generosity, nobility, or virtue. The gifts of God, glory be to Him, rise above all of that, for God is under no obligation to give anyone anything, and He seeks no reward from any of His creatures. In the same way, the Commander of the Faithful does not give to anyone for any of the reasons named, nor does he seek recompense for it. God the Exalted said regarding the Commander of the Faithful, Ali b. Abi Talib:', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'we also observe that the gifts of other monarchs are seen by people as given in return for a service a relationship an obligation love need the pursuit of some benefit or the warding off of some harm such gifts may also spring from other motives that make them necessary fear of calamity hope of good fortune fear of someones censure the desire for praise or exaltation the wish for gratitude or goodwill payment to an official or the provision of sustenance all of this is conducted on the basis of calculation and assessment the gifts of the commander of the faithful however rise above all of that for gifts given for any of the reasons named above cannot truly be called generosity virtue or beneficence they amount to either the discharge of a past obligation or an advance toward a future one to delay what one owes and fulfill rights late is blameworthy and miserly and to advance money in expectation of future benefit is neither generosity nor virtue nor is anything given in connection with a debt counted as generosity nobility or virtue the gifts of god glory be to him rise above all of that for god is under no obligation to give anyone anything and he seeks no reward from any of his creatures in the same way the commander of the faithful does not give to anyone for any of the reasons named nor does he seek recompense for it god the exalted said regarding the commander of the faithful ali b abi talib', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 37, NULL, '"We do not desire either reward or gratitude from them."', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'we do not desire either reward or gratitude from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 38, NULL, 'Rather, he bestows upon them freely, out of generosity, nobility, and virtue, following the actions of God the Exalted with His creation.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'rather he bestows upon them freely out of generosity nobility and virtue following the actions of god the exalted with his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 39, NULL, 'Were people to view the actions of the Commander of the Faithful in this light, they would not fall into confusion. Yet some look at him with short sight, judging his actions by the standard of other human beings, while others look at him with excess, claiming divinity for him. The actions of the Commander of the Faithful rise above both of these positions. He is, rather, the Universal Vicegerent of God among His worshippers (الْخَلِيفَةُ الْكُلِّيُّ لِلَّهِ تَعَالَى عَلَى عِبَادِهِ).', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'were people to view the actions of the commander of the faithful in this light they would not fall into confusion yet some look at him with short sight judging his actions by the standard of other human beings while others look at him with excess claiming divinity for him the actions of the commander of the faithful rise above both of these positions he is rather the universal vicegerent of god among his worshippers الخليفه الكلي لله تعالي علي عباده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 40, NULL, 'Just as God the Exalted has hidden from mankind the reasons for creating the world while making plain the reasons of religion and the means of attaining it, He also made plain the ways of attaining His pleasure, clarifying it through the words of His Prophet. He gave knowledge and wisdom to those who deserved it and denied it to those who did not, and', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'just as god the exalted has hidden from mankind the reasons for creating the world while making plain the reasons of religion and the means of attaining it he also made plain the ways of attaining his pleasure clarifying it through the words of his prophet he gave knowledge and wisdom to those who deserved it and denied it to those who did not and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 41, NULL, '"He made before them a barrier and behind them a barrier,"', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'he made before them a barrier and behind them a barrier', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 42, NULL, 'setting up signposts of guidance and the summons of the proof and the guide to the bounty of the hereafter. He disclosed the ways of attaining it and opened its gates, so that whoever deserves it attains it and whoever does not deserve it misses it, in utmost wisdom. Likewise, the Commander of the Faithful hid the means of attaining worldly fortune through him, giving it to both those who deserve it and those who do not. He made plain the means of attaining religion, knowledge, and wisdom, and bestowed them upon those who deserved them, neither withholding them nor being miserly. He bestowed favors upon people abundantly, giving more than anyone could ever give in any time or age. He also withheld favors from the undeserving, distinguishing between the people of truth (أَهْلُ الْحَقّ) and the people of falsehood (أَهْلُ الْبَاطِل), following the ways of God the Exalted in governing the world and religion alike, and in building both this present world and the world to come.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'setting up signposts of guidance and the summons of the proof and the guide to the bounty of the hereafter he disclosed the ways of attaining it and opened its gates so that whoever deserves it attains it and whoever does not deserve it misses it in utmost wisdom likewise the commander of the faithful hid the means of attaining worldly fortune through him giving it to both those who deserve it and those who do not he made plain the means of attaining religion knowledge and wisdom and bestowed them upon those who deserved them neither withholding them nor being miserly he bestowed favors upon people abundantly giving more than anyone could ever give in any time or age he also withheld favors from the undeserving distinguishing between the people of truth اهل الحق and the people of falsehood اهل الباطل following the ways of god the exalted in governing the world and religion alike and in building both this present world and the world to come', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 43, NULL, 'We ask God to bestow upon us gratitude for what He has blessed us with in word, deed, and intention, and to grant us success in obedience to the lord of the age and time (وَلِيُّ الْعَصْرِ وَالزَّمَانِ). May He provide us with the means to strive on his behalf with our hands, our tongues, and our hearts. May God open the whole world to him and, through his sword, cleanse the earth of polytheism (الشِّرْك), unbelief (اَلْكُفْر), and hypocrisy (اَلنِّفَاق), by his bounty and generosity.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'we ask god to bestow upon us gratitude for what he has blessed us with in word deed and intention and to grant us success in obedience to the lord of the age and time ولي العصر والزمان may he provide us with the means to strive on his behalf with our hands our tongues and our hearts may god open the whole world to him and through his sword cleanse the earth of polytheism الشرك unbelief الكفر and hypocrisy النفاق by his bounty and generosity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 44, NULL, 'This servant begs and longs for the blessings of the Commander of the Faithful, and seeks the supreme command (الْأَمْرُ الْعَالِي) to examine what the servant has gathered and compiled, to grant him leave for whatever is sound and correct, and to draw his attention to any mistakes, so that the servant may thank him for deepening his insight and certainty, and so that this may become a means of guidance and evidence for those who seek to be guided, and a proof against those who deny.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'this servant begs and longs for the blessings of the commander of the faithful and seeks the supreme command الامر العالي to examine what the servant has gathered and compiled to grant him leave for whatever is sound and correct and to draw his attention to any mistakes so that the servant may thank him for deepening his insight and certainty and so that this may become a means of guidance and evidence for those who seek to be guided and a proof against those who deny', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 45, NULL, 'Praise be to God, the praise of the thankful, the mindful, and the pious, and prayers upon His Messenger, our master Muhammad, and all his progeny.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'praise be to god the praise of the thankful the mindful and the pious and prayers upon his messenger our master muhammad and all his progeny', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'chapter', 'god''s vicegerent in his time', '9. God''s Vicegerent in His Time', 46, NULL, 'Editorial note (tradition-grounded). A modern reader may find the chapter''s talk of "six stages of development from sperm to fully formed creature" and a completing "seventh stage" hard to place. It draws on an image the wider tradition preserves: a Quranic passage describing the human being created first from an extract of clay, then as a Nutfah — the mingled drops — lodged in a safe lodging, and carried through successive stages of the womb. A related teaching also holds that the soul''s powers unfold by station rather than all at once: in the womb the fetus has only the power to grow (the vegetative soul), and the five senses activate only later. Read against this, the chapter''s claim becomes clearer — as bodily life is completed only in its final stage, so the spiritual "seventh stage," the fullness of recompense, is what it says the Commander of the Faithful brings to completion.', '', NULL, NULL, NULL, NULL, 'degrees of excellence 9 gods vicegerent in his time', 'editorial note tradition grounded a modern reader may find the chapters talk of six stages of development from sperm to fully formed creature and a completing seventh stage hard to place it draws on an image the wider tradition preserves a quranic passage describing the human being created first from an extract of clay then as a nutfah the mingled drops lodged in a safe lodging and carried through successive stages of the womb a related teaching also holds that the souls powers unfold by station rather than all at once in the womb the fetus has only the power to grow the vegetative soul and the five senses activate only later read against this the chapters claim becomes clearer as bodily life is completed only in its final stage so the spiritual seventh stage the fullness of recompense is what it says the commander of the faithful brings to completion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'episode', NULL, 'The Imamate, Pole of Religion', 0, 1, 'The Imamate, Pole of Religion The treatise opens, and al-Naysaburi begins with a claim most believers would find backwards: the true pole of religion is not the messenger who brings the law but the imam who guards it — and you cannot affirm the one without first affirming the other. He argues that the world is never for a moment without an imam while the messenger comes and goes; that God Himself called the imam a messenger and the messenger an imam; and that the necessity of the imamate is written into intellect and human nature as surely as the necessity of the Creator. Then, having conceded that people dispute the imam exactly as they disputed God, he lays down the hinge of the whole book: that reality gives two witnesses to the truth — one established by sacred law and one compelled by nature, the horizons and the souls themselves — and that when both testify and the intellect weighs them without bias, the truth of the imamate becomes impossible to miss.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'episode', NULL, 'The Peak of Every Kind', 0, 2, 'The Peak of Every Kind Episode 1 sketched the ladder of degrees of excellence as an abstract engine; here al-Naysaburi builds it himself, rung by rung, out of the raw materials of the world. Fire is the summit of the elements, the sun of the planets, gold of the metals, and — finer still — the red ruby that comes through fire and water unchanged is the crown of all jewels; wheat is the peak of the grains and the date palm of the trees, so like a human being that it has male and female and must be fertilized. Each choice quietly names a virtue of the imam: the one who gives light, who cannot be corrupted, who nourishes and heals. And every bright image has its dark twin — the healing antidote against the fatal poison, the sweet tree against the thorned, the fragrant plant against the putrid — by which the usurpers of the imamate are shown for what they are. The climb ends where it always pointed: humankind is the summit of all creation, and the imam is the summit of humankind, without whom, al-Naysaburi warns, a person sinks beneath the beasts.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'episode', NULL, 'The Imam''s Authority', 0, 3, 'The Imam''s Authority The ladder has reached its summit; now al-Naysaburi asks what the summit authorizes, and his answers are among the boldest in the book. All the worlds, he argues, were made for humanity and humanity for the imams, so that whatever anyone takes without the imam''s leave is a kind of theft, and all benefit is, in the end, a return to its source. He grounds this in a ladder of spirits: as the plant outranks the earth by the spirit of growth and the animal outranks the plant by sensation and the human outranks the animal by reason, so the imam is given further spirits — the sanctified and the creative — that widen his dominion over all humankind. From there he presses two more arguments: that the imam is absolutely wise, so that to charge him with a foolish act is to fall out of the faith; and that reason alone, without a line of scripture, shows the world must have one supreme leader who is the best, most knowing, and most pure of all — the shepherd without whom the flock is lost, the head without which the body is a corpse.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'episode', NULL, 'Worship and Law Without the Imam', 0, 4, 'Worship and Law Without the Imam Having proved the imam''s authority from nature and reason, al-Naysaburi now finds it hidden inside the everyday obligations of Islam. Human beings, he argues, are born knowing nothing and must be taught in a chain that ends in one taught by God alone — so the imam is God''s standing proof over creation, and the perfect circle, the number one, and the indivisible point all image his uniqueness. Then he turns to the rites: the qibla you face and the leader you follow in prayer share the very root of the word imam, and the congregation multiplies your reward because it is performed behind him; the pilgrimage begins with an intention aimed at him, and the Ka''ba in its barren valley teaches that he is reached only through hardship. Alms may be collected only by the imam, holy war waged only under his banner, and the prescribed penalties carried out only by his authority — so that the leaders who claim the office, trusted by their followers with blood and property but not with alms, and bound by their own rule that a sinner cannot judge or testify, refute themselves. What remains, al-Naysaburi concludes, is that the true imamate belongs to the purified progeny of the Prophet''s house.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'episode', NULL, 'Prophets, Symbols, and the Caliphs', 0, 5, 'Prophets, Symbols, and the Caliphs Al-Naysaburi turns from doctrine to history and finds the imamate written across it. If even a world holding none but sinless angels was given a vicegerent — over the angels'' own objection — then no world of flawed human beings can go without one, and the imamate can never be settled by choice; had it been, the choice would have belonged to the angels. Noah''s ark was the imam, and Noah named his heir by designation; and each later prophet''s direction of prayer marks where the living guide stands — Moses toward Jerusalem, Jesus toward the east, and Muhammad turning the people back to the Ka''ba that Abraham and Ishmael built, a sign that the imamate had returned to the house of Abraham through Ishmael''s line. Then al-Naysaburi measures the first caliphs against the three virtues God honors — knowledge, holy struggle, and piety — and finds them wanting on the record of their own words: the flight at Hunayn, Abu Bakr''s confession that he was not the best among them, and Umar''s admission that the first oath had been a hasty slip.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('degrees-of-excellence', 'episode', NULL, 'The Imam Who Mirrors God', 0, 6, 'The Imam Who Mirrors God The treatise ends where its ladder always pointed. Every ordered domain has its peak, so the imams too must have one — and that utmost degree, al- Naysaburi says, is the Commander of the Faithful, Ali b. Abi Talib, the summit of all summits, the perfector who gathers into himself the merits of every prophet and imam before him, as the heart gives life to the limbs; and the reigning imam of each age continues and completes that summit for his own time. Then comes the book''s most demanding claim: that the imam''s dealing with people mirrors God''s own. As God gives to the pious and the impious alike, conceals the means of worldly gain so no single path corrupts the world, and moves between nearness and distance to keep His servants between fear and hope, so does the imam — his gifts, unlike any monarch''s, seeking no return at all. Between those who reduce him to an ordinary ruler and those who exaggerate him into a god, al-Naysaburi sets the true measure: the Universal Vicegerent of God, a shadow that imitates in every detail the one who casts it. The series closes on the author''s own prayer of gratitude and striving.
